export const CONTENIDOS: Record<string, string> = {
  "src/app/tutorial/01-componentes/leccion.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 1 — Anatomía de un Componente\n *\n * Un componente tiene 3 partes:\n *   1. La clase TypeScript (esta clase)\n *   2. La plantilla HTML (propiedad `template`)\n *   3. Los estilos CSS (propiedad `styles`)\n *\n * Abrí http://localhost:4200/tutorial/01 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/01/solucion\n */\n@Component({\n  selector: 'leccion-01',\n  template: `\n    <!-- TODO 1: Cambiá el texto \"Hello\" por \"Hello Universe\" -->\n    <p>Hello</p>\n  `,\n  styles: `\n    :host {\n      /* TODO 2: Cambiá el color de \"cornflowerblue\" a la variable de acento del tema: var(--acento) */\n      color: cornflowerblue;\n    }\n  `,\n})\nexport class Leccion01 {}\n",
  "src/app/tutorial/01-componentes/README.md": "# Lección 1 — Anatomía de un Componente\n\n> Original: [Components in Angular](https://v20.angular.dev/tutorials/learn-angular/1-components-in-angular)\n\nLos componentes son los bloques fundamentales de cualquier aplicación Angular. Cada componente tiene tres partes:\n\n- Clase TypeScript\n- Plantilla HTML\n- Estilos CSS\n\nEn esta lección vas a aprender a actualizar la plantilla y los estilos de un componente.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/01>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/01/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/01-componentes/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Actualizar la plantilla del componente\n\nCambiá la propiedad `template` para que diga `Hello Universe`:\n\n```ts\ntemplate: `\n  Hello Universe\n`,\n```\n\nAl cambiar la plantilla HTML, la vista se actualiza con tu mensaje. Vamos un paso más allá: cambiá el color del texto.\n\n### 2. Actualizar los estilos del componente\n\nCambiá el valor de `styles` y modificá la propiedad `color` de `cornflowerblue` a la variable de acento del tema, `var(--acento)`:\n\n```ts\nstyles: `\n  :host {\n    color: var(--acento);\n  }\n`,\n```\n\nAl mirar la vista, vas a ver que el color del texto cambió.\n\n## Para cerrar\n\nEn Angular podés usar todo el HTML y CSS soportado por el navegador. Si querés, podés guardar tu plantilla y estilos en archivos separados (con `templateUrl` y `styleUrl`), como se hace en el componente raíz `src/app/app.ts`.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/01/solucion` y seguí con la [Lección 2](http://localhost:4200/tutorial/02).\n",
  "src/app/tutorial/02-clase-del-componente/leccion.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 2 — Actualizar la Clase del Componente\n *\n * La lógica del componente vive en su clase TypeScript y se muestra\n * en la plantilla usando interpolación: {{ }}.\n *\n * Abrí http://localhost:4200/tutorial/02 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/02/solucion\n */\n@Component({\n  selector: 'leccion-02',\n  template: ` Hello `,\n})\nexport class Leccion02 {\n  // TODO 1: Agregá una propiedad llamada `city` con el valor 'San Francisco'\n}\n",
  "src/app/tutorial/02-clase-del-componente/README.md": "# Lección 2 — Actualizar la Clase del Componente\n\n> Original: [Updating the Component Class](https://v20.angular.dev/tutorials/learn-angular/2-updating-the-component-class)\n\nEn Angular, la lógica y el comportamiento de un componente se definen en su clase TypeScript.\n\nEn esta lección vas a aprender a actualizar la clase del componente y a usar la [interpolación](https://v20.angular.dev/guide/templates/binding#render-dynamic-text-with-text-interpolation), que te permite mostrar texto dinámico en la plantilla.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/02>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/02/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/02-clase-del-componente/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Agregar una propiedad llamada `city`\n\nActualizá la clase del componente agregando una propiedad llamada `city` a la clase `Leccion02`:\n\n```ts\nexport class Leccion02 {\n  city = 'San Francisco';\n}\n```\n\nLa propiedad `city` es de tipo `string`, pero podés omitir el tipo gracias a la [inferencia de tipos de TypeScript](https://www.typescriptlang.org/docs/handbook/type-inference.html). La propiedad `city` puede usarse dentro de la clase y también referenciarse en la plantilla del componente.\n\nPara usar una propiedad de la clase en la plantilla, tenés que usar la sintaxis `{{ }}`.\n\n### 2. Actualizar la plantilla del componente\n\nActualizá la propiedad `template` para que coincida con el siguiente HTML:\n\n```ts\ntemplate: `Hello {{ city }}`,\n```\n\nEste es un ejemplo de interpolación y forma parte de la sintaxis de plantillas de Angular. Te permite hacer mucho más que poner texto dinámico en una plantilla: también podés usar esta sintaxis para llamar funciones, escribir expresiones y más.\n\n### 3. Más práctica con la interpolación\n\nProbá esto: agregá otro par de `{{ }}` con el contenido `1 + 1`:\n\n```ts\ntemplate: `Hello {{ city }}, {{ 1 + 1 }}`,\n```\n\nAngular evalúa el contenido de los `{{ }}` y muestra el resultado en la plantilla.\n\n## Para cerrar\n\nEsto es solo el comienzo de lo que se puede hacer con las plantillas de Angular: seguí aprendiendo para descubrir más.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/02/solucion` y seguí con la [Lección 3](http://localhost:4200/tutorial/03).\n",
  "src/app/tutorial/03-componer-componentes/leccion.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 3 — Componer Componentes\n *\n * Un componente se usa dentro de otro a través de su `selector`,\n * que se escribe en la plantilla como una etiqueta HTML.\n *\n * Abrí http://localhost:4200/tutorial/03 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/03/solucion\n */\n@Component({\n  selector: 'leccion-03-user',\n  template: ` Username: {{ username }} `,\n})\n\nexport class Leccion03User {\n  username = 'youngTech';\n}\n\n@Component({\n  selector: 'leccion-03',\n  template: `\n    <!-- TODO 1: Mostrá el componente de usuario acá con <leccion-03-user /> -->\n\n    <p>Acá va a aparecer el componente de usuario...</p>\n  `,\n  imports: [\n    // TODO 1: Agregá Leccion03User a los imports para poder usarlo en la plantilla\n  ],\n})\nexport class Leccion03 {}\n",
  "src/app/tutorial/03-componer-componentes/README.md": "# Lección 3 — Componer Componentes\n\n> Original: [Composing Components](https://v20.angular.dev/tutorials/learn-angular/3-composing-components)\n\nYa aprendiste a actualizar la plantilla, la lógica y los estilos de un componente, pero ¿cómo se usa un componente en tu aplicación?\n\nLa propiedad `selector` de la configuración del componente te da un nombre para referenciar el componente en otra plantilla. Usás el `selector` como una etiqueta HTML: por ejemplo, si el selector es `leccion-03-user`, en la plantilla se escribe `<leccion-03-user />`.\n\nEn este ejemplo hay dos componentes: `Leccion03User` y `Leccion03`.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/03>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/03/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/03-componer-componentes/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Agregar una referencia al componente `Leccion03User`\n\nActualizá la plantilla de `Leccion03` para incluir una referencia al componente `Leccion03User`, que usa el selector `leccion-03-user`. Asegurate de agregar `Leccion03User` al arreglo `imports` de `Leccion03`; eso lo hace disponible para usarlo en la plantilla de `Leccion03`.\n\n```ts\ntemplate: `<leccion-03-user />`,\nimports: [Leccion03User],\n```\n\nEl componente ahora muestra el mensaje `Username: youngTech`. Podés actualizar el código de la plantilla para incluir más marcado.\n\n### 2. Agregar más marcado HTML\n\nComo podés usar cualquier marcado HTML que quieras en una plantilla, probá actualizar la plantilla de `Leccion03` para incluir más elementos HTML. Este ejemplo agrega un elemento `<section>` como padre del elemento `<leccion-03-user>`.\n\n```html\ntemplate: `\n<section><leccion-03-user /></section>\n`,\n```\n\n## Para cerrar\n\nPodés usar todo el HTML y tantos componentes como necesites para dar vida a tu idea de app. Incluso podés tener varias copias del mismo componente en la misma página.\n\nEso nos lleva a la siguiente pregunta: ¿cómo mostrarías un componente de forma condicional según datos? Andá a la siguiente sección para descubrirlo.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/03/solucion` y seguí con la [Lección 4](http://localhost:4200/tutorial/04).\n",
  "src/app/tutorial/04-control-flow-if/leccion.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 4 — Control de Flujo: @if\n *\n * Con @if / @else podés mostrar u ocultar partes de la plantilla\n * según una condición, sin necesidad de directivas.\n *\n * Abrí http://localhost:4200/tutorial/04 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/04/solucion\n */\n@Component({\n  selector: 'leccion-04',\n  template: `\n    <!-- TODO 2: Envolver este span en un bloque @if que lo muestre solo si isServerRunning es true -->\n    <span>Yes, the server is running</span>\n    <!-- TODO 3: Agregar un bloque @else que muestre \"No, the server is not running\" -->\n  `,\n})\nexport class Leccion04 {\n  // TODO 1: Agregá acá la propiedad booleana isServerRunning con valor inicial true\n}\n",
  "src/app/tutorial/04-control-flow-if/README.md": "# Lección 4 — Control de Flujo: `@if`\n\n> Original: [Control Flow in Components - `@if`](https://v20.angular.dev/tutorials/learn-angular/4-control-flow-if)\n\nDecidir qué mostrar en la pantalla es una tarea común en el desarrollo de aplicaciones. Muchas veces, la decisión se toma programáticamente usando condiciones.\n\nPara expresar visualizaciones condicionales en las plantillas, Angular usa la sintaxis `@if`.\n\nEn esta lección vas a aprender a usar condicionales en las plantillas.\n\nLa sintaxis que permite mostrar elementos de forma condicional en una plantilla es `@if`. Acá hay un ejemplo de cómo usarla en un componente:\n\n```ts\n@Component({\n  ...\n  template: `\n    @if (isLoggedIn) {\n      <p>Welcome back, Friend!</p>\n    }\n  `,\n})\nexport class App {\n  isLoggedIn = true;\n}\n```\n\nDos cosas a tener en cuenta:\n\n- Hay un prefijo `@` para el `if` porque es un tipo especial de sintaxis llamada [sintaxis de plantillas de Angular](https://v20.angular.dev/guide/templates)\n- Para aplicaciones que todavía usan `*ngIf`, consultá la [documentación de Angular sobre directivas estructurales](https://v20.angular.dev/guide/directives/structural-directives)\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/04>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/04/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/04-control-flow-if/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Crear una propiedad llamada `isServerRunning`\n\nEn la clase `Leccion04`, agregá una propiedad `boolean` llamada `isServerRunning` con el valor inicial `true`.\n\n### 2. Usar `@if` en la plantilla\n\nActualizá la plantilla para mostrar el mensaje `Yes, the server is running` si el valor de `isServerRunning` es `true`.\n\n### 3. Usar `@else` en la plantilla\n\nAngular ahora soporta sintaxis nativa de plantillas para definir el caso contrario con la sintaxis `@else`. Actualizá la plantilla para mostrar el mensaje `No, the server is not running` como caso `@else`.\n\nAcá hay un ejemplo:\n\n```html\ntemplate: `\n@if (isServerRunning) {\n  ...\n} @else {\n  ...\n}\n`;\n```\n\nAgregá tu código para completar el marcado que falta.\n\n## Para cerrar\n\nEste tipo de funcionalidad se llama control de flujo condicional. A continuación vas a aprender cómo repetir elementos en una plantilla.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/04/solucion` y seguí con la [Lección 5](http://localhost:4200/tutorial/05).\n",
  "src/app/tutorial/05-control-flow-for/leccion.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 5 — Control de Flujo: @for\n *\n * Con @for podés repetir elementos de la plantilla a partir de\n * una colección de datos.\n *\n * Abrí http://localhost:4200/tutorial/05 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/05/solucion\n */\n@Component({\n  selector: 'leccion-05',\n  template: `\n    <!-- TODO 2: Usá un bloque @for para mostrar el nombre de cada usuario en un <p> (no te olvides del track) -->\n    <p>Acá van a aparecer los usuarios...</p>\n  `,\n})\nexport class Leccion05 {\n  // TODO 1: Agregá acá la propiedad `users` con los usuarios y sus nombres\n}\n",
  "src/app/tutorial/05-control-flow-for/README.md": "# Lección 5 — Control de Flujo: `@for`\n\n> Original: [Control Flow in Components - `@for`](https://v20.angular.dev/tutorials/learn-angular/5-control-flow-for)\n\nA menudo, al construir aplicaciones web, necesitás repetir un fragmento de código una cantidad específica de veces; por ejemplo, dado un arreglo de nombres, quizás quieras mostrar cada nombre en una etiqueta `<p>`.\n\nEn esta lección vas a aprender a usar `@for` para repetir elementos en una plantilla.\n\nLa sintaxis que permite repetir elementos en una plantilla es `@for`. Acá hay un ejemplo de cómo usarla en un componente:\n\n```ts\n@Component({\n  ...\n  template: `\n    @for (os of operatingSystems; track os.id) {\n      {{ os.name }}\n    }\n  `,\n})\nexport class App {\n  operatingSystems = [{id: 'win', name: 'Windows'}, {id: 'osx', name: 'macOS'}, {id: 'linux', name: 'Linux'}];\n}\n```\n\nDos cosas a tener en cuenta:\n\n- Hay un prefijo `@` para el `for` porque es una sintaxis especial llamada [sintaxis de plantillas de Angular](https://v20.angular.dev/guide/templates)\n- Para aplicaciones que todavía usan `*ngFor`, consultá la [documentación de Angular sobre directivas estructurales](https://v20.angular.dev/guide/directives/structural-directives)\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/05>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/05/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/05-control-flow-for/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Agregar la propiedad `users`\n\nEn la clase `Leccion05`, agregá una propiedad llamada `users` que contenga usuarios y sus nombres:\n\n```ts\n[\n  {id: 0, name: 'Sarah'},\n  {id: 1, name: 'Amy'},\n  {id: 2, name: 'Rachel'},\n  {id: 3, name: 'Jessica'},\n  {id: 4, name: 'Poornima'},\n];\n```\n\n### 2. Actualizar la plantilla\n\nActualizá la plantilla para mostrar el nombre de cada usuario en un elemento `p` usando la sintaxis de plantillas `@for`:\n\n```html\n@for (user of users; track user.id) {\n  <p>{{ user.name }}</p>\n}\n```\n\nNOTA: el uso de `track` es obligatorio; podés usar el `id` u otro identificador único.\n\n## Para cerrar\n\nEste tipo de funcionalidad se llama control de flujo. A continuación vas a aprender a personalizar y comunicarte con los componentes; por cierto, ¡vas muy bien hasta ahora!\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/05/solucion` y seguí con la [Lección 6](http://localhost:4200/tutorial/06).\n",
  "src/app/tutorial/06-property-binding/leccion.css": "div {\n    border: solid 2px var(--acento);\n    padding: 5px;\n    height: 20px;\n    border-radius: 4px;\n}\n",
  "src/app/tutorial/06-property-binding/leccion.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 6 — Property Binding\n *\n * Con la sintaxis de corchetes [propiedad] podés asignar dinámicamente\n * el valor de una propiedad de la clase a un atributo del HTML.\n *\n * Abrí http://localhost:4200/tutorial/06 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/06/solucion\n */\n@Component({\n  selector: 'leccion-06',\n  styleUrl: './leccion.css',\n  template: `\n    <!-- TODO 2: Bindeá el atributo contentEditable del div a la propiedad isEditable usando corchetes: [contentEditable]=\"isEditable\" -->\n    <div contentEditable=\"false\"></div>\n  `,\n})\nexport class Leccion06 {\n  // TODO 1: Agregá acá la propiedad isEditable con valor inicial true\n}\n",
  "src/app/tutorial/06-property-binding/README.md": "# Lección 6 — Property Binding\n\n> Original: [Property Binding in Angular](https://v20.angular.dev/tutorials/learn-angular/6-property-binding)\n\nEl property binding en Angular te permite asignar valores a propiedades de elementos HTML, componentes de Angular y más.\n\nUsá property binding para asignar dinámicamente valores a propiedades y atributos. Podés hacer cosas como activar o desactivar funciones de un botón, definir rutas de imágenes programáticamente y compartir valores entre componentes.\n\nEn esta lección vas a aprender a usar property binding en las plantillas.\n\nPara bindear el atributo de un elemento, envolvé el nombre del atributo en corchetes. Acá hay un ejemplo:\n\n```html\n<img alt=\"photo\" [src]=\"imageURL\" />\n```\n\nEn este ejemplo, el valor del atributo `src` queda bindeado a la propiedad de clase `imageURL`. El valor que tenga `imageURL` se asigna como atributo `src` de la etiqueta `img`.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/06>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/06/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/06-property-binding/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Agregar una propiedad llamada `isEditable`\n\nActualizá el código de `leccion.ts` agregando a la clase `Leccion06` una propiedad llamada `isEditable` con el valor inicial `true`:\n\n```ts\nexport class Leccion06 {\n  isEditable = true;\n}\n```\n\n### 2. Bindear `contentEditable`\n\nA continuación, bindeá el atributo `contentEditable` del `div` a la propiedad `isEditable` usando la sintaxis de [corchetes]:\n\n```ts\n@Component({\n  ...\n  template: `<div [contentEditable]=\"isEditable\"></div>`,\n})\n```\n\nEl div ahora es editable. ¡Buen trabajo! 🎉\n\n## Para cerrar\n\nEl property binding es una de las muchas funcionalidades poderosas de Angular. Si querés aprender más, mirá [la documentación de Angular](https://v20.angular.dev/guide/templates/binding#css-class-and-style-property-bindings).\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/06/solucion` y seguí con la [Lección 7](http://localhost:4200/tutorial/07).\n",
  "src/app/tutorial/07-event-handling/leccion.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 7 — Manejo de eventos\n *\n * En Angular te suscribís a eventos con la sintaxis de paréntesis `()`.\n * Por ejemplo: `<button (click)=\"greet()\">` ejecuta `greet()` en cada clic.\n *\n * Abrí http://localhost:4200/tutorial/07 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/07/solucion\n */\n@Component({\n  selector: 'leccion-07',\n  template: `\n    <!-- TODO 2: Suscribite al evento \"mouseover\" de este section: <section (mouseover)=\"showSecretMessage()\"> -->\n\n    <section>\n      Hay un mensaje secreto para vos, pasá el mouse para revelarlo 👀\n      {{ message }}\n    </section>\n  `,\n})\nexport class Leccion07 {\n  message = '';\n\n  showSecretMessage() {\n    // TODO 1: Completá el cuerpo del método con: this.message = 'Way to go 🚀';\n  }\n}\n",
  "src/app/tutorial/07-event-handling/README.md": "# Lección 7 — Manejo de eventos\n\n> Original: [Event handling](https://v20.angular.dev/tutorials/learn-angular/7-event-handling)\n\nEl manejo de eventos es lo que habilita las funcionalidades interactivas en las aplicaciones web. Te da la posibilidad, como desarrollador, de responder a acciones del usuario como pulsaciones de botones, envíos de formularios y más.\n\nEn esta lección vas a aprender a agregar un manejador de eventos.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/07>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/07/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/07-event-handling/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\nEn Angular te suscribís a eventos con la sintaxis de paréntesis `()`. En un elemento dado, envolvé el evento al que querés suscribirte entre paréntesis y asignale un manejador de eventos. Considerá este ejemplo con un `button`:\n\n```ts\n@Component({\n  ...\n  template: `<button (click)=\"greet()\">`\n})\nexport class App {\n  greet() {\n    console.log('Hello, there 👋');\n  }\n}\n```\n\nEn este ejemplo, la función `greet()` se ejecuta cada vez que se hace clic en el botón. Tené en cuenta que la sintaxis `greet()` incluye los paréntesis al final.\n\nBien, ahora te toca a vos:\n\n### 1. Agregar un manejador de eventos\n\nEn la clase `Leccion07`, completá el cuerpo del método `showSecretMessage()` con el siguiente código:\n\n```ts\nthis.message = 'Way to go 🚀';\n```\n\n### 2. Suscribirse al evento de la plantilla\n\nActualizá el código de la plantilla en `leccion.ts` para suscribirte al evento `mouseover` del elemento `section`:\n\n```html\n<section (mouseover)=\"showSecretMessage()\">\n```\n\nY con unos pocos pasos en el código creaste tu primer manejador de eventos en Angular. Parece que ya le vas agarrando la mano. Seguí así.\n\n## Para cerrar\n\nPasá el mouse sobre la sección y mirá cómo aparece el mensaje secreto. Compará tu resultado con la solución en `/tutorial/07/solucion` y seguí con la [Lección 8](http://localhost:4200/tutorial/08).\n",
  "src/app/tutorial/08-input/leccion.ts": "import {Component} from '@angular/core';\nimport {Leccion08User} from './user';\n\n/**\n * LECCIÓN 8 — Propiedades input de componentes\n *\n * Los valores de un `input` se establecen en las plantillas con la\n * sintaxis de atributo: `<leccion-08-user name=\"Simran\" />`\n *\n * Abrí http://localhost:4200/tutorial/08 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/08/solucion\n */\n@Component({\n  selector: 'leccion-08',\n  template: `\n    <!-- TODO 2: Pasá la propiedad name con el valor \"Simran\": <leccion-08-user name=\"Simran\" /> -->\n\n    <leccion-08-user />\n  `,\n  imports: [Leccion08User],\n})\nexport class Leccion08 {}\n",
  "src/app/tutorial/08-input/README.md": "# Lección 8 — Propiedades input de componentes\n\nA veces, al desarrollar una aplicación, necesitás enviar datos hacia un componente. Estos datos se pueden usar para personalizar un componente o para enviar información de un componente padre a uno hijo.\n\nAngular usa un concepto llamado `input` (entrada). Es similar a `props` en otros frameworks. Para crear una propiedad `input`, usá la función `input()`.\n\nEn esta lección vas a aprender a usar la función `input()` para enviar información a los componentes.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/08>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/08/solucion>\n\n## Archivos de trabajo\n\n- `src/app/tutorial/08-input/user.ts`\n- `src/app/tutorial/08-input/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\nPara crear una propiedad `input`, agregá la función `input()` para inicializar una propiedad de la clase de un componente:\n\n```ts\n// user.ts\nclass User {\n  occupation = input<string>();\n}\n```\n\nCuando quieras pasar un valor a través de un `input`, los valores se pueden establecer en las plantillas usando la sintaxis de atributo. Acá hay un ejemplo:\n\n```ts\n// app.ts\n@Component({\n  ...\n  template: `<app-user occupation=\"Angular Developer\"></app-user>`\n})\nexport class App {}\n```\n\nLa función `input` devuelve un `InputSignal`. Podés leer el valor invocando la señal:\n\n```ts\n// user.ts\n@Component({\n  ...\n  template: `<p>The user's occupation is {{occupation()}}</p>`\n})\n```\n\n### 1. Definir una propiedad `input()`\n\nActualizá el código de `user.ts` para definir una propiedad `input` en `Leccion08User` llamada `name` con tipo `string`. Por ahora, no establezcas un valor inicial e invocá `input()` sin argumentos. Asegurate de actualizar la plantilla para invocar e interpolar la propiedad `name` al final de la oración.\n\n### 2. Pasar un valor a la propiedad `input`\n\nActualizá el código de `leccion.ts` para enviar la propiedad `name` con el valor `\"Simran\"`.\n\nCuando el código se haya actualizado correctamente, la app va a mostrar `El nombre del usuario es Simran`.\n\n## Para cerrar\n\nEsto es genial, pero es solo una dirección de la comunicación entre componentes. ¿Qué pasa si querés enviar información y datos a un componente padre desde uno hijo? Descubrilo en la próxima lección.\n\nP.D.: lo estás haciendo muy bien — seguí así 🎉\n\nCompará tu resultado con la solución en `/tutorial/08/solucion` y seguí con la [Lección 9](http://localhost:4200/tutorial/09).\n",
  "src/app/tutorial/08-input/user.ts": "import {Component, input} from '@angular/core';\n\n/**\n * LECCIÓN 8 — Componente hijo que recibe datos con `input()`\n *\n * La función `input()` devuelve un `InputSignal`: leé el valor\n * invocándola como una señal, por ejemplo `{{ name() }}`.\n */\n@Component({\n  selector: 'leccion-08-user',\n  template: `\n    <!-- TODO 1: Definí una propiedad input llamada name (tipo string) en la clase e\n    interpolá su valor al final de la oración: <p>El nombre del usuario es {{ name() }}</p> -->\n\n    <p>El nombre del usuario es</p>\n\n  `,\n})\nexport class Leccion08User {}\n",
  "src/app/tutorial/09-output/child.ts": "import {Component, output} from '@angular/core';\n\n/**\n * LECCIÓN 9 — Componente hijo que notifica al padre con `output()`\n *\n * Una propiedad `output` se declara con la función `output()` y se\n * dispara con el método `emit`, que recibe el valor del evento.\n */\n@Component({\n  selector: 'leccion-09-child',\n  styles: `\n    .btn {\n      padding: 5px;\n    }\n  `,\n  template: ` <button class=\"btn\" (click)=\"addItem()\">Agregar ítem</button> `,\n})\nexport class Leccion09Child {\n  // TODO 1: Agregá una propiedad de salida llamada addItemEvent con tipo string: readonly addItemEvent = output<string>();\n\n  addItem() {\n    // TODO 2: Emití el evento con el valor '🐢': this.addItemEvent.emit('🐢');\n  }\n}\n",
  "src/app/tutorial/09-output/leccion.ts": "import {Component} from '@angular/core';\nimport {Leccion09Child} from './child';\n\n/**\n * LECCIÓN 9 — Propiedades output de componentes\n *\n * El componente hijo emite eventos con `output()` y el padre los escucha\n * con la sintaxis de paréntesis: `(addItemEvent)=\"addItem($event)\"`.\n *\n * Abrí http://localhost:4200/tutorial/09 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/09/solucion\n */\n@Component({\n  selector: 'leccion-09',\n  template: `\n    <!-- TODO 3: Escuchá el evento emitido por el hijo: <leccion-09-child (addItemEvent)=\"addItem($event)\" /> -->\n\n    <leccion-09-child />\n    <p>🐢 all the way down {{ items.length }}</p>\n  `,\n  imports: [Leccion09Child],\n})\nexport class Leccion09 {\n  items = new Array();\n\n  addItem(item: string) {\n    this.items.push(item);\n  }\n}\n",
  "src/app/tutorial/09-output/README.md": "# Lección 9 — Propiedades output de componentes\n\nAl trabajar con componentes, puede ser necesario notificar a otros componentes que algo pasó. Quizás se hizo clic en un botón, se agregó o quitó un ítem de una lista, u ocurrió alguna otra actualización importante. En este escenario, los componentes necesitan comunicarse con los componentes padres.\n\nAngular usa la función `output()` para habilitar este tipo de comportamiento.\n\nEn esta lección vas a aprender a usar la función `output()` para comunicar componentes.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/09>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/09/solucion>\n\n## Archivos de trabajo\n\n- `src/app/tutorial/09-output/child.ts`\n- `src/app/tutorial/09-output/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\nPara crear el camino de comunicación de los componentes hijos hacia los padres, usá la función `output` para inicializar una propiedad de la clase:\n\n```ts\n// child.ts\n@Component({...})\nclass Child {\n  incrementCountEvent = output<number>();\n}\n```\n\nAhora el componente puede generar eventos que el componente padre puede escuchar. Dispará eventos llamando al método `emit`:\n\n```ts\n// child.ts\nclass Child {\n  ...\n\n  onClick() {\n    this.count++;\n    this.incrementCountEvent.emit(this.count);\n  }\n}\n```\n\nLa función `emit` genera un evento con el mismo tipo definido en el `output`.\n\nBien, ahora te toca a vos. Completá el código siguiendo estas tareas:\n\n### 1. Agregar una propiedad `output()`\n\nActualizá `child.ts` agregando una propiedad de salida llamada `addItemEvent`, asegurándote de que el tipo de la salida sea `string`.\n\n### 2. Completar el método `addItem`\n\nEn `child.ts` actualizá el método `addItem`; usá el siguiente código como lógica:\n\n```ts\n// child.ts\naddItem() {\n  this.addItemEvent.emit('🐢');\n}\n```\n\n### 3. Actualizar la plantilla de `Leccion09`\n\nEn `leccion.ts` actualizá la plantilla para escuchar el evento emitido agregando el siguiente código:\n\n```html\n<leccion-09-child (addItemEvent)=\"addItem($event)\" />\n```\n\nAhora, el botón \"Agregar ítem\" agrega un nuevo ítem a la lista cada vez que se hace clic.\n\n## Para cerrar\n\n¡Wow, en este punto completaste los fundamentos de componentes! Impresionante 👏\n\nSeguí aprendiendo para desbloquear más funcionalidades geniales de Angular.\n\nCompará tu resultado con la solución en `/tutorial/09/solucion` y seguí con la [Lección 10](http://localhost:4200/tutorial/10).\n",
  "src/app/tutorial/10-deferrable-views/comments.ts": "import {Component} from '@angular/core';\n\n/**\n * LECCIÓN 10 — Componente de comentarios del post\n *\n * Este es el componente \"pesado\" que se carga de forma diferida\n * con el bloque `@defer` de la plantilla principal.\n */\n@Component({\n  selector: 'leccion-10-comments',\n  template: `\n    <ul>\n      <li>Building for the web is fantastic!</li>\n      <li>The new template syntax is great</li>\n      <li>I agree with the other comments!</li>\n    </ul>\n  `,\n})\nexport class Leccion10Comments {}\n",
  "src/app/tutorial/10-deferrable-views/leccion.ts": "import {Component} from '@angular/core';\nimport {Leccion10Comments} from './comments';\n\n/**\n * LECCIÓN 10 — Vistas diferibles (Deferrable Views)\n *\n * Los bloques `@defer`, `@placeholder` y `@loading` permiten cargar\n * partes de la plantilla de forma diferida, por ejemplo cuando el\n * contenido entra en el viewport: `@defer (on viewport) { ... }`.\n *\n * Abrí http://localhost:4200/tutorial/10 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/10/solucion\n */\n@Component({\n  selector: 'leccion-10',\n  template: `\n    <div>\n      <h1>Lo que pienso de Angular</h1>\n      <!-- TODO 6: Agregá los párrafos del post dentro de este <article> (paso 6 del README) -->\n\n      <article></article>\n\n      <!-- TODO 1: Envolver <leccion-10-comments /> con un bloque @defer: @defer { <leccion-10-comments /> } -->\n      <!-- TODO 2: Agregar un bloque @placeholder con: <p>Future comments</p> -->\n      <!-- TODO 3: Agregar un bloque @loading con: <p>Loading comments...</p> -->\n      <!-- TODO 4: Al bloque @loading agregarle una duración mínima: (minimum 2s) -->\n      <!-- TODO 5: Al bloque @defer agregarle el disparador de viewport: (on viewport) -->\n\n      <leccion-10-comments />\n    </div>\n  `,\n  imports: [Leccion10Comments],\n})\nexport class Leccion10 {}\n",
  "src/app/tutorial/10-deferrable-views/README.md": "# Lección 10 — Vistas diferibles (Deferrable Views)\n\nA veces, al desarrollar una aplicación, terminás con muchos componentes que necesitás referenciar en tu app, pero algunos no necesitan cargarse de inmediato por varias razones.\n\nQuizás están por debajo del pliegue visible o son componentes pesados con los que no se interactúa hasta más adelante. En ese caso, podemos cargar algunos de esos recursos más tarde con las vistas diferibles (deferrable views).\n\nEn esta actividad vas a aprender a usar vistas diferibles para cargar de forma diferida una sección de la plantilla de tu componente.\n\n> **Nota sobre la configuración:** la lección original configura `main.ts` y `app.config.ts` con `bootstrapApplication` y `provideRouter`. En esta app anfitriona eso ya está hecho: podés verlo en `src/main.ts` y en `src/app/app.config.ts`, así que acá solo trabajamos con los componentes.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/10>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/10/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/10-deferrable-views/leccion.ts`\n\nBuscá los comentarios `<!-- TODO -->` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Agregar un bloque `@defer` alrededor del componente de comentarios\n\nEn tu app, la página del posteo del blog tiene un componente de comentarios después de los detalles del posteo.\n\nEnvolvé el componente de comentarios con un bloque `@defer` para cargarlo de forma diferida:\n\n```html\n@defer {\n  <comments />\n}\n```\n\nEl código de arriba es un ejemplo de cómo usar un bloque `@defer` básico. Por defecto, `@defer` carga el componente `comments` cuando el navegador está inactivo.\n\n### 2. Agregar un placeholder\n\nAgregá un bloque `@placeholder` al bloque `@defer`. El bloque `@placeholder` es donde ponés el HTML que se va a mostrar antes de que empiece la carga diferida. El contenido de los bloques `@placeholder` se carga de forma eager (inmediata):\n\n```html\n@defer {\n  <comments />\n} @placeholder {\n  <p>Future comments</p>\n}\n```\n\n### 3. Agregar un bloque de carga (loading)\n\nAgregá un bloque `@loading` al bloque `@defer`. El bloque `@loading` es donde ponés el HTML que se muestra _mientras_ el contenido diferido se está cargando activamente, pero todavía no terminó. El contenido de los bloques `@loading` también se carga de forma eager:\n\n```html\n@defer {\n  <comments />\n} @placeholder {\n  <p>Future comments</p>\n} @loading {\n  <p>Loading comments...</p>\n}\n```\n\n### 4. Agregar una duración mínima\n\nTanto las secciones `@placeholder` como `@loading` tienen parámetros opcionales para evitar el parpadeo cuando la carga ocurre muy rápido. `@placeholder` tiene `minimum` y `@loading` tiene `minimum` y `after`. Agregá una duración `minimum` al bloque `@loading` para que se renderice por al menos 2 segundos:\n\n```html\n@defer {\n  <comments />\n} @placeholder {\n  <p>Future comments</p>\n} @loading (minimum 2s) {\n  <p>Loading comments...</p>\n}\n```\n\n### 5. Agregar un disparador de viewport (viewport trigger)\n\nLas vistas diferibles tienen varias opciones de disparadores. Agregá un disparador de viewport para que el contenido se cargue de forma diferida cuando entre en el viewport:\n\n```html\n@defer (on viewport) {\n  <comments />\n} @placeholder {\n  <p>Future comments</p>\n} @loading (minimum 2s) {\n  <p>Loading comments...</p>\n}\n```\n\n### 6. Agregar contenido\n\nUn disparador de viewport es más útil cuando el contenido diferido está lo suficientemente abajo en la página como para tener que hacer scroll para verlo. Así que agreguemos algo de contenido a nuestro posteo del blog. Podés escribir el tuyo o copiar el contenido de abajo y ponerlo dentro del elemento `<article>`:\n\n```html\n<article>\n  <p>\n    Angular is my favorite framework, and this is why. Angular has the coolest deferrable view\n    feature that makes defer loading content the easiest and most ergonomic it could possibly be.\n    The Angular community is also filled with amazing contributors and experts that create excellent\n    content. The community is welcoming and friendly, and it really is the best community out there.\n  </p>\n  <p>\n    I can't express enough how much I enjoy working with Angular. It offers the best developer\n    experience I've ever had. I love that the Angular team puts their developers first and takes\n    care to make us very happy. They genuinely want Angular to be the best framework it can be, and\n    they're doing such an amazing job at it, too. This statement comes from my heart and is not at\n    all copied and pasted. In fact, I think I'll say these exact same things again a few times.\n  </p>\n  <p>\n    Angular is my favorite framework, and this is why. Angular has the coolest deferrable view\n    feature that makes defer loading content the easiest and most ergonomic it could possibly be.\n    The Angular community is also filled with amazing contributors and experts that create excellent\n    content. The community is welcoming and friendly, and it really is the best community out there.\n  </p>\n  <p>\n    I can't express enough how much I enjoy working with Angular. It offers the best developer\n    experience I've ever had. I love that the Angular team puts their developers first and takes\n    care to make us very happy. They genuinely want Angular to be the best framework it can be, and\n    they're doing such an amazing job at it, too. This statement comes from my heart and is not at\n    all copied and pasted. In fact, I think I'll say these exact same things again a few times.\n  </p>\n  <p>\n    Angular is my favorite framework, and this is why. Angular has the coolest deferrable view\n    feature that makes defer loading content the easiest and most ergonomic it could possibly be.\n    The Angular community is also filled with amazing contributors and experts that create excellent\n    content. The community is welcoming and friendly, and it really is the best community out there.\n  </p>\n  <p>\n    I can't express enough how much I enjoy working with Angular. It offers the best developer\n    experience I've ever had. I love that the Angular team puts their developers first and takes\n    care to make us very happy. They genuinely want Angular to be the best framework it can be, and\n    they're doing such an amazing job at it, too. This statement comes from my heart and is not at\n    all copied and pasted.\n  </p>\n</article>\n```\n\nUna vez que agregaste este código, hacé scroll hacia abajo para ver cómo el contenido diferido se carga al entrar en el viewport.\n\n## Para cerrar\n\nEn esta actividad aprendiste a usar vistas diferibles en tus aplicaciones. ¡Gran trabajo! 🙌\n\nSe puede hacer mucho más con ellas: otros disparadores, prefetching y bloques `@error`. Si querés saber más, mirá la [documentación de Deferrable views](https://v20.angular.dev/guide/templates/defer).\n\nCompará tu resultado con la solución en `/tutorial/10/solucion` y seguí con la [Lección 11](http://localhost:4200/tutorial/11).\n",
  "src/app/tutorial/11-optimizando-imagenes/leccion.ts": "import {Component} from '@angular/core';\nimport {Leccion11User} from './user';\n\n/**\n * LECCIÓN 11 — Optimizando imágenes\n *\n * Este componente solo envuelve al componente de usuario; el trabajo\n * con imágenes está en user.ts.\n *\n * Abrí http://localhost:4200/tutorial/11 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/11/solucion\n */\n@Component({\n  selector: 'leccion-11',\n  template: ` <leccion-11-user /> `,\n  imports: [Leccion11User],\n})\nexport class Leccion11 {}\n",
  "src/app/tutorial/11-optimizando-imagenes/README.md": "# Lección 11 — Optimizando imágenes\n\nLas imágenes son una gran parte de muchas aplicaciones y pueden ser una de las principales causas de problemas de rendimiento, incluyendo puntajes bajos de [Core Web Vitals](https://web.dev/explore/learn-core-web-vitals).\n\nLa optimización de imágenes puede ser un tema complejo, pero Angular resuelve la mayor parte por vos con la directiva `NgOptimizedImage`.\n\nEn esta actividad vas a aprender a usar `NgOptimizedImage` para asegurarte de que tus imágenes se carguen de manera eficiente.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/11>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/11/solucion>\n\n## Archivos de trabajo\n\n- `src/app/tutorial/11-optimizando-imagenes/user.ts`\n- `src/app/tutorial/11-optimizando-imagenes/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n> El logo que usa esta lección está en `public/tut-logo.svg` y se sirve en la ruta `/tut-logo.svg`.\n\n## Pasos\n\n### 1. Importar la directiva NgOptimizedImage\n\nPara poder usar la directiva `NgOptimizedImage`, primero importala desde la librería `@angular/common` y agregala al array `imports` del componente:\n\n```ts\nimport { NgOptimizedImage } from '@angular/common';\n\n@Component({\n  imports: [NgOptimizedImage],\n  ...\n})\n```\n\n### 2. Cambiar el atributo src por ngSrc\n\nPara habilitar la directiva `NgOptimizedImage`, cambiá el atributo `src` por `ngSrc`. Esto aplica tanto para fuentes de imagen estáticas (es decir, `src`) como dinámicas (es decir, `[src]`):\n\n```ts\nimport { NgOptimizedImage } from '@angular/common';\n\n@Component({\ntemplate: `     ...\n    <li>\n      Static Image:\n      <img ngSrc=\"/logo.svg\" alt=\"Angular logo\" width=\"32\" height=\"32\" />\n    </li>\n    <li>\n      Dynamic Image:\n      <img [ngSrc]=\"logoUrl\" [alt]=\"logoAlt\" width=\"32\" height=\"32\" />\n    </li>\n    ...\n  `,\nimports: [NgOptimizedImage],\n})\n```\n\n### 3. Agregar los atributos width y height\n\nFijate que en el ejemplo de arriba cada imagen tiene los atributos `width` y `height`. Para evitar el [desplazamiento del layout (CLS)](https://web.dev/articles/cls), la directiva `NgOptimizedImage` requiere ambos atributos de tamaño en cada imagen.\n\nEn situaciones donde no podés o no querés especificar un `height` y `width` estáticos para las imágenes, podés usar [el atributo `fill`](https://v20.angular.dev/guide/image-optimization#using-fill-mode) para que la imagen se comporte como una \"imagen de fondo\", llenando su elemento contenedor:\n\n```html\n<!-- El contenedor div tiene 'position: \"relative\"' -->\n<div class=\"image-container\">\n  <img ngSrc=\"www.example.com/image.png\" fill />\n</div>\n```\n\n**Nota:** para que una imagen con `fill` se renderice correctamente, su elemento padre debe estar estilizado con `position: \"relative\"`, `position: \"fixed\"` o `position: \"absolute\"`.\n\n### 4. Priorizar imágenes importantes\n\nUna de las optimizaciones más importantes para el rendimiento de carga es priorizar cualquier imagen que pueda ser el [\"elemento LCP\"](https://web.dev/articles/optimize-lcp), es decir, el elemento gráfico más grande en pantalla cuando la página carga. Para optimizar tus tiempos de carga, asegurate de agregar el atributo `priority` a tu \"imagen hero\" o a cualquier otra imagen que creas que podría ser un elemento LCP:\n\n```html\n<img ngSrc=\"www.example.com/image.png\" height=\"600\" width=\"800\" priority />\n```\n\n### 5. Opcional: usar un image loader\n\n`NgOptimizedImage` te permite especificar un [image loader](https://v20.angular.dev/guide/image-optimization#configuring-an-image-loader-for-ngoptimizedimage), que le dice a la directiva cómo formatear las URLs de tus imágenes. Usar un loader te permite definir tus imágenes con URLs cortas y relativas:\n\n```ts\nproviders: [provideImgixLoader('https://my.base.url/')],\n```\n\nLa URL final será 'https://my.base.url/image.png'\n\n```html\n<img ngSrc=\"image.png\" height=\"600\" width=\"800\" />\n```\n\nLos image loaders no son solo una comodidad: te permiten usar todas las capacidades de `NgOptimizedImage`. Conocé más sobre estas optimizaciones y los loaders integrados para CDNs populares [acá](https://v20.angular.dev/guide/image-optimization#configuring-an-image-loader-for-ngoptimizedimage).\n\n## Para cerrar\n\nAl agregar esta directiva a tu flujo de trabajo, tus imágenes ahora se cargan usando las mejores prácticas con la ayuda de Angular 🎉\n\nSi querés aprender más, mirá la [documentación de `NgOptimizedImage`](https://v20.angular.dev/guide/image-optimization). ¡Seguí con el gran trabajo y aprendamos sobre routing en la próxima lección!\n\nCompará tu resultado con la solución en `/tutorial/11/solucion` y seguí con la [Lección 12](http://localhost:4200/tutorial/12).\n",
  "src/app/tutorial/11-optimizando-imagenes/user.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 11 — Optimizando imágenes con NgOptimizedImage\n *\n * La directiva `NgOptimizedImage` (de `@angular/common`) optimiza la\n * carga de imágenes: usa `ngSrc` en lugar de `src` y exige los\n * atributos `width` y `height` para evitar saltos de layout.\n *\n * El logo está en public/tut-logo.svg y se sirve en la ruta /tut-logo.svg.\n */\n@Component({\n  selector: 'leccion-11-user',\n  template: `\n    <p>Usuario: {{ username }}</p>\n    <p>Framework preferido:</p>\n\n    <ul>\n      <li>\n        Imagen estática:\n        <!-- TODO 1: Importá NgOptimizedImage desde '@angular/common' y agregalo al array imports de este componente -->\n        <!-- TODO 2: Cambiá el atributo src por ngSrc y agregá width=\"32\" height=\"32\" -->\n\n        <img src='/tut-logo.svg' alt=\"Logo de Angular\" />\n      </li>\n      <li>\n        Imagen dinámica:\n        <!-- TODO 3: Cambiá el atributo [src] por [ngSrc] y agregá width=\"32\" height=\"32\" -->\n\n        <img [src]=\"logoUrl\" [alt]=\"logoAlt\" />\n      </li>\n    </ul>\n  `,\n  imports: [],\n})\nexport class Leccion11User {\n  logoUrl = '/tut-logo.svg';\n  logoAlt = 'Logo de Angular';\n  username = 'youngTech';\n}\n",
  "src/app/tutorial/12-enable-routing/home/home.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 12 — Componente \"Home Page\"\n *\n * Es una de las dos páginas que va a mostrar el router en esta lección.\n */\n@Component({\n  selector: 'leccion-12-home',\n  template: ` <div>Home Page</div> `,\n})\nexport class Leccion12Home {}\n",
  "src/app/tutorial/12-enable-routing/leccion.ts": "import { Component } from '@angular/core';\nimport { RouterOutlet } from '@angular/router';\n\n/**\n * LECCIÓN 12 — Activar el routing\n *\n * Esta clase hace de \"shell\" de la lección: tiene una barra de navegación y\n * es el lugar donde el router va a mostrar el contenido de cada página.\n *\n * Abrí http://localhost:4200/tutorial/12 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/12/solucion\n *\n * Nota: en el tutorial original los links apuntan a \"/\" y \"/user\". En esta\n * app anfitriona las lecciones viven bajo /tutorial/12, así que los links\n * apuntan a /tutorial/12/home y /tutorial/12/user.\n */\n@Component({\n  selector: 'leccion-12',\n  template: `\n    <nav>\n      <a href=\"/tutorial/12/home\">Home</a>\n      |\n      <a href=\"/tutorial/12/user\">User</a>\n    </nav>\n    <!-- TODO 1: Agregá <router-outlet /> acá, debajo del nav, para indicarle al router dónde mostrar el contenido de cada página -->\n  `,\n  imports: [RouterOutlet],\n})\nexport class Leccion12 {}\n",
  "src/app/tutorial/12-enable-routing/README.md": "# Lección 12 — Activar el routing\n\n> Original: [Routing Overview](https://v20.angular.dev/tutorials/learn-angular/12-enable-routing)\n\nA toda app llega el momento en que necesita más de una sola página. Cuando eso pasa, el routing se vuelve una parte fundamental de la historia de rendimiento para tus usuarios.\n\nEn esta lección vas a aprender a configurar tu app para usar el **Angular Router**.\n\n> **Nota:** podés leer más sobre routing en la [guía en profundidad](https://v20.angular.dev/guide/routing).\n\n> **⚠️ App anfitriona:** en esta app el routing ya está configurado de fábrica, así que los pasos 1 y 2 de esta lección **ya están hechos**. Se muestran igual para que entiendas qué hace cada pieza y dónde vivirían en un proyecto propio. Tu ejercicio real es el **paso 3**.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/12>\n   - Sub-rutas: <http://localhost:4200/tutorial/12/home> y <http://localhost:4200/tutorial/12/user>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/12/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/12-enable-routing/leccion.ts`\n\nBuscá el comentario `// TODO 1` y completalo. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Crear un archivo `app.routes.ts` *(ya hecho en esta app)*\n\nDentro de `app.routes.ts`, hacé los siguientes cambios:\n\n1. Importá `Routes` desde el paquete `@angular/router`.\n2. Exportá una constante llamada `routes` de tipo `Routes`, y asignale `[]` como valor.\n\n```ts\nimport { Routes } from '@angular/router';\n\nexport const routes: Routes = [];\n```\n\nEn esta app ese archivo es `src/app/app.routes.ts` y ya existe: ahí se registran las rutas de todas las lecciones.\n\n### 2. Agregar el routing a los providers *(ya hecho en esta app)*\n\nEn `app.config.ts`, configurá la app para usar el Angular Router con estos pasos:\n\n1. Importá la función `provideRouter` desde `@angular/router`.\n2. Importá `routes` desde `./app.routes`.\n3. Llamá a la función `provideRouter` con `routes` como argumento, dentro del array `providers`.\n\n```ts\nimport { ApplicationConfig } from '@angular/core';\nimport { provideRouter } from '@angular/router';\n\nimport { routes } from './app.routes';\n\nexport const appConfig: ApplicationConfig = {\n  providers: [provideRouter(routes)],\n};\n```\n\nEn esta app ese archivo es `src/app/app.config.ts`, que ya llama a `provideRouter(routes)`, y el bootstrap ocurre en `src/main.ts` con `bootstrapApplication`.\n\n### 3. Importar `RouterOutlet` en el componente *(este es tu ejercicio)*\n\nPara que la app esté lista para usar el Angular Router, tenés que decirle **dónde** esperás que el router muestre el contenido. Eso se logra con la directiva `RouterOutlet` de `@angular/router`.\n\nActualizá el template de `Leccion12` (en `leccion.ts`) agregando `<router-outlet />` debajo del `<nav>`:\n\n```ts\n@Component({\n  // ...\n  template: `\n    <nav>\n      <a href=\"/tutorial/12/home\">Home</a>\n      |\n      <a href=\"/tutorial/12/user\">User</a>\n    </nav>\n    <router-outlet />\n  `,\n  imports: [RouterOutlet],\n})\nexport class Leccion12 {}\n```\n\n> **Nota:** en el tutorial original los links son `href=\"/\"` y `href=\"/user\"`. Acá apuntan a `/tutorial/12/home` y `/tutorial/12/user` para no salir del tutorial. En la lección 14 los vas a reemplazar por `routerLink`.\n\nAl mirar la vista vas a ver que `<router-outlet />` por sí solo no muestra nada todavía: es solo el \"agujero\" donde el router va a insertar las páginas. En la próxima lección definimos qué mostrar ahí.\n\n## Para cerrar\n\nTu app ya está configurada para usar Angular Router. ¡Buen trabajo! 🎉\n\nSigamos con el próximo paso: definir las rutas de la app. Compará tu resultado con la solución en `/tutorial/12/solucion` y seguí con la [Lección 13](http://localhost:4200/tutorial/13).\n",
  "src/app/tutorial/12-enable-routing/user/user.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 12 — Componente \"User Page\"\n *\n * Es la otra página que va a mostrar el router en esta lección.\n */\n@Component({\n  selector: 'leccion-12-user',\n  template: ` <div>Username: {{ username }}</div> `,\n})\nexport class Leccion12User {\n  username = 'youngTech';\n}\n",
  "src/app/tutorial/13-define-a-route/home/home.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 13 — Componente \"Home Page\"\n *\n * Es la página que se muestra en la ruta por defecto (path: '') del shell\n * de la lección 13.\n */\n@Component({\n  selector: 'leccion-13-home',\n  template: ` <div>Home Page</div> `,\n})\nexport class Leccion13Home {}\n",
  "src/app/tutorial/13-define-a-route/leccion.ts": "import { Component } from '@angular/core';\nimport { RouterOutlet } from '@angular/router';\n\n/**\n * LECCIÓN 13 — Definir una ruta\n *\n * Esta clase hace de \"shell\" de la lección: tiene una barra de navegación y\n * el <router-outlet /> donde el router muestra las páginas Home y User.\n *\n * ⚠️ El ejercicio de esta lección NO está acá: está en `src/app/app.routes.ts`.\n * Tenés que agregar las rutas hijas de /tutorial/13 (Home y User) al array\n * `children` de esa ruta. Mirá el README de la lección para el snippet exacto.\n *\n * Hasta que agregues esas rutas, http://localhost:4200/tutorial/13/home y\n * http://localhost:4200/tutorial/13/user no van a funcionar.\n *\n * La versión resuelta está en http://localhost:4200/tutorial/13/solucion\n *\n * Nota: en el tutorial original los links apuntan a \"/\" y \"/user\". En esta\n * app anfitriona las lecciones viven bajo /tutorial/13.\n */\n@Component({\n  selector: 'leccion-13',\n  template: `\n    <nav>\n      <a href=\"/tutorial/13/home\">Home</a>\n      |\n      <a href=\"/tutorial/13/user\">User</a>\n    </nav>\n    <router-outlet />\n  `,\n  imports: [RouterOutlet],\n})\nexport class Leccion13 {}\n",
  "src/app/tutorial/13-define-a-route/README.md": "# Lección 13 — Definir una ruta\n\n> Original: [Define a Route](https://v20.angular.dev/tutorials/learn-angular/13-define-a-route)\n\nAhora que la app ya está configurada para usar el Angular Router, es momento de **definir las rutas**.\n\nEn esta lección vas a aprender a agregar y configurar rutas en tu app.\n\n> **Nota:** podés leer más sobre cómo definir rutas básicas en la [guía en profundidad](https://v20.angular.dev/guide/routing/define-routes).\n\n> **⚠️ App anfitriona:** en el tutorial original las rutas se definen en el array raíz de `app.routes.ts` (`path: ''` y `path: 'user'`). En esta app las lecciones viven bajo `/tutorial/13`, así que el ejercicio consiste en agregar esas mismas rutas como **rutas hijas** (`children`) de la ruta `tutorial/13`. Tu archivo de trabajo es `src/app/app.routes.ts` (el de la app, no el de la lección).\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/13>\n   - Sub-rutas: <http://localhost:4200/tutorial/13/home> y <http://localhost:4200/tutorial/13/user> — **no van a funcionar hasta que completes el ejercicio**\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/13/solucion>\n\n## Archivo de trabajo\n\n`src/app/app.routes.ts` (en la raíz de `src/app/`, no dentro de la carpeta de la lección)\n\nEl shell de la lección (`src/app/tutorial/13-define-a-route/leccion.ts`) ya está completo y no tiene TODOs: la única pieza que falta son las rutas.\n\n## Pasos\n\n### 1. Definir una ruta en `app.routes.ts`\n\nEn tu app hay dos páginas para mostrar: (1) la **Home Page** y (2) la **User Page**.\n\nPara definir una ruta, agregá un objeto de ruta al array de rutas que contenga:\n\n- El `path` de la ruta (que arranca automáticamente desde la raíz, es decir, `/`)\n- El `component` que querés que esa ruta muestre\n\nAsí se ve en el tutorial original, donde `Home` se agrega como ruta por defecto:\n\n```ts\nimport { Routes } from '@angular/router';\nimport { Home } from './home/home';\n\nexport const routes: Routes = [\n  {\n    path: '',\n    component: Home,\n  },\n];\n```\n\n**Adaptación a esta app:** en `src/app/app.routes.ts`, buscá la ruta con `path: 'tutorial/13'` y agregale un array `children` con los objetos de ruta de las páginas de la lección, usando las clases `Leccion13Home` y `Leccion13User`:\n\n```ts\nimport { Leccion13Home } from './tutorial/13-define-a-route/home/home';\nimport { Leccion13User } from './tutorial/13-define-a-route/user/user';\n\n// ... dentro del array `routes`, en la ruta path: 'tutorial/13':\n{\n  path: 'tutorial/13',\n  children: [\n    {\n      path: '',\n      title: 'App Home Page',\n      component: Leccion13Home,\n    },\n    {\n      path: 'user',\n      title: 'App User Page',\n      component: Leccion13User,\n    },\n  ],\n},\n```\n\nUsá `'user'` como path para `Leccion13User`, tal como pide el original.\n\n### 2. Agregar `title` a la definición de la ruta\n\nAdemás de definir las rutas correctamente, el Angular Router te permite establecer el título de la página cada vez que el usuario navega, agregando la propiedad `title` a cada ruta.\n\nAgregá la propiedad `title` a la ruta por defecto (`path: ''`) y a la ruta `user`. Ya están incluidas en el snippet del paso 1, pero así se ve en el original:\n\n```ts\nimport { Routes } from '@angular/router';\nimport { Home } from './home/home';\n\nexport const routes: Routes = [\n  {\n    path: '',\n    title: 'App Home Page',\n    component: Home,\n  },\n];\n```\n\nAl navegar, vas a ver que el título de la pestaña del navegador cambia según la página.\n\n## Para cerrar\n\nEn esta actividad aprendiste a definir y configurar rutas en tu app Angular. ¡Buen trabajo! 🎉\n\nEl camino para tener routing completo casi termina, seguí adelante: compará con la solución en `/tutorial/13/solucion` y pasá a la [Lección 14](http://localhost:4200/tutorial/14).\n",
  "src/app/tutorial/13-define-a-route/user/user.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 13 — Componente \"User Page\"\n *\n * Es la página que se muestra en la ruta 'user' del shell de la lección 13.\n */\n@Component({\n  selector: 'leccion-13-user',\n  template: ` <div>Username: {{ username }}</div> `,\n})\nexport class Leccion13User {\n  username = 'youngTech';\n}\n",
  "src/app/app.routes.ts": "import { Routes } from '@angular/router';\nimport { rutasPractica04 } from './extras/04-auth-jwt-guards-interceptors/rutas';\n\nexport const routes: Routes = [\n  // ─── Página de inicio: acceso a Tutorial y Prácticas ─────────\n  {\n    path: '',\n    pathMatch: 'full',\n    loadComponent: () => import('./home/home').then((m) => m.Home),\n    title: 'Pruebas Practicas — Aprendiendo Angular haciendo',\n  },\n\n  {\n    path: 'tutorial',\n    loadComponent: () => import('./tutorial/index').then((m) => m.TutorialIndex),\n    title: 'Tutorial de Angular',\n  },\n\n  // ─── Lección 01 — Anatomía de un Componente ──────────────────\n  {\n    path: 'tutorial/01',\n    loadComponent: () => import('./tutorial/01-componentes/leccion').then((m) => m.Leccion01),\n    title: 'Lección 01 — Anatomía de un Componente',\n  },\n  {\n    path: 'tutorial/01/solucion',\n    loadComponent: () =>\n      import('./tutorial/01-componentes/solucion/solucion').then((m) => m.Leccion01Solucion),\n    title: 'Solución 01 — Anatomía de un Componente',\n  },\n\n  // ─── Lección 02 — Actualizar la clase del componente ─────────\n  {\n    path: 'tutorial/02',\n    loadComponent: () =>\n      import('./tutorial/02-clase-del-componente/leccion').then((m) => m.Leccion02),\n    title: 'Lección 02 — Actualizar la clase del componente',\n  },\n  {\n    path: 'tutorial/02/solucion',\n    loadComponent: () =>\n      import('./tutorial/02-clase-del-componente/solucion/solucion').then(\n        (m) => m.Leccion02Solucion,\n      ),\n    title: 'Solución 02 — Actualizar la clase del componente',\n  },\n\n  // ─── Lección 03 — Componer componentes ───────────────────────\n  {\n    path: 'tutorial/03',\n    loadComponent: () =>\n      import('./tutorial/03-componer-componentes/leccion').then((m) => m.Leccion03),\n    title: 'Lección 03 — Componer componentes',\n  },\n  {\n    path: 'tutorial/03/solucion',\n    loadComponent: () =>\n      import('./tutorial/03-componer-componentes/solucion/solucion').then(\n        (m) => m.Leccion03Solucion,\n      ),\n    title: 'Solución 03 — Componer componentes',\n  },\n\n  // ─── Lección 04 — Control de flujo: @if ──────────────────────\n  {\n    path: 'tutorial/04',\n    loadComponent: () => import('./tutorial/04-control-flow-if/leccion').then((m) => m.Leccion04),\n    title: 'Lección 04 — Control de flujo: @if',\n  },\n  {\n    path: 'tutorial/04/solucion',\n    loadComponent: () =>\n      import('./tutorial/04-control-flow-if/solucion/solucion').then((m) => m.Leccion04Solucion),\n    title: 'Solución 04 — Control de flujo: @if',\n  },\n\n  // ─── Lección 05 — Control de flujo: @for ─────────────────────\n  {\n    path: 'tutorial/05',\n    loadComponent: () => import('./tutorial/05-control-flow-for/leccion').then((m) => m.Leccion05),\n    title: 'Lección 05 — Control de flujo: @for',\n  },\n  {\n    path: 'tutorial/05/solucion',\n    loadComponent: () =>\n      import('./tutorial/05-control-flow-for/solucion/solucion').then((m) => m.Leccion05Solucion),\n    title: 'Solución 05 — Control de flujo: @for',\n  },\n\n  // ─── Lección 06 — Property binding ───────────────────────────\n  {\n    path: 'tutorial/06',\n    loadComponent: () => import('./tutorial/06-property-binding/leccion').then((m) => m.Leccion06),\n    title: 'Lección 06 — Property binding',\n  },\n  {\n    path: 'tutorial/06/solucion',\n    loadComponent: () =>\n      import('./tutorial/06-property-binding/solucion/solucion').then((m) => m.Leccion06Solucion),\n    title: 'Solución 06 — Property binding',\n  },\n\n  // ─── Lección 07 — Manejo de eventos ──────────────────────────\n  {\n    path: 'tutorial/07',\n    loadComponent: () => import('./tutorial/07-event-handling/leccion').then((m) => m.Leccion07),\n    title: 'Lección 07 — Manejo de eventos',\n  },\n  {\n    path: 'tutorial/07/solucion',\n    loadComponent: () =>\n      import('./tutorial/07-event-handling/solucion/solucion').then((m) => m.Leccion07Solucion),\n    title: 'Solución 07 — Manejo de eventos',\n  },\n\n  // ─── Lección 08 — Inputs ─────────────────────────────────────\n  {\n    path: 'tutorial/08',\n    loadComponent: () => import('./tutorial/08-input/leccion').then((m) => m.Leccion08),\n    title: 'Lección 08 — Inputs',\n  },\n  {\n    path: 'tutorial/08/solucion',\n    loadComponent: () =>\n      import('./tutorial/08-input/solucion/solucion').then((m) => m.Leccion08Solucion),\n    title: 'Solución 08 — Inputs',\n  },\n\n  // ─── Lección 09 — Outputs ────────────────────────────────────\n  {\n    path: 'tutorial/09',\n    loadComponent: () => import('./tutorial/09-output/leccion').then((m) => m.Leccion09),\n    title: 'Lección 09 — Outputs',\n  },\n  {\n    path: 'tutorial/09/solucion',\n    loadComponent: () =>\n      import('./tutorial/09-output/solucion/solucion').then((m) => m.Leccion09Solucion),\n    title: 'Solución 09 — Outputs',\n  },\n\n  // ─── Lección 10 — Vistas diferibles (@defer) ─────────────────\n  {\n    path: 'tutorial/10',\n    loadComponent: () => import('./tutorial/10-deferrable-views/leccion').then((m) => m.Leccion10),\n    title: 'Lección 10 — Vistas diferibles (@defer)',\n  },\n  {\n    path: 'tutorial/10/solucion',\n    loadComponent: () =>\n      import('./tutorial/10-deferrable-views/solucion/solucion').then((m) => m.Leccion10Solucion),\n    title: 'Solución 10 — Vistas diferibles (@defer)',\n  },\n\n  // ─── Lección 11 — Optimización de imágenes ───────────────────\n  {\n    path: 'tutorial/11',\n    loadComponent: () =>\n      import('./tutorial/11-optimizando-imagenes/leccion').then((m) => m.Leccion11),\n    title: 'Lección 11 — Optimización de imágenes',\n  },\n  {\n    path: 'tutorial/11/solucion',\n    loadComponent: () =>\n      import('./tutorial/11-optimizando-imagenes/solucion/solucion').then(\n        (m) => m.Leccion11Solucion,\n      ),\n    title: 'Solución 11 — Optimización de imágenes',\n  },\n\n  // ─── Lección 12 — Habilitar el routing ───────────────────────\n  {\n    path: 'tutorial/12',\n    loadComponent: () => import('./tutorial/12-enable-routing/leccion').then((m) => m.Leccion12),\n    children: [\n      {\n        path: '',\n        loadComponent: () =>\n          import('./tutorial/12-enable-routing/home/home').then((m) => m.Leccion12Home),\n        title: 'App Home Page',\n      },\n      {\n        path: 'user',\n        loadComponent: () =>\n          import('./tutorial/12-enable-routing/user/user').then((m) => m.Leccion12User),\n        title: 'App User Page',\n      },\n    ],\n    title: 'Lección 12 — Habilitar el routing',\n  },\n  {\n    path: 'tutorial/12/solucion',\n    loadComponent: () =>\n      import('./tutorial/12-enable-routing/solucion/solucion').then((m) => m.Leccion12Solucion),\n    children: [\n      {\n        path: '',\n        loadComponent: () =>\n          import('./tutorial/12-enable-routing/solucion/home/home').then(\n            (m) => m.Leccion12SolucionHome,\n          ),\n      },\n      {\n        path: 'home',\n        loadComponent: () =>\n          import('./tutorial/12-enable-routing/solucion/home/home').then(\n            (m) => m.Leccion12SolucionHome,\n          ),\n      },\n      {\n        path: 'user',\n        loadComponent: () =>\n          import('./tutorial/12-enable-routing/solucion/user/user').then(\n            (m) => m.Leccion12SolucionUser,\n          ),\n      },\n    ],\n    title: 'Solución 12 — Habilitar el routing',\n  },\n\n  // ─── Lección 13 — Definir una ruta ───────────────────────────\n  // ✏️ EJERCICIO de la lección 13: definí las rutas hijas de esta lección.\n  // Las páginas ya existen (Leccion13Home y Leccion13User); te falta a vos:\n  // agregar el array `children` con `path: ''` (Home) y `path: 'user'` (User).\n  // El snippet exacto está en src/app/tutorial/13-define-a-route/README.md\n  {\n    path: 'tutorial/13',\n    loadComponent: () => import('./tutorial/13-define-a-route/leccion').then((m) => m.Leccion13),\n    // TODO (Lección 13): agregá acá el array `children` con las rutas\n    // '' → Leccion13Home y 'user' → Leccion13User (ver README de la lección).\n    title: 'Lección 13 — Definir una ruta',\n  },\n  {\n    path: 'tutorial/13/solucion',\n    loadComponent: () =>\n      import('./tutorial/13-define-a-route/solucion/solucion').then((m) => m.Leccion13Solucion),\n    children: [\n      {\n        path: '',\n        loadComponent: () =>\n          import('./tutorial/13-define-a-route/solucion/home/home').then(\n            (m) => m.Leccion13SolucionHome,\n          ),\n      },\n      {\n        path: 'home',\n        loadComponent: () =>\n          import('./tutorial/13-define-a-route/solucion/home/home').then(\n            (m) => m.Leccion13SolucionHome,\n          ),\n      },\n      {\n        path: 'user',\n        loadComponent: () =>\n          import('./tutorial/13-define-a-route/solucion/user/user').then(\n            (m) => m.Leccion13SolucionUser,\n          ),\n      },\n    ],\n    title: 'Solución 13 — Definir una ruta',\n  },\n\n  // ─── Lección 14 — Navegación con routerLink ──────────────────\n  {\n    path: 'tutorial/14',\n    loadComponent: () => import('./tutorial/14-routerlink/leccion').then((m) => m.Leccion14),\n    children: [\n      {\n        path: '',\n        loadComponent: () =>\n          import('./tutorial/14-routerlink/home/home').then((m) => m.Leccion14Home),\n        title: 'App Home Page',\n      },\n      {\n        path: 'user',\n        loadComponent: () =>\n          import('./tutorial/14-routerlink/user/user').then((m) => m.Leccion14User),\n        title: 'App User Page',\n      },\n    ],\n    title: 'Lección 14 — Navegación con routerLink',\n  },\n  {\n    path: 'tutorial/14/solucion',\n    loadComponent: () =>\n      import('./tutorial/14-routerlink/solucion/solucion').then((m) => m.Leccion14Solucion),\n    children: [\n      {\n        path: '',\n        loadComponent: () =>\n          import('./tutorial/14-routerlink/solucion/home/home').then(\n            (m) => m.Leccion14SolucionHome,\n          ),\n      },\n      {\n        path: 'home',\n        loadComponent: () =>\n          import('./tutorial/14-routerlink/solucion/home/home').then(\n            (m) => m.Leccion14SolucionHome,\n          ),\n      },\n      {\n        path: 'user',\n        loadComponent: () =>\n          import('./tutorial/14-routerlink/solucion/user/user').then(\n            (m) => m.Leccion14SolucionUser,\n          ),\n      },\n    ],\n    title: 'Solución 14 — Navegación con routerLink',\n  },\n\n  // ─── Lección 15 — Formularios ────────────────────────────────\n  {\n    path: 'tutorial/15',\n    loadComponent: () => import('./tutorial/15-forms/leccion').then((m) => m.Leccion15),\n    title: 'Lección 15 — Formularios',\n  },\n  {\n    path: 'tutorial/15/solucion',\n    loadComponent: () =>\n      import('./tutorial/15-forms/solucion/solucion').then((m) => m.Leccion15Solucion),\n    title: 'Solución 15 — Formularios',\n  },\n\n  // ─── Lección 16 — Valores de controles de formulario ─────────\n  {\n    path: 'tutorial/16',\n    loadComponent: () =>\n      import('./tutorial/16-form-control-values/leccion').then((m) => m.Leccion16),\n    title: 'Lección 16 — Valores de controles de formulario',\n  },\n  {\n    path: 'tutorial/16/solucion',\n    loadComponent: () =>\n      import('./tutorial/16-form-control-values/solucion/solucion').then(\n        (m) => m.Leccion16Solucion,\n      ),\n    title: 'Solución 16 — Valores de controles de formulario',\n  },\n\n  // ─── Lección 17 — Formularios reactivos ──────────────────────\n  {\n    path: 'tutorial/17',\n    loadComponent: () => import('./tutorial/17-reactive-forms/leccion').then((m) => m.Leccion17),\n    title: 'Lección 17 — Formularios reactivos',\n  },\n  {\n    path: 'tutorial/17/solucion',\n    loadComponent: () =>\n      import('./tutorial/17-reactive-forms/solucion/solucion').then((m) => m.Leccion17Solucion),\n    title: 'Solución 17 — Formularios reactivos',\n  },\n\n  // ─── Lección 18 — Validación de formularios ──────────────────\n  {\n    path: 'tutorial/18',\n    loadComponent: () => import('./tutorial/18-forms-validation/leccion').then((m) => m.Leccion18),\n    title: 'Lección 18 — Validación de formularios',\n  },\n  {\n    path: 'tutorial/18/solucion',\n    loadComponent: () =>\n      import('./tutorial/18-forms-validation/solucion/solucion').then((m) => m.Leccion18Solucion),\n    title: 'Solución 18 — Validación de formularios',\n  },\n\n  // ─── Lección 19 — Crear un servicio inyectable ───────────────\n  {\n    path: 'tutorial/19',\n    loadComponent: () =>\n      import('./tutorial/19-injectable-service/leccion').then((m) => m.Leccion19),\n    title: 'Lección 19 — Crear un servicio inyectable',\n  },\n  {\n    path: 'tutorial/19/solucion',\n    loadComponent: () =>\n      import('./tutorial/19-injectable-service/solucion/solucion').then((m) => m.Leccion19Solucion),\n    title: 'Solución 19 — Crear un servicio inyectable',\n  },\n\n  // ─── Lección 20 — Inyección de dependencias con inject() ─────\n  {\n    path: 'tutorial/20',\n    loadComponent: () => import('./tutorial/20-inject-based-di/leccion').then((m) => m.Leccion20),\n    title: 'Lección 20 — Inyección de dependencias con inject()',\n  },\n  {\n    path: 'tutorial/20/solucion',\n    loadComponent: () =>\n      import('./tutorial/20-inject-based-di/solucion/solucion').then((m) => m.Leccion20Solucion),\n    title: 'Solución 20 — Inyección de dependencias con inject()',\n  },\n\n  // ─── Lección 22 — Pipes ──────────────────────────────────────\n  {\n    path: 'tutorial/22',\n    loadComponent: () => import('./tutorial/22-pipes/leccion').then((m) => m.Leccion22),\n    title: 'Lección 22 — Pipes',\n  },\n  {\n    path: 'tutorial/22/solucion',\n    loadComponent: () =>\n      import('./tutorial/22-pipes/solucion/solucion').then((m) => m.Leccion22Solucion),\n    title: 'Solución 22 — Pipes',\n  },\n\n  // ─── Lección 23 — Formatear datos con pipes ──────────────────\n  {\n    path: 'tutorial/23',\n    loadComponent: () => import('./tutorial/23-pipes-format-data/leccion').then((m) => m.Leccion23),\n    title: 'Lección 23 — Formatear datos con pipes',\n  },\n  {\n    path: 'tutorial/23/solucion',\n    loadComponent: () =>\n      import('./tutorial/23-pipes-format-data/solucion/solucion').then((m) => m.Leccion23Solucion),\n    title: 'Solución 23 — Formatear datos con pipes',\n  },\n\n  // ─── Lección 24 — Crear un pipe personalizado ────────────────\n  {\n    path: 'tutorial/24',\n    loadComponent: () => import('./tutorial/24-create-a-pipe/leccion').then((m) => m.Leccion24),\n    title: 'Lección 24 — Crear un pipe personalizado',\n  },\n  {\n    path: 'tutorial/24/solucion',\n    loadComponent: () =>\n      import('./tutorial/24-create-a-pipe/solucion/solucion').then((m) => m.Leccion24Solucion),\n    title: 'Solución 24 — Crear un pipe personalizado',\n  },\n\n  // ─── Lección 25 — Próximos pasos (solo lectura) ──────────────\n  {\n    path: 'tutorial/25',\n    loadComponent: () => import('./tutorial/25-next-steps/leccion').then((m) => m.Leccion25),\n    title: 'Lección 25 — Próximos pasos',\n  },\n\n  // ═══════════════════════════════════════════════════════════════\n  //  PRÁCTICAS AVANZADAS (src/app/extras)\n  // ═══════════════════════════════════════════════════════════════\n  {\n    path: 'extras',\n    loadComponent: () => import('./extras/index').then((m) => m.ExtrasIndex),\n    title: 'Prácticas avanzadas de Angular',\n  },\n\n  // ─── Práctica 01 — Comunicación y Bus de Eventos ─────────────\n  {\n    path: 'extras/01',\n    loadComponent: () =>\n      import('./extras/01-comunicacion-y-bus-eventos/ejercicio/productos-page').then(\n        (m) => m.ProductosPage,\n      ),\n    title: 'Práctica 01 — Comunicación y Bus de Eventos',\n  },\n  {\n    path: 'extras/01/solucion',\n    loadComponent: () =>\n      import('./extras/01-comunicacion-y-bus-eventos/solucion/productos-page').then(\n        (m) => m.ProductosPageSolucion,\n      ),\n    title: 'Solución 01 — Comunicación y Bus de Eventos',\n  },\n\n  // ─── Práctica 02 — Formularios reactivos avanzados ───────────\n  {\n    path: 'extras/02',\n    loadComponent: () =>\n      import('./extras/02-formularios-reactivos-avanzados/ejercicio/registro-page').then(\n        (m) => m.RegistroPage,\n      ),\n    title: 'Práctica 02 — Formularios Reactivos Avanzados',\n  },\n  {\n    path: 'extras/02/solucion',\n    loadComponent: () =>\n      import('./extras/02-formularios-reactivos-avanzados/solucion/registro-page').then(\n        (m) => m.RegistroPageSolucion,\n      ),\n    title: 'Solución 02 — Formularios Reactivos Avanzados',\n  },\n\n  // ─── Práctica 03 — HttpClient y Manejo de Errores ────────────\n  // El \"backend\" de la 03 y la 04 es un interceptor falso (backendFalso)\n  // registrado en app.config.ts: todo responde offline.\n  {\n    path: 'extras/03',\n    loadComponent: () =>\n      import('./extras/03-http-client-y-manejo-errores/ejercicio/empleados-page').then(\n        (m) => m.EmpleadosPage,\n      ),\n    title: 'Práctica 03 — HttpClient y Manejo de Errores',\n  },\n  {\n    path: 'extras/03/solucion',\n    loadComponent: () =>\n      import('./extras/03-http-client-y-manejo-errores/solucion/empleados-page').then(\n        (m) => m.EmpleadosPageSolucion,\n      ),\n    title: 'Solución 03 — HttpClient y Manejo de Errores',\n  },\n\n  // ─── Práctica 04 — Auth JWT: Guards e Interceptores ──────────\n  // Las rutas (hijas, con guards) viven en extras/04-auth-jwt-guards-interceptors/rutas.ts.\n  ...rutasPractica04,\n\n  // ─── Práctica 05 — CRUD Interactivo con Modales ──────────────\n  {\n    path: 'extras/05',\n    loadComponent: () =>\n      import('./extras/05-crud-interactivo-con-modales/ejercicio/empleados-page').then(\n        (m) => m.EmpleadosPage,\n      ),\n    title: 'Práctica 05 — CRUD Interactivo con Modales',\n  },\n  {\n    path: 'extras/05/solucion',\n    loadComponent: () =>\n      import('./extras/05-crud-interactivo-con-modales/solucion/empleados-page').then(\n        (m) => m.EmpleadosPageSolucion,\n      ),\n    title: 'Solución 05 — CRUD Interactivo con Modales',\n  },\n];\n",
  "src/app/tutorial/14-routerlink/home/home.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 14 — Componente \"Home Page\"\n */\n@Component({\n  selector: 'leccion-14-home',\n  template: ` <div>Home Page</div> `,\n})\nexport class Leccion14Home {}\n",
  "src/app/tutorial/14-routerlink/leccion.ts": "import { Component } from '@angular/core';\nimport { RouterOutlet } from '@angular/router';\n\n/**\n * LECCIÓN 14 — Navegación con routerLink\n *\n * Esta clase hace de \"shell\" de la lección. En su estado inicial los links\n * usan `href`, lo que recarga la página entera en cada clic. El ejercicio es\n * reemplazarlos por la directiva `routerLink` para que la navegación sea\n * del lado del cliente (sin recargar la app).\n *\n * Abrí http://localhost:4200/tutorial/14 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/14/solucion\n *\n * Nota: en el tutorial original los links apuntan a \"/\" y \"/user\". En esta\n * app anfitriona las lecciones viven bajo /tutorial/14.\n */\n@Component({\n  selector: 'leccion-14',\n  template: `\n    <nav>\n      <!-- TODO 2: Reemplazá los atributos \"href\" por la directiva \"routerLink\" -->\n      <a href=\"/tutorial/14/home\">Home</a>\n      |\n      <a href=\"/tutorial/14/user\">User</a>\n    </nav>\n    <router-outlet />\n  `,\n  // TODO 1: Importá RouterLink desde '@angular/router' y agregalo al array \"imports\" del decorator\n  imports: [RouterOutlet],\n})\nexport class Leccion14 {}\n",
  "src/app/tutorial/14-routerlink/README.md": "# Lección 14 — Navegación con routerLink\n\n> Original: [Use RouterLink for Navigation](https://v20.angular.dev/tutorials/learn-angular/14-routerLink)\n\nEn el estado actual de la app, la página entera se recarga cada vez que hacés clic en un link interno. Con una app chica puede parecer irrelevante, pero en páginas más grandes tiene implicancias de rendimiento: el usuario tiene que volver a descargar assets y ejecutar cálculos otra vez.\n\nEn esta lección vas a aprender a usar la directiva **`RouterLink`** para sacarle el máximo provecho al Angular Router.\n\n> **Nota:** podés leer más sobre cómo agregar rutas a tu aplicación en la [guía en profundidad](https://v20.angular.dev/guide/routing/define-routes#adding-the-router-to-your-application).\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/14>\n   - Sub-rutas: <http://localhost:4200/tutorial/14/home> y <http://localhost:4200/tutorial/14/user>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/14/solucion>\n\n> Probá hacer clic en los links del nav: mientras uses `href`, la página entera se recarga. Después de completar el ejercicio, solo cambia el contenido del `<router-outlet />`.\n\n## Archivo de trabajo\n\n`src/app/tutorial/14-routerlink/leccion.ts`\n\nBuscá los comentarios `// TODO 1` y `// TODO 2` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Importar la directiva `RouterLink`\n\nEn `leccion.ts`, agregá la directiva `RouterLink` al import existente desde `@angular/router` y sumala al array `imports` del decorator del componente:\n\n```ts\n// ...\nimport { RouterLink, RouterOutlet } from '@angular/router';\n\n@Component({\n  imports: [RouterLink, RouterOutlet],\n  // ...\n})\n```\n\n### 2. Agregar `routerLink` al template\n\nPara usar la directiva `RouterLink`, reemplazá los atributos `href` por `routerLink`. Actualizá el template con este cambio:\n\n```ts\nimport { RouterLink, RouterOutlet } from '@angular/router';\n\n@Component({\n  // ...\n  template: `\n    ...\n    <a routerLink=\"/\">Home</a>\n    <a routerLink=\"/user\">User</a>\n    ...\n  `,\n  imports: [RouterLink, RouterOutlet],\n})\n```\n\n**Adaptación a esta app:** los links de la lección apuntan a `/tutorial/14/home` y `/tutorial/14/user` (en la solución, a `/tutorial/14/solucion/home` y `/tutorial/14/solucion/user`) para no salir del tutorial.\n\n```ts\n<a routerLink=\"/tutorial/14/home\">Home</a>\n|\n<a routerLink=\"/tutorial/14/user\">User</a>\n```\n\nCuando hagas clic en los links de la navegación, ya no debería parpadear la pantalla: solo cambia el contenido de la página en sí (es decir, lo que muestra el `<router-outlet />`).\n\n## Para cerrar\n\n¡Buen trabajo aprendiendo sobre routing con Angular! 🎉 Esto es apenas la superficie de la API del `Router`; para saber más, mirá la [documentación de Angular Router](https://v20.angular.dev/guide/routing).\n\nCompará tu resultado con la solución en `/tutorial/14/solucion` y seguí con la [Lección 15](http://localhost:4200/tutorial/15), donde arrancamos con los formularios.\n",
  "src/app/tutorial/14-routerlink/user/user.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 14 — Componente \"User Page\"\n */\n@Component({\n  selector: 'leccion-14-user',\n  template: ` <div>Username: {{ username }}</div> `,\n})\nexport class Leccion14User {\n  username = 'youngTech';\n}\n",
  "src/app/tutorial/15-forms/leccion.ts": "import { Component } from '@angular/core';\nimport { Leccion15User } from './user';\n\n/**\n * LECCIÓN 15 — Formularios (template-driven)\n *\n * Shell de la lección: muestra el componente <leccion-15-user />, que es\n * donde está todo el ejercicio.\n *\n * Abrí http://localhost:4200/tutorial/15 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/15/solucion\n */\n@Component({\n  selector: 'leccion-15',\n  template: ` <leccion-15-user /> `,\n  imports: [Leccion15User],\n})\nexport class Leccion15 {}\n",
  "src/app/tutorial/15-forms/README.md": "# Lección 15 — Formularios (template-driven)\n\n> Original: [Forms Overview](https://v20.angular.dev/tutorials/learn-angular/15-forms)\n\nLos formularios son una parte grande de muchas apps porque le permiten a tu app aceptar input del usuario. Veamos cómo se manejan los formularios en Angular.\n\nEn Angular hay dos tipos de formularios: **template-driven** (basados en la plantilla) y **reactive** (reactivos). Vas a aprender sobre ambos en las próximas actividades.\n\nEn esta lección vas a aprender a armar un formulario usando el enfoque template-driven.\n\n> **Nota:** podés leer más sobre formularios en la [guía en profundidad](https://v20.angular.dev/guide/forms).\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/15>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/15/solucion>\n\n## Archivos de trabajo\n\n`src/app/tutorial/15-forms/user.ts`\n\nBuscá los comentarios `// TODO 1`, `// TODO 2` y `// TODO 3` y completalos. El shell (`leccion.ts`) no necesita cambios. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Crear un campo de input\n\nEn `user.ts`, actualizá la plantilla agregando un input de texto con el `id` en `framework` y el `type` en `text`, dentro del `<label>`:\n\n```angular-html\n<label for=\"framework\">\n  Favorite Framework:\n  <input id=\"framework\" type=\"text\" />\n</label>\n```\n\n### 2. Importar `FormsModule`\n\nPara que este formulario use las características de Angular que permiten vincular datos con formularios, necesitás importar el `FormsModule`.\n\nImportá `FormsModule` desde `@angular/forms` y agregalo al array `imports` de `Leccion15User`:\n\n```ts {highlight:[[2],[6]]}\nimport { Component } from '@angular/core';\nimport { FormsModule } from '@angular/forms';\n\n@Component({\n  // ...\n  imports: [FormsModule],\n})\nexport class Leccion15User {}\n```\n\n### 3. Vincular el valor del input con la clase\n\nEl `FormsModule` trae una directiva llamada `ngModel` que vincula el valor del input con una propiedad de tu clase.\n\nActualizá el input para usar la directiva `ngModel`, con esta sintaxis: `[(ngModel)]=\"favoriteFramework\"`, para vincular la propiedad `favoriteFramework`:\n\n```html {highlight:[3]}\n<label for=\"framework\">\n  Favorite Framework:\n  <input id=\"framework\" type=\"text\" [(ngModel)]=\"favoriteFramework\" />\n</label>\n```\n\nDespués de hacer los cambios, probá escribir un valor en el campo. Fijate cómo se actualiza en la pantalla (sí, muy bueno 😄).\n\n> **Nota:** la sintaxis `[()]` se conoce como *\"banana in a box\"* (banana en una caja) y representa un two-way binding (vinculación bidireccional): property binding + event binding. Podés leer más en la [documentación de Angular sobre two-way data binding](https://v20.angular.dev/guide/templates/two-way-binding).\n\n## Para cerrar\n\nDiste un primer paso importante hacia la construcción de formularios con Angular. ¡Buen trabajo! 🎉 Sigamos con el impulso.\n\nCompará tu resultado con la solución en `/tutorial/15/solucion` y seguí con la [Lección 16](http://localhost:4200/tutorial/16).\n",
  "src/app/tutorial/15-forms/user.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 15 — Componente User con un formulario template-driven\n *\n * Acá está el ejercicio: crear un input de texto y conectarlo con la\n * propiedad `favoriteFramework` de la clase usando `ngModel`.\n *\n * Abrí http://localhost:4200/tutorial/15 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/15/solucion\n */\n@Component({\n  selector: 'leccion-15-user',\n  template: `\n    <p>Username: {{ username }}</p>\n    <p>{{ username }}'s favorite framework: {{ favoriteFramework }}</p>\n    <!-- TODO 1: Dentro del label, agregá un input de texto con id=\"framework\" y type=\"text\" -->\n    <label for=\"framework\">Favorite Framework:</label>\n  `,\n  // TODO 2: Importá FormsModule desde '@angular/forms' y agregalo a este array `imports`\n  imports: [],\n})\nexport class Leccion15User {\n  username = 'youngTech';\n  favoriteFramework = '';\n}\n",
  "src/app/tutorial/16-form-control-values/leccion.ts": "import { Component } from '@angular/core';\nimport { Leccion16User } from './user';\n\n/**\n * LECCIÓN 16 — Obtener el valor de un control de formulario\n *\n * Shell de la lección: muestra el componente <leccion-16-user />, que es\n * donde está todo el ejercicio.\n *\n * Abrí http://localhost:4200/tutorial/16 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/16/solucion\n */\n@Component({\n  selector: 'leccion-16',\n  template: ` <leccion-16-user /> `,\n  imports: [Leccion16User],\n})\nexport class Leccion16 {}\n",
  "src/app/tutorial/16-form-control-values/README.md": "# Lección 16 — Obtener el valor de un control de formulario\n\n> Original: [Getting form control value](https://v20.angular.dev/tutorials/learn-angular/16-form-control-values)\n\nAhora que tus formularios ya están armados con Angular, el próximo paso es **acceder a los valores** de los controles del formulario.\n\nEn esta lección vas a aprender a obtener el valor de un input de tu formulario.\n\n> **Nota:** podés leer más sobre cómo agregar un control de formulario básico en la [guía en profundidad](https://v20.angular.dev/guide/forms/reactive-forms#adding-a-basic-form-control).\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/16>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/16/solucion>\n\n## Archivos de trabajo\n\n`src/app/tutorial/16-form-control-values/user.ts`\n\nBuscá los comentarios `// TODO 1` y `// TODO 2` y completalos. El shell (`leccion.ts`) no necesita cambios. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Mostrar el valor del input en el template\n\nPara mostrar el valor del input en una plantilla, podés usar la sintaxis de interpolación `{{}}`, igual que con cualquier otra propiedad de la clase del componente:\n\n```angular-ts {highlight:[5]}\n@Component({\n  selector: 'app-user',\n  template: `\n    ...\n    <p>Framework: {{ favoriteFramework }}</p>\n    <label for=\"framework\">\n      Favorite Framework:\n      <input id=\"framework\" type=\"text\" [(ngModel)]=\"favoriteFramework\" />\n    </label>\n  `,\n})\nexport class User {\n  favoriteFramework = '';\n}\n```\n\nEn la lección, actualizá el `<p>Framework:</p>` de `user.ts` para que muestre `{{ favoriteFramework }}`. Al escribir en el input, vas a ver el texto reflejado en vivo.\n\n### 2. Obtener el valor del input desde la clase\n\nCuando necesitás referenciar el valor del campo de input dentro de la clase del componente, lo hacés accediendo a la propiedad de la clase con la sintaxis `this`:\n\n```angular-ts {highlight:[15]}\n// ...\n@Component({\n  selector: 'app-user',\n  template: `\n    ...\n    <button (click)=\"showFramework()\">Show Framework</button>\n  `,\n  // ...\n})\nexport class User {\n  favoriteFramework = '';\n  // ...\n\n  showFramework() {\n    alert(this.favoriteFramework);\n  }\n}\n```\n\nEn la lección, completá el método `showFramework()` de `user.ts` para que muestre un `alert` con `this.favoriteFramework`. Al hacer clic en el botón **Show Framework**, vas a ver el valor actual del input en un alerta.\n\n## Para cerrar\n\n¡Buen trabajo aprendiendo a mostrar los valores del input en tu template y a acceder a ellos programáticamente! 🎉\n\nEs momento de avanzar hacia la próxima forma de manejar formularios con Angular: los **formularios reactivos**. Si querés saber más sobre los formularios template-driven, revisá la [documentación de formularios de Angular](https://v20.angular.dev/guide/forms/template-driven-forms).\n\nCompará tu resultado con la solución en `/tutorial/16/solucion` y seguí con la [Lección 17](http://localhost:4200/tutorial/17).\n",
  "src/app/tutorial/16-form-control-values/user.ts": "import { Component } from '@angular/core';\nimport { FormsModule } from '@angular/forms';\n\n/**\n * LECCIÓN 16 — Componente User: leer el valor del control de formulario\n *\n * Acá está el ejercicio: mostrar el valor del input en el template y\n * accederlo desde la clase.\n *\n * Abrí http://localhost:4200/tutorial/16 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/16/solucion\n */\n@Component({\n  selector: 'leccion-16-user',\n  template: `\n    <p>Username: {{ username }}</p>\n    <!-- TODO 1: Mostrá el valor del input con interpolación, cambiando esta línea por: <p>Framework: {{ favoriteFramework }}</p> -->\n    <p>Framework:</p>\n    <label for=\"framework\">\n      Favorite Framework:\n      <input id=\"framework\" type=\"text\" [(ngModel)]=\"favoriteFramework\" />\n    </label>\n    <button (click)=\"showFramework()\">Show Framework</button>\n  `,\n  imports: [FormsModule],\n})\nexport class Leccion16User {\n  favoriteFramework = '';\n  username = 'youngTech';\n\n  showFramework() {\n    // TODO 2: Mostrá el valor del input con alert(this.favoriteFramework)\n  }\n}\n",
  "src/app/tutorial/17-reactive-forms/leccion.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 17 — Formularios reactivos\n *\n * Los formularios reactivos permiten manejar los formularios por código\n * (en la clase del componente) en lugar de depender solo de la plantilla.\n *\n * Abrí http://localhost:4200/tutorial/17 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/17/solucion\n */\n@Component({\n  selector: 'leccion-17',\n  template: `\n    <!-- TODO 6: Agregá la directiva [formGroup]=\"profileForm\" al form y el\n         evento (ngSubmit)=\"handleSubmit()\" para manejar el envío -->\n    <form>\n      <label>\n        Name\n        <input type=\"text\" formControlName=\"name\" />\n      </label>\n      <label>\n        Email\n        <input type=\"email\" formControlName=\"email\" />\n      </label>\n      <button type=\"submit\">Submit</button>\n    </form>\n\n    <!-- TODO 4: Mostrá los valores del formulario:\n         un <h2>Profile Form</h2> y dos <p> con profileForm.value.name y\n         profileForm.value.email -->\n  `,\n  // TODO 1: Importá ReactiveFormsModule desde '@angular/forms' y agregalo a\n  // este array `imports` del componente\n  imports: [],\n})\nexport class Leccion17 {\n  // TODO 2: Creá la propiedad `profileForm` como un FormGroup con los\n  // controles `name` y `email` (usá FormControl de '@angular/forms')\n  //\n  // TODO 5: Agregá el método handleSubmit() que muestre con alert() los\n  // valores del formulario\n}\n",
  "src/app/tutorial/17-reactive-forms/README.md": "# Lección 17 — Formularios reactivos\n\n> Original: [Reactive Forms](https://v20.angular.dev/tutorials/learn-angular/17-reactive-forms)\n\nCuando querés manejar tus formularios de forma programática, en lugar de depender únicamente de la plantilla, los formularios reactivos son la respuesta.\n\n> Nota: aprendé más sobre [formularios reactivos en la guía en profundidad](https://v20.angular.dev/guide/forms/reactive-forms).\n\nEn esta actividad vas a aprender a configurar formularios reactivos.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/17>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/17/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/17-reactive-forms/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Importar `ReactiveFormsModule`\n\nEn `leccion.ts`, importá `ReactiveFormsModule` desde `@angular/forms` y agregalo al array `imports` del componente.\n\n```ts\nimport { ReactiveFormsModule } from '@angular/forms';\n\n@Component({\n  selector: 'app-root',\n  template: `\n    <form>\n      <label>Name\n        <input type=\"text\" />\n      </label>\n      <label>Email\n        <input type=\"email\" />\n      </label>\n      <button type=\"submit\">Submit</button>\n    </form>\n  `,\n  imports: [ReactiveFormsModule],\n})\n```\n\n### 2. Crear el objeto `FormGroup` con FormControls\n\nLos formularios reactivos usan la clase `FormControl` para representar los controles del formulario (por ejemplo, los inputs). Angular provee la clase `FormGroup` para agrupar form controls en un objeto que hace más cómodo manejar formularios grandes.\n\nAgregá `FormControl` y `FormGroup` al import desde `@angular/forms` para poder crear un `FormGroup` con las propiedades `name` y `email` como FormControls:\n\n```ts\nimport { ReactiveFormsModule, FormControl, FormGroup } from '@angular/forms';\n...\nexport class App {\n  profileForm = new FormGroup({\n    name: new FormControl(''),\n    email: new FormControl(''),\n  });\n}\n```\n\n### 3. Vincular el FormGroup y los FormControls al formulario\n\nCada `FormGroup` debe asociarse a un formulario con la directiva `[formGroup]`.\n\nAdemás, cada `FormControl` se conecta con la directiva `formControlName` y la propiedad correspondiente. Actualizá la plantilla con el siguiente código del formulario:\n\n```html\n<form [formGroup]=\"profileForm\">\n  <label>\n    Name\n    <input type=\"text\" formControlName=\"name\" />\n  </label>\n  <label>\n    Email\n    <input type=\"email\" formControlName=\"email\" />\n  </label>\n  <button type=\"submit\">Submit</button>\n</form>\n```\n\n### 4. Mostrar los valores del formulario\n\nCuando quieras acceder a los datos de un `FormGroup`, podés hacerlo accediendo al valor (`value`) del grupo. Actualizá la `template` para mostrar los valores del formulario:\n\n```html\n...\n<h2>Profile Form</h2>\n<p>Name: {{ profileForm.value.name }}</p>\n<p>Email: {{ profileForm.value.email }}</p>\n```\n\n### 5. Manejar los cambios del formulario\n\nAccedé a los valores del `FormGroup` para trabajar con ellos. Agregá a la clase del componente un método llamado `handleSubmit` que vas a usar después para manejar el envío del formulario; este método mostrará los valores leídos del FormGroup:\n\n```ts\nhandleSubmit() {\n  alert(\n    this.profileForm.value.name + ' | ' + this.profileForm.value.email\n  );\n}\n```\n\n### 6. Agregar `ngSubmit` al formulario\n\nYa tenés acceso a los valores del formulario, ahora falta manejar el evento de envío y usar el método `handleSubmit`. Angular tiene un manejador de eventos para justo esto: `ngSubmit`. Actualizá el elemento `form` para que llame al método `handleSubmit` cuando se envíe el formulario:\n\n```html {highlight:[1]}\n<form [formGroup]=\"profileForm\" (ngSubmit)=\"handleSubmit()\"></form>\n```\n\n## Para cerrar\n\nY así de simple ya sabés trabajar con formularios reactivos en Angular.\n\n¡Excelente trabajo con esta actividad! Seguí para aprender sobre validación de formularios: compará tu resultado con la solución en `/tutorial/17/solucion` y continuá con la [Lección 18](http://localhost:4200/tutorial/18).\n",
  "src/app/tutorial/18-forms-validation/leccion.ts": "import { Component } from '@angular/core';\nimport { FormGroup, FormControl, ReactiveFormsModule } from '@angular/forms';\n\n/**\n * LECCIÓN 18 — Validación de formularios\n *\n * Otro escenario común al trabajar con formularios es validar los inputs\n * para asegurar que se envíen los datos correctos. Con formularios reactivos\n * esto se hace con la clase `Validators`.\n *\n * Abrí http://localhost:4200/tutorial/18 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/18/solucion\n */\n@Component({\n  selector: 'leccion-18',\n  template: `\n    <form [formGroup]=\"profileForm\">\n      <input type=\"text\" formControlName=\"name\" name=\"name\" />\n      <input type=\"email\" formControlName=\"email\" name=\"email\" />\n      <!-- TODO 3: Deshabilitá el botón mientras el formulario no sea válido\n           con el binding [disabled]=\"!profileForm.valid\" -->\n      <button type=\"submit\">Submit</button>\n    </form>\n  `,\n  imports: [ReactiveFormsModule],\n})\nexport class Leccion18 {\n  profileForm = new FormGroup({\n    // TODO 1: Importá `Validators` desde '@angular/forms'\n    //\n    // TODO 2: Agregá validaciones a los controles:\n    // - `name`: Validators.required\n    // - `email`: Validators.required y Validators.email combinados en un array\n    name: new FormControl(''),\n    email: new FormControl(''),\n  });\n}\n",
  "src/app/tutorial/18-forms-validation/README.md": "# Lección 18 — Validación de formularios\n\n> Original: [Validating forms](https://v20.angular.dev/tutorials/learn-angular/18-forms-validation)\n\nOtro escenario común al trabajar con formularios es la necesidad de validar los inputs para asegurar que se envíen los datos correctos.\n\n> Nota: aprendé más sobre [validar inputs de formularios en la guía en profundidad](https://v20.angular.dev/guide/forms/reactive-forms#validating-form-input).\n\nEn esta actividad vas a aprender a validar formularios con formularios reactivos.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/18>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/18/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/18-forms-validation/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Importar `Validators`\n\nAngular provee un conjunto de herramientas de validación. Para usarlas, primero actualizá el componente para importar `Validators` desde `@angular/forms`:\n\n```ts {highlight:[1]}\nimport { ReactiveFormsModule, Validators } from '@angular/forms';\n\n@Component({...})\nexport class App {}\n```\n\n### 2. Agregar validación al formulario\n\nA cada `FormControl` se le pueden pasar los `Validators` que quieras usar para validar sus valores. Por ejemplo, si querés que el campo `name` de `profileForm` sea obligatorio, usá `Validators.required`.\n\nPara el campo `email` queremos asegurarnos de que no quede vacío y que siga la estructura de una dirección de email válida. Esto se logra combinando los validadores `Validators.required` y `Validators.email` en un array.\n\nActualizá los `FormControl` de `name` y `email`:\n\n```ts\nprofileForm = new FormGroup({\n  name: new FormControl('', Validators.required),\n  email: new FormControl('', [Validators.required, Validators.email]),\n});\n```\n\n### 3. Chequear la validez del formulario en la plantilla\n\nPara determinar si un formulario es válido, la clase `FormGroup` tiene la propiedad `valid`. Podés usar esta propiedad para enlazar atributos dinámicamente. Actualizá el botón de envío para que esté habilitado según la validez del formulario:\n\n```html\n<button type=\"submit\" [disabled]=\"!profileForm.valid\">Submit</button>\n```\n\n## Para cerrar\n\nYa conocés los básicos de cómo funciona la validación con formularios reactivos.\n\n¡Gran trabajo aprendiendo estos conceptos centrales de los formularios en Angular! Si querés aprender más, consultá la [documentación de formularios de Angular](https://v20.angular.dev/guide/forms/form-validation). Compará tu resultado con la solución en `/tutorial/18/solucion` y seguí con la [Lección 19](http://localhost:4200/tutorial/19).\n",
  "src/app/tutorial/19-injectable-service/car.service.ts": "import { Injectable } from '@angular/core';\n\n/**\n * LECCIÓN 19 — Crear un servicio inyectable\n *\n * La inyección de dependencias (DI) es una de las características más\n * potentes de Angular: le permite al framework *proveer* en tiempo de\n * ejecución los recursos que tu aplicación necesita (como un servicio).\n *\n * NOTA: el tutorial oficial usa el decorador `@Service()`, que es muy nuevo.\n * En esta versión de Angular el equivalente es `@Injectable()` (mismo rol).\n *\n * Abrí http://localhost:4200/tutorial/19 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/19/solucion\n */\n// TODO 1: Agregá el decorador @Injectable({ providedIn: 'root' }) a la clase\n// Leccion19CarService para marcarla como servicio inyectable por el sistema\n// de DI. (El tutorial oficial usa @Service(), que se auto-provee; aquí el\n// equivalente es providedIn: 'root'.)\nexport class Leccion19CarService {\n  cars = ['Sunflower GT', 'Flexus Sport', 'Sprout Mach One'];\n\n  getCars(): string[] {\n    return this.cars;\n  }\n\n  getCar(id: number) {\n    return this.cars[id];\n  }\n}\n",
  "src/app/tutorial/19-injectable-service/leccion.ts": "import { Component, inject } from '@angular/core';\nimport { Leccion19CarService } from './car.service';\n\n/**\n * LECCIÓN 19 — Crear un servicio inyectable\n *\n * Este componente ya inyecta el servicio con `inject()` y lo usa para mostrar\n * la lista de autos. Tu trabajo está en ./car.service.ts: hacer que la clase\n * sea inyectable con el decorador @Service().\n *\n * Abrí http://localhost:4200/tutorial/19 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/19/solucion\n */\n@Component({\n  selector: 'leccion-19',\n  template: '<p> {{ carService.getCars() }} </p>',\n})\nexport class Leccion19 {\n  carService = inject(Leccion19CarService);\n}\n",
  "src/app/tutorial/19-injectable-service/README.md": "# Lección 19 — Crear un servicio inyectable\n\n> Original: [Creating an injectable service](https://v20.angular.dev/tutorials/learn-angular/19-creating-an-injectable-service)\n\nLa inyección de dependencias (DI) en Angular es una de las características más potentes del framework. Podés pensar en la inyección de dependencias como la capacidad de Angular de _proveer_ en tiempo de ejecución los recursos que tu aplicación necesita. Una dependencia puede ser un servicio u otro tipo de recurso.\n\n> Nota: aprendé más sobre [inyección de dependencias en la guía de fundamentos](https://v20.angular.dev/essentials/dependency-injection).\n\nEn esta actividad vas a aprender a crear un servicio `inyectable`.\n\nUna forma de usar un servicio es como intermediario para interactuar con datos y APIs. Para que un servicio sea reutilizable, la lógica debe quedarse en el servicio y compartirse por toda la aplicación cuando haga falta.\n\nPara que una clase pueda ser inyectada por el sistema de DI, se usa un decorador. El tutorial oficial usa `@Service()` (una API muy reciente que se auto-provee en el inyector raíz), pero en esta versión de Angular el equivalente es **`@Injectable({ providedIn: 'root' })`**. Por ejemplo:\n\n```ts {highlight:[1]}\n@Injectable({ providedIn: 'root' })\nclass UserService {\n  // métodos para obtener y devolver datos\n}\n```\n\nEl decorador `@Injectable` marca la clase como servicio y le notifica al sistema de DI que `UserService` puede usarse en cualquier parte de tu aplicación. Con `providedIn: 'root'`, Angular provee el servicio en toda la aplicación, así que no necesitás ninguna configuración extra.\n\n> Nota: podés aprender más en la [guía sobre cómo crear servicios inyectables](https://v20.angular.dev/guide/di/creating-injectable-service).\n\nMuy bien, ahora probalo vos:\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/19>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/19/solucion>\n\n> ⚠️ Mientras no completes el TODO, la página del ejercicio va a mostrar un error `NG0201: No provider found for Leccion19CarService` (en pantalla en blanco y en la consola). Es esperado: justamente ese es el problema que esta lección resuelve. Al agregar el decorador, la página va a funcionar.\n\n## Archivo de trabajo\n\n`src/app/tutorial/19-injectable-service/car.service.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Agregar el decorador `@Injectable`\n\nActualizá el código en `car.service.ts` agregando el decorador `@Injectable({ providedIn: 'root' })` a la clase del servicio:\n\n```ts\n@Injectable({ providedIn: 'root' })\nexport class CarService {\n  cars = ['Sunflower GT', 'Flexus Sport', 'Sprout Mach One'];\n\n  getCars(): string[] {\n    return this.cars;\n  }\n\n  getCar(id: number) {\n    return this.cars[id];\n  }\n}\n```\n\nTIP: usá el ejemplo de arriba para encontrar la sintaxis correcta.\n\n## Para cerrar\n\nBien hecho 👍 ese servicio ahora es `inyectable` y puede participar de la fiesta. Ahora que el servicio es inyectable, inyectemoslo en un componente 👉\n\nCompará tu resultado con la solución en `/tutorial/19/solucion` y seguí con la [Lección 20](http://localhost:4200/tutorial/20).\n",
  "src/app/tutorial/20-inject-based-di/car.service.ts": "import { Injectable } from '@angular/core';\n\n/**\n * LECCIÓN 20 — Servicio de autos\n *\n * Este servicio ya está decorado con @Injectable() (lo hiciste inyectable en\n * la lección 19). En esta lección lo vas a inyectar en el componente con\n * inject().\n */\n@Injectable({ providedIn: 'root' })\nexport class Leccion20CarService {\n  cars = ['Sunflower GT', 'Flexus Sport', 'Sprout Mach One'];\n\n  getCars(): string[] {\n    return this.cars;\n  }\n\n  getCar(id: number) {\n    return this.cars[id];\n  }\n}\n",
  "src/app/tutorial/20-inject-based-di/leccion.ts": "import { Component, inject } from '@angular/core';\nimport { Leccion20CarService } from './car.service';\n\n/**\n * LECCIÓN 20 — Inyección de dependencias con inject()\n *\n * Crear un servicio inyectable es la primera parte del sistema de DI de\n * Angular. ¿Cómo lo inyectás en un componente? Angular tiene la función\n * `inject()`, que se puede usar en el contexto adecuado.\n *\n * Es muy común inicializar propiedades de la clase con valores que provee el\n * sistema de DI:\n *\n *   carService = inject(Leccion20CarService);\n *\n * Abrí http://localhost:4200/tutorial/20 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/20/solucion\n */\n@Component({\n  selector: 'leccion-20',\n  // TODO 3: Actualizá la plantilla para mostrar la lista de autos:\n  // <p>Car Listing: {{ display }}</p>\n  template: ``,\n})\nexport class Leccion20 {\n  // TODO 1: Inyectá el Leccion20CarService con la función inject() y\n  // asignalo a una propiedad llamada `carService`\n  display = '';\n\n  // TODO 2: Inicializá la propiedad `display` con:\n  // this.carService.getCars().join(' ⭐️ ')\n}\n",
  "src/app/tutorial/20-inject-based-di/README.md": "# Lección 20 — Inyección de dependencias con inject()\n\n> Original: [Inject-based dependency injection](https://v20.angular.dev/tutorials/learn-angular/20-inject-based-di)\n\nCrear un servicio inyectable es la primera parte del sistema de inyección de dependencias (DI) de Angular. ¿Cómo inyectás un servicio en un componente? Angular tiene una función conveniente llamada `inject()` que puede usarse en el contexto adecuado.\n\n> Nota: los contextos de inyección quedan fuera del alcance de este tutorial, pero podés aprender más en la [guía de fundamentos de DI](https://v20.angular.dev/essentials/dependency-injection) y en la [guía de contextos de DI](https://v20.angular.dev/guide/di/dependency-injection-context).\n\nEn esta actividad vas a aprender a inyectar un servicio y usarlo en un componente.\n\nEs muy útil inicializar propiedades de una clase con valores que provee el sistema de DI. Por ejemplo:\n\n```ts {highlight:[3]}\n@Component({...})\nclass PetCareDashboard {\n  petRosterService = inject(PetRosterService);\n}\n```\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/20>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/20/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/20-inject-based-di/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\n### 1. Inyectar el servicio de autos\n\nEn `leccion.ts`, usando la función `inject()`, inyectá el servicio de autos y asignalo a una propiedad llamada `carService`:\n\n```ts\ncarService = inject(CarService);\n```\n\n> Nota: fijate la diferencia entre la propiedad `carService` (en minúsculas) y la clase `CarService`.\n\n### 2. Usar la instancia `carService`\n\nLlamar a `inject(CarService)` te dio una instancia del servicio que podés usar en tu aplicación, guardada en la propiedad `carService`.\n\nInicializá la propiedad `display` con la siguiente implementación:\n\n```ts\ndisplay = this.carService.getCars().join(' ⭐️ ');\n```\n\n### 3. Actualizar la plantilla\n\nActualizá la plantilla del componente con el siguiente código:\n\n```ts\ntemplate: `<p>Car Listing: {{ display }}</p>`,\n```\n\n## Para cerrar\n\nAcabás de inyectar tu primer servicio en un componente: ¡gran esfuerzo!\n\nCompará tu resultado con la solución en `/tutorial/20/solucion` y seguí con la [Lección 22](http://localhost:4200/tutorial/22).\n",
  "src/app/tutorial/22-pipes/leccion.ts": "import { Component } from '@angular/core';\n\n/**\n * LECCIÓN 22 — Pipes\n *\n * Los pipes son funciones que transforman datos directamente en las plantillas.\n * En general son funciones \"puras\" que no causan efectos secundarios. Angular\n * incluye varios pipes útiles que podés importar y usar en tus componentes.\n *\n * Abrí http://localhost:4200/tutorial/22 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/22/solucion\n */\n@Component({\n  selector: 'leccion-22',\n  template: `\n    <h2>Pipes</h2>\n    <p>Usuario: {{ username }}</p>\n  `,\n  imports: [],\n})\nexport class Leccion22 {\n  username = 'yOunGTECh';\n}\n",
  "src/app/tutorial/22-pipes/README.md": "# Lección 22 — Pipes\n\n> Original: [Pipes](https://v20.angular.dev/tutorials/learn-angular/22-pipes)\n\nLos pipes son funciones que se usan para transformar datos en las plantillas. En general, los pipes son funciones \"puras\" que no causan efectos secundarios. Angular tiene una serie de pipes integrados muy útiles que podés importar y usar en tus componentes. También podés crear un pipe personalizado.\n\n> NOTA: Aprendé más sobre los [pipes en la guía en profundidad](https://v20.angular.dev/guide/templates/pipes).\n\nEn esta actividad vas a importar un pipe y a usarlo en la plantilla.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/22>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/22/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/22-pipes/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\nPara usar un pipe en una plantilla, incluyalo en una expresión interpolada. Mirá este ejemplo:\n\n```ts\nimport { UpperCasePipe } from '@angular/common';\n\n@Component({\n  // ...\n  template: `{{ loudMessage | uppercase }}`,\n  imports: [UpperCasePipe],\n})\nexport class App {\n  loudMessage = 'we think you are doing great!';\n}\n```\n\nAhora te toca probarlo a vos:\n\n### 1. Importar el pipe `LowerCase`\n\nPrimero, actualizá `leccion.ts` agregando el import de archivo para `LowerCasePipe` desde `@angular/common`:\n\n```ts\nimport { LowerCasePipe } from '@angular/common';\n```\n\n### 2. Agregar el pipe a los imports de la plantilla\n\nDespués, actualizá los `imports` del decorador `@Component()` para incluir una referencia a `LowerCasePipe`:\n\n```ts\n@Component({\n  // ...\n  imports: [LowerCasePipe],\n})\n```\n\n### 3. Agregar el pipe a la plantilla\n\nPor último, en `leccion.ts` actualizá la plantilla para incluir el pipe `lowercase`:\n\n```ts\ntemplate: `{{ username | lowercase }}`,\n```\n\n## Para cerrar\n\nLos pipes también pueden aceptar parámetros, que se usan para configurar su salida. Vas a descubrir más en la próxima actividad.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/22/solucion` y seguí con la [Lección 23](http://localhost:4200/tutorial/23).\n",
  "src/app/tutorial/23-pipes-format-data/leccion.ts": "import { Component } from '@angular/core';\nimport { CurrencyPipe, DatePipe, DecimalPipe } from '@angular/common';\n\n/**\n * LECCIÓN 23 — Formatear datos con pipes\n *\n * Podés llevar el uso de pipes más allá configurándolos: los pipes aceptan\n * parámetros usando la sintaxis `:` seguida del valor del parámetro.\n * Ejemplo: `{{ date | date: 'medium' }}` produce `Jun 15, 2015, 9:43:11 PM`.\n *\n * Abrí http://localhost:4200/tutorial/23 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/23/solucion\n */\n@Component({\n  selector: 'leccion-23',\n  template: `\n    <h2>Formatear datos con pipes</h2>\n    <ul>\n      <!-- TODO 1: Usá el pipe \"number\" con el parámetro '3.2-2' sobre la expresión de num -->\n      <li>Number with \"decimal\" {{ num }}</li>\n      <!-- TODO 2: Usá el pipe \"date\" con el parámetro 'medium' sobre la expresión de birthday -->\n      <li>Date with \"date\" {{ birthday }}</li>\n      <!-- TODO 3: Usá el pipe \"currency\" sobre la expresión de cost -->\n      <li>Currency with \"currency\" {{ cost }}</li>\n    </ul>\n  `,\n  imports: [DecimalPipe, DatePipe, CurrencyPipe],\n})\nexport class Leccion23 {\n  num = 103.1234;\n  birthday = new Date(2023, 3, 2);\n  cost = 4560.34;\n}\n",
  "src/app/tutorial/23-pipes-format-data/README.md": "# Lección 23 — Formatear datos con pipes\n\n> Original: [Formatting data with pipes](https://v20.angular.dev/tutorials/learn-angular/23-pipes-format-data)\n\nPodés llevar tu uso de pipes aún más lejos configurándolos. Los pipes se pueden configurar pasándoles opciones.\n\n> NOTA: Aprendé más sobre [formatear datos con pipes en la guía en profundidad](https://v20.angular.dev/guide/templates/pipes).\n\nEn esta actividad vas a trabajar con algunos pipes y parámetros de pipes.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/23>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/23/solucion>\n\n## Archivo de trabajo\n\n`src/app/tutorial/23-pipes-format-data/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\nPara pasar parámetros a un pipe, usá la sintaxis `:` seguida del valor del parámetro. Acá hay un ejemplo:\n\n```ts\ntemplate: `{{ date | date: 'medium' }}`;\n```\n\nLa salida es `Jun 15, 2015, 9:43:11 PM`.\n\nEs hora de personalizar la salida de algunos pipes:\n\n### 1. Formatear un número con `DecimalPipe`\n\nEn `leccion.ts`, actualizá la plantilla para incluir un parámetro en el pipe `number`:\n\n```html\ntemplate: ` ...\n<li>Number with \"decimal\" {{ num | number: '3.2-2' }}</li>\n`\n```\n\n> NOTA: ¿Qué es ese formato? El parámetro del `DecimalPipe` se llama `digitsInfo`, y usa el formato `{minIntegerDigits}.{minFractionDigits}-{maxFractionDigits}`.\n\n### 2. Formatear una fecha con `DatePipe`\n\nAhora, actualizá la plantilla para usar el pipe `date`:\n\n```html\ntemplate: ` ...\n<li>Date with \"date\" {{ birthday | date: 'medium' }}</li>\n`\n```\n\nComo extra, probá diferentes parámetros para `date`. Encontrá más información en la [documentación de Angular](https://v20.angular.dev/guide/templates/pipes).\n\n### 3. Formatear una moneda con `CurrencyPipe`\n\nComo última tarea, actualizá la plantilla para usar el pipe `currency`:\n\n```html\ntemplate: ` ...\n<li>Currency with \"currency\" {{ cost | currency }}</li>\n`\n```\n\nTambién podés probar diferentes parámetros para `currency`. Encontrá más información en la [documentación de Angular](https://v20.angular.dev/guide/templates/pipes).\n\n## Para cerrar\n\nBuen trabajo con los pipes. Viniste avanzando muy bien.\n\nHay aún más pipes integrados que podés usar en tus aplicaciones. Encontrás la lista en la [documentación de Angular](https://v20.angular.dev/guide/templates/pipes).\n\nEn el caso de que los pipes integrados no cubran tus necesidades, también podés crear un pipe personalizado. Mirá la próxima lección para saber más.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/23/solucion` y seguí con la [Lección 24](http://localhost:4200/tutorial/24).\n",
  "src/app/tutorial/24-create-a-pipe/leccion.ts": "import { Component } from '@angular/core';\nimport { Leccion24ReversePipe } from './reverse.pipe';\n\n/**\n * LECCIÓN 24 — Crear un pipe personalizado\n *\n * Podés crear pipes personalizados en Angular para adaptarlos a tus\n * necesidades de transformación de datos.\n *\n * Abrí http://localhost:4200/tutorial/24 para ver el resultado en vivo.\n * La versión resuelta está en http://localhost:4200/tutorial/24/solucion\n */\n@Component({\n  selector: 'leccion-24',\n  template: `\n    <h2>Crear un pipe personalizado</h2>\n    <p> Reverse Machine: {{ word }} </p>\n  `,\n  imports: [],\n})\nexport class Leccion24 {\n  word = 'You are a champion';\n}\n",
  "src/app/tutorial/24-create-a-pipe/README.md": "# Lección 24 — Crear un pipe personalizado\n\n> Original: [Create a custom pipe](https://v20.angular.dev/tutorials/learn-angular/24-create-a-pipe)\n\nPodés crear pipes personalizados en Angular para adaptarlos a tus necesidades de transformación de datos.\n\n> NOTA: Aprendé más sobre [crear pipes personalizados en la guía en profundidad](https://v20.angular.dev/guide/templates/pipes#creating-custom-pipes).\n\nEn esta actividad vas a crear un pipe personalizado y a usarlo en tu plantilla.\n\n## Cómo verla en el navegador\n\n1. Levantá el servidor de desarrollo: `npm start`\n2. Ejercicio: <http://localhost:4200/tutorial/24>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/tutorial/24/solucion>\n\n## Archivos de trabajo\n\n- `src/app/tutorial/24-create-a-pipe/reverse.pipe.ts`\n- `src/app/tutorial/24-create-a-pipe/leccion.ts`\n\nBuscá los comentarios `// TODO` y completalos. Al guardar, el navegador se recarga solo.\n\n## Pasos\n\nUn pipe es una clase TypeScript con un decorador `@Pipe`. Acá hay un ejemplo:\n\n```ts\nimport { Pipe, PipeTransform } from '@angular/core';\n\n@Pipe({\n  name: 'star',\n})\nexport class StarPipe implements PipeTransform {\n  transform(value: string): string {\n    return `⭐️ ${value} ⭐️`;\n  }\n}\n```\n\nLa `StarPipe` acepta un valor de tipo string y devuelve ese string con estrellas alrededor. Tené en cuenta que:\n\n- el `name` en la configuración del decorador `@Pipe` es lo que se va a usar en la plantilla\n- la función `transform` es donde ponés tu lógica\n\nBien, te toca probar a vos — vas a crear el `ReversePipe`:\n\n### 1. Crear el `ReversePipe`\n\nEn `reverse.pipe.ts`, agregá el decorador `@Pipe` a la clase `Leccion24ReversePipe` con la siguiente configuración:\n\n```ts\n@Pipe({\n  name: 'tutorialReverse',\n})\n```\n\n> En este proyecto el pipe se llama `tutorialReverse` (y `tutorialReverseSolucion` en la solución) para que su nombre no choque con el de otras lecciones.\n\n### 2. Implementar la función `transform`\n\nAhora la clase `Leccion24ReversePipe` es un pipe. Actualizá la función `transform` para agregar la lógica de inversión:\n\n```ts\nexport class Leccion24ReversePipe implements PipeTransform {\n  transform(value: string): string {\n    let reverse = '';\n\n    for (let i = value.length - 1; i >= 0; i--) {\n      reverse += value[i];\n    }\n\n    return reverse;\n  }\n}\n```\n\n### 3. Usar el `ReversePipe` en la plantilla\n\nCon la lógica del pipe implementada, el último paso es usarlo en la plantilla. En `leccion.ts` incluí el pipe en la plantilla y agregalo a los imports del componente:\n\n```ts\n@Component({\n  // ...\n  template: `Reverse Machine: {{ word | tutorialReverse }}`,\n  imports: [Leccion24ReversePipe],\n})\n```\n\n## Para cerrar\n\nY con eso lo lograste. Felicitaciones por completar esta actividad. Ahora sabés cómo usar pipes e incluso cómo implementar tus propios pipes personalizados.\n\n¿Listo? Compará tu resultado con la solución en `/tutorial/24/solucion` y seguí con la [Lección 25](http://localhost:4200/tutorial/25).\n",
  "src/app/tutorial/24-create-a-pipe/reverse.pipe.ts": "import { Pipe, PipeTransform } from '@angular/core';\n\n/**\n * LECCIÓN 24 — Pipe personalizado \"Reverse\"\n *\n * Un pipe es una clase TypeScript con el decorador `@Pipe`:\n *   - El `name` en la configuración de `@Pipe` es lo que se usa en la plantilla.\n *   - La función `transform` es donde va tu lógica.\n *\n * TODO 1: Agregá el decorador `@Pipe` a la clase con la configuración:\n *           @Pipe({ name: 'tutorialReverse' })\n * TODO 2: Implementá la lógica para invertir el string dentro de `transform`\n *         (recorré el valor desde el final hacia el principio y armá el resultado).\n */\nexport class Leccion24ReversePipe implements PipeTransform {\n  transform(value: string): string {\n    // TODO 2: Reemplazá este return vacío por la lógica que invierte el texto\n    return '';\n  }\n}\n",
  "src/app/tutorial/25-next-steps/leccion.ts": "import { Component } from '@angular/core';\nimport { RouterLink } from '@angular/router';\n\n/**\n * LECCIÓN 25 — Próximos pasos (solo lectura)\n *\n * ¡Completaste el tutorial Learn Angular! Esta lección no tiene ejercicio:\n * es un cierre con recursos para seguir aprendiendo.\n */\n@Component({\n  selector: 'leccion-25',\n  template: `\n    <main class=\"contenedor\">\n      <h1>¿Listo para explorar más de Angular? 🎉</h1>\n      <p class=\"burbuja\">\n        ¡Lo lograste! Completaste el tutorial Learn Angular y aprendiste lo\n        esencial para construir aplicaciones.\n      </p>\n\n      <div class=\"tarjetas\">\n        <a\n          class=\"tarjeta\"\n          href=\"https://v20.angular.dev/roadmap\"\n          target=\"_blank\"\n          rel=\"noopener\"\n        >\n          <h3>Hoja de ruta de Angular</h3>\n          <p>Leé el roadmap open source de Angular: proyectos actuales, futuros y completados.</p>\n        </a>\n        <a\n          class=\"tarjeta\"\n          href=\"https://v20.angular.dev/playground\"\n          target=\"_blank\"\n          rel=\"noopener\"\n        >\n          <h3>Zona de juegos</h3>\n          <p>¡Jugá con Angular directamente en tu navegador!</p>\n        </a>\n        <a\n          class=\"tarjeta\"\n          href=\"https://youtube.com/playlist?list=PL1w1q3fL4pmj9k1FrJ3Pe91EPub2_h4jF\"\n          target=\"_blank\"\n          rel=\"noopener\"\n        >\n          <h3>Curso de Angular en YouTube</h3>\n          <p>Mirá el canal oficial de Angular en YouTube: videos y cursos.</p>\n        </a>\n        <a\n          class=\"tarjeta\"\n          href=\"https://www.youtube.com/watch?v=JWhRMyyF7nc&amp;t=36s\"\n          target=\"_blank\"\n          rel=\"noopener\"\n        >\n          <h3>Angular de la A a la Z</h3>\n          <p>Tutorial completo de Envato para principiantes: repasa Angular entero en un solo video.</p>\n        </a>\n        <a\n          class=\"tarjeta\"\n          href=\"https://www.youtube.com/watch?v=rZCQiMdQsxE&amp;list=PLfyWdpsiUiPApyjPvz7Ms6D6IXhoimQBW\"\n          target=\"_blank\"\n          rel=\"noopener\"\n        >\n          <h3>Serie completa de Angular</h3>\n          <p>Playlist de Nihira Techiees que cubre Angular capítulo por capítulo, desde cero.</p>\n        </a>\n        <a\n          class=\"tarjeta\"\n          href=\"https://hackernoon.com/how-to-build-an-employee-management-crud-app-with-angular-and-material-ui\"\n          target=\"_blank\"\n          rel=\"noopener\"\n        >\n          <h3>CRUD con Angular y Material UI</h3>\n          <p>Artículo de Hackernoon: construí una app de gestión de empleados paso a paso.</p>\n        </a>\n        <a class=\"tarjeta\" routerLink=\"/extras\">\n          <h3>Prácticas avanzadas 🧪</h3>\n          <p>\n            El aprendizaje sigue acá: escenarios de trabajo real para seguir practicando lo\n            visto. ¡Y más, con nuevas actividades en camino!\n          </p>\n        </a>\n      </div>\n\n      <a class=\"volver\" routerLink=\"/tutorial\">← Volver al índice del tutorial</a>\n    </main>\n  `,\n  imports: [RouterLink],\n  styles: `\n    .contenedor {\n      max-width: 860px;\n      margin: 0 auto;\n      padding: 2rem 1rem;\n      font-family: system-ui, sans-serif;\n    }\n    h1 {\n      margin: 0 0 1rem;\n    }\n    .burbuja {\n      background: var(--acento-suave);\n      border: 1px solid color-mix(in srgb, var(--acento) 18%, transparent);\n      border-radius: 12px;\n      padding: 1rem 1.25rem;\n      line-height: 1.5;\n    }\n    .tarjetas {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n      gap: 1rem;\n      margin: 1.5rem 0;\n    }\n    .tarjeta {\n      border: 1px solid var(--borde);\n      border-radius: 12px;\n      padding: 1rem 1.25rem;\n      text-decoration: none;\n      color: inherit;\n      background: var(--superficie);\n      box-shadow: var(--sombra-tarjeta);\n      transition: border-color 0.2s ease, transform 0.18s ease;\n    }\n    .tarjeta:hover {\n      border-color: var(--acento);\n      transform: translateY(-2px);\n    }\n    .tarjeta:focus-visible {\n      outline: 2px solid var(--acento);\n      outline-offset: 2px;\n    }\n    .tarjeta h3 {\n      margin: 0 0 0.5rem;\n      font-size: 1.05rem;\n      color: var(--acento);\n    }\n    .tarjeta p {\n      margin: 0;\n      color: var(--texto-suave);\n      font-size: 0.9rem;\n      line-height: 1.45;\n    }\n    .volver {\n      color: var(--acento);\n    }\n  `,\n})\nexport class Leccion25 {}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/notificaciones-bus.ts": "import { Injectable } from '@angular/core';\nimport { Subject } from 'rxjs';\n\n/**\n * Eventos que circulan por el bus de la práctica.\n *\n * Es una \"unión discriminada\": el campo `tipo` le permite a TypeScript\n * saber qué otras propiedades tiene el evento dentro de cada `case`.\n */\nexport type EventoBus =\n  | { tipo: 'agregado'; id: number; nombre: string; cantidad: number }\n  | { tipo: 'eliminado'; id: number; nombre: string };\n\n/**\n * BUS DE EVENTOS\n *\n * Servicio desacoplado que permite que componentes LEJANOS se comuniquen\n * sin pasarse datos uno por uno (eso se llama \"prop drilling\").\n *\n * ¿Cómo funciona?\n * - Un `Subject` es como una radio emisora: quien llama `.next(valor)` emite,\n *   y todos los suscriptos con `.subscribe()` lo reciben al instante.\n * - El Subject es PRIVADO; afuera se expone como `Observable` de solo lectura\n *   (con `asObservable()`) para que nadie pueda emitir \"de contrabando\".\n * - Al ser `providedIn: 'root'`, TODOS los componentes comparten la misma\n *   instancia: por eso lo que emite el nieto lo escucha el abuelo.\n */\n@Injectable({ providedIn: 'root' })\nexport class NotificacionesBus {\n  /** La emisora. Privada: solo el bus puede emitir con `.next()`. */\n  private readonly eventos = new Subject<EventoBus>();\n\n  /** El flujo de solo lectura que consumen los componentes. */\n  readonly eventos$ = this.eventos.asObservable();\n\n  notificarProductoAgregado(id: number, nombre: string, cantidad: number): void {\n    // TODO: [Paso 2] - Emití el evento por el Subject:\n    //   this.eventos.next({ tipo: 'agregado', id, nombre, cantidad });\n    // (fijate que con el shorthand de objetos { id, nombre } alcanza si el\n    //  nombre de la variable coincide con la propiedad).\n  }\n\n  notificarProductoEliminado(id: number, nombre: string): void {\n    // TODO: [Paso 3] - Emití el evento por el Subject:\n    //   this.eventos.next({ tipo: 'eliminado', id, nombre });\n  }\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto-fila.css": "/* El <tr> vive dentro del host (producto-fila): lo volvemos transparente\n   con `display: contents` para que la fila participe directo de la grilla\n   de la tabla y respete las columnas fijas (simetría garantizada). */\n:host {\n  display: contents;\n}\n\ntd {\n  padding: 0.6rem 0.75rem;\n  border-bottom: 1px solid var(--borde);\n  vertical-align: middle;\n}\n\n/* Precio: alineado a la derecha y con dígitos tabulares para que\n   todas las filas queden perfectamente alineadas entre sí. */\ntd.precio {\n  text-align: right;\n  font-variant-numeric: tabular-nums;\n  color: var(--texto-suave);\n}\n\n/* Resaltado sutil de la fila al pasar el mouse */\n:host(:hover) td {\n  background: var(--acento-suave);\n}\n\n/* ─── Acciones de compra/eliminación ────────────────────────────── */\n.acciones {\n  display: flex;\n  align-items: center;\n  gap: 0.5rem;\n}\n\nbutton.primario {\n  border: 1px solid var(--acento);\n  background: var(--acento);\n  color: var(--acento-contraste);\n  border-radius: 6px;\n  padding: 0.3rem 0.7rem;\n  font-size: 0.85rem;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\nbutton.primario:hover {\n  background: var(--acento-fuerte);\n  border-color: var(--acento-fuerte);\n}\n\nbutton.peligro {\n  border: 1px solid color-mix(in srgb, var(--error) 45%, transparent);\n  background: var(--error-fondo);\n  color: var(--error);\n  border-radius: 6px;\n  padding: 0.3rem 0.55rem;\n  font-size: 0.85rem;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\nbutton.peligro:hover {\n  border-color: var(--error);\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto-fila.html": "<tr>\n  <td>{{ producto().nombre }}</td>\n  <td class=\"precio\">{{ producto().precio | currency: 'ARS' : 'symbol' : '1.0-0' }}</td>\n  <td class=\"acciones\">\n    <selector-cantidad [(cantidad)]=\"cantidad\" />\n    <button type=\"button\" class=\"primario\" (click)=\"agregar()\">➕ Agregar</button>\n    <button type=\"button\" class=\"peligro\" (click)=\"eliminar()\" aria-label=\"Eliminar producto\">\n      🗑️\n    </button>\n  </td>\n</tr>\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto-fila.ts": "import { CurrencyPipe } from '@angular/common';\nimport { Component, inject, input, signal } from '@angular/core';\nimport { NotificacionesBus } from './notificaciones-bus';\nimport { Producto } from './producto';\nimport { SelectorCantidad } from './selector-cantidad';\n\n/**\n * FILA DE PRODUCTO — el componente NIETO 🧓 → 👨 → 👶\n *\n * Vive dentro de `producto-tabla` (hijo), que vive dentro de\n * `productos-page` (abuelo).\n *\n * Fijate en el detalle importante: acá NO hay outputs. La comunicación con\n * el abuelo NO viaja de hijo en hijo, sino que va directa por el\n * `NotificacionesBus` (inyectado con la función `inject()`).\n */\n@Component({\n  selector: 'producto-fila',\n  imports: [SelectorCantidad, CurrencyPipe],\n  templateUrl: './producto-fila.html',\n  styleUrl: './producto-fila.css',\n})\nexport class ProductoFila {\n  /** Con inject() no necesitamos constructor: una línea por dependencia. */\n  protected readonly bus = inject(NotificacionesBus);\n\n  /** El producto que el abuelo manda a dibujar. `required` = obligatorio. */\n  producto = input.required<Producto>();\n\n  /** Cantidad local elegida para este producto (enlazada al selector). */\n  protected readonly cantidad = signal(1);\n\n  agregar(): void {\n    // TODO: [Paso 4a] - Avisale al bus que el usuario quiere agregar este\n    // producto con la cantidad elegida:\n    //   this.bus.notificarProductoAgregado(\n    //     this.producto().id,\n    //     this.producto().nombre,\n    //     this.cantidad(),\n    //   );\n  }\n\n  eliminar(): void {\n    // TODO: [Paso 4b] - Avisale al bus que hay que eliminar este producto:\n    //   this.bus.notificarProductoEliminado(this.producto().id, this.producto().nombre);\n    // No hacés la eliminación acá: el ABUELO es el dueño de la lista y\n    // decide qué hacer con el evento. ¡Separación de responsabilidades!\n  }\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto-tabla.css": "/* ─── Tabla de productos: grilla simétrica ──────────────────────── */\ntable {\n  width: 100%;\n  border-collapse: collapse;\n  /* Anchos de columna fijos: todas las filas comparten la misma grilla */\n  table-layout: fixed;\n}\n\nth,\ntd {\n  text-align: left;\n  padding: 0.6rem 0.75rem;\n  border-bottom: 1px solid var(--borde);\n}\n\nth {\n  font-size: 0.78rem;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n  color: var(--texto-suave);\n}\n\n/* Proporciones: producto 38% · precio 22% · acciones 40% */\nth:nth-child(1) {\n  width: 38%;\n}\n\nth:nth-child(2) {\n  width: 22%;\n  text-align: right;\n}\n\nth:nth-child(3) {\n  width: 40%;\n}\n\n.vacio {\n  text-align: center;\n  color: var(--texto-suave);\n  padding: 1.5rem;\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto-tabla.html": "<table>\n  <thead>\n    <tr>\n      <th>Producto</th>\n      <th>Precio</th>\n      <th>Acciones</th>\n    </tr>\n  </thead>\n  <tbody>\n    @for (item of productos(); track item.id) {\n      <producto-fila [producto]=\"item\" />\n    } @empty {\n      <tr>\n        <td colspan=\"3\" class=\"vacio\">Catálogo vacío 🕳️</td>\n      </tr>\n    }\n  </tbody>\n</table>\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto-tabla.ts": "import { Component, input } from '@angular/core';\nimport { ProductoFila } from './producto-fila';\nimport { Producto } from './producto';\n\n/**\n * TABLA DE PRODUCTOS — el componente HIJO puente 🧓 → 👨\n *\n * Recibe el listado del abuelo por input() y dibuja una fila por producto\n * con el nuevo control de flujo `@for` (siempre con `track`).\n *\n * Detalle clave para la práctica: este componente NO tiene outputs ni\n * inyecta el bus. Es solo un puente de renderizado. Si tuviéramos que\n * reenviar eventos del nieto al abuelo por acá, sería \"prop drilling\".\n * El bus de eventos evita justamente eso.\n */\n@Component({\n  selector: 'producto-tabla',\n  imports: [ProductoFila],\n  templateUrl: './producto-tabla.html',\n  styleUrl: './producto-tabla.css',\n})\nexport class ProductoTabla {\n  productos = input.required<Producto[]>();\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/producto.ts": "/**\n * Modelo compartido de la Práctica 01.\n *\n * Un `interface` (no una clase) es lo recomendable para modelar datos\n * que viajan por la app: no genera código en runtime, solo tipos.\n */\nexport interface Producto {\n  id: number;\n  nombre: string;\n  precio: number;\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/productos-page.css": "/* ─── Página de productos: layout de dos columnas ───────────────── */\n.layout {\n  display: grid;\n  gap: 1rem;\n  max-width: 900px;\n  margin: 0 auto;\n  padding: 1rem;\n}\n\n@media (min-width: 720px) {\n  .layout {\n    grid-template-columns: 2fr 1fr;\n    align-items: start;\n  }\n}\n\n.panel {\n  border: 1px solid var(--borde);\n  border-radius: 12px;\n  padding: 1rem 1.25rem;\n  background: var(--superficie);\n  box-shadow: var(--sombra-tarjeta);\n  margin-bottom: 1rem;\n}\n\n.panel h2 {\n  margin-top: 0;\n}\n\n.ayuda {\n  color: var(--texto-suave);\n  font-size: 0.88rem;\n  line-height: 1.5;\n}\n\n.total {\n  margin-top: 0.75rem;\n}\n\n.carrito-demo {\n  display: flex;\n  align-items: center;\n  gap: 0.75rem;\n}\n\n.valor-elegido {\n  color: var(--acento);\n  font-weight: 600;\n}\n\n.notificaciones {\n  margin: 0;\n  padding-left: 1.25rem;\n  line-height: 1.7;\n  font-size: 0.9rem;\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/productos-page.html": "<div class=\"layout\">\n  <section class=\"panel\">\n    <h2>Catálogo</h2>\n    <p class=\"ayuda\">\n      Las filas son el componente <strong>nieto</strong> (<code>producto-fila</code>). Al\n      eliminar o agregar, el nieto avisa a este <strong>abuelo</strong> a través del\n      <code>NotificacionesBus</code> sin pasar por <code>producto-tabla</code> (hijo).\n    </p>\n\n    <producto-tabla [productos]=\"productos()\" />\n\n    <p class=\"total\">\n      Valor del catálogo:\n      <strong>{{ total() | currency: 'ARS' : 'symbol' : '1.0-0' }}</strong>\n    </p>\n  </section>\n\n  <aside class=\"columna\">\n    <section class=\"panel\">\n      <h2>Carrito: {{ carrito() }} unidades</h2>\n      <p class=\"ayuda\">\n        Enlace bidireccional personalizado con <code>[(cantidad)]</code> (el abuelo también\n        puede usar el selector directamente):\n      </p>\n      <div class=\"carrito-demo\">\n        <selector-cantidad [(cantidad)]=\"cantidadCarrito\" />\n        <span class=\"valor-elegido\">{{ cantidadCarrito() }} elegidas</span>\n      </div>\n    </section>\n\n    <section class=\"panel\">\n      <h2>Notificaciones del bus</h2>\n      @if (notificaciones().length === 0) {\n        <p class=\"ayuda\">Sin eventos todavía. Tocá los botones de la tabla 👆</p>\n      } @else {\n        <ul class=\"notificaciones\">\n          @for (mensaje of notificaciones(); track $index) {\n            <li>{{ mensaje }}</li>\n          }\n        </ul>\n      }\n    </section>\n  </aside>\n</div>\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/productos-page.ts": "import { Component, computed, inject, signal } from '@angular/core';\nimport { takeUntilDestroyed } from '@angular/core/rxjs-interop';\nimport { CurrencyPipe } from '@angular/common';\nimport { NotificacionesBus } from './notificaciones-bus';\nimport { Producto } from './producto';\nimport { ProductoTabla } from './producto-tabla';\nimport { SelectorCantidad } from './selector-cantidad';\n\n/**\n * PÁGINA DE PRODUCTOS — el componente ABUELO 🧓\n *\n * Es el dueño de la lista de productos y del carrito. Los nietos le avisan\n * qué hacer a través del `NotificacionesBus`; acá es donde escuchamos.\n *\n * `takeUntilDestroyed()` cancela la suscripción automáticamente cuando el\n * componente se destruye: nunca te olvides de desuscribirte de un Observable.\n */\n@Component({\n  selector: 'productos-page',\n  imports: [ProductoTabla, SelectorCantidad, CurrencyPipe],\n  templateUrl: './productos-page.html',\n  styleUrl: './productos-page.css',\n})\nexport class ProductosPage {\n  private readonly bus = inject(NotificacionesBus);\n\n  /** La única fuente de verdad de la lista: un signal. */\n  protected readonly productos = signal<Producto[]>([\n    { id: 1, nombre: 'Teclado mecánico', precio: 45000 },\n    { id: 2, nombre: 'Monitor 27\"', precio: 210000 },\n    { id: 3, nombre: 'Mouse inalámbrico', precio: 12000 },\n    { id: 4, nombre: 'Auriculares con micro', precio: 38000 },\n  ]);\n\n  /** Cantidad de la demo de two-way binding [(cantidad)]. */\n  protected readonly cantidadCarrito = signal(1);\n\n  /** Unidades acumuladas que llegan por el bus de eventos. */\n  protected readonly carrito = signal(0);\n\n  /** Valor del catálogo: se recalcula solo cuando cambia `productos`. */\n  protected readonly total = computed(() =>\n    this.productos().reduce((suma, p) => suma + p.precio, 0),\n  );\n\n  /** Últimos eventos recibidos (los más nuevos primero). */\n  protected readonly notificaciones = signal<string[]>([]);\n\n  constructor() {\n    this.bus.eventos$\n      .pipe(takeUntilDestroyed())\n      .subscribe((evento) => {\n        // TODO: [Paso 5] - Manejá los dos tipos de evento con un switch:\n        //\n        //  - case 'agregado': sumá `evento.cantidad` al signal `carrito`\n        //    (con .update()) y agregá una notificación tipo:\n        //    `✅ Agregaste ${evento.cantidad} × ${evento.nombre}`.\n        //\n        //  - case 'eliminado': sacá el producto del signal `productos`\n        //    (filter por id, con .update()) y agregá una notificación tipo:\n        //    `🗑 Eliminaste \"${evento.nombre}\"`.\n        //\n        //  Tip para las notificaciones: poné el mensaje nuevo PRIMERO en el\n        //  array y quedate solo con las últimas 5:\n        //    this.notificaciones.update((lista) => [mensaje, ...lista].slice(0, 5));\n      });\n  }\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/selector-cantidad.css": "/* ─── Selector de cantidad (- / valor / +) ──────────────────────── */\n.selector {\n  display: inline-flex;\n  align-items: center;\n  border: 1px solid var(--entrada-borde);\n  border-radius: 8px;\n  overflow: hidden;\n  background: var(--entrada-fondo);\n}\n\n.selector button {\n  border: none;\n  background: var(--acento-suave);\n  color: var(--acento);\n  font-size: 1rem;\n  line-height: 1;\n  padding: 0.35rem 0.65rem;\n  cursor: pointer;\n  transition: background-color 0.15s ease;\n}\n\n.selector button:hover {\n  background: color-mix(in srgb, var(--acento) 18%, transparent);\n}\n\n.valor {\n  min-width: 2rem;\n  text-align: center;\n  font-weight: 600;\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/selector-cantidad.html": "<div class=\"selector\">\n  <button type=\"button\" (click)=\"decrementar()\" aria-label=\"Restar uno\">−</button>\n  <span class=\"valor\">{{ cantidad() }}</span>\n  <button type=\"button\" (click)=\"incrementar()\" aria-label=\"Sumar uno\">+</button>\n</div>\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/selector-cantidad.ts": "import { Component, input, output } from '@angular/core';\n\n/**\n * SELECTOR DE CANTIDAD\n *\n * Componente reutilizable con enlace bidireccional PERSONALIZADO: el padre\n * lo usa como `<selector-cantidad [(cantidad)]=\"unaSignal\" />`.\n *\n * Esta versión usa el par clásico `input()` + `output()`. Para que el\n * \"banana in a box\" `[(cantidad)]` funcione, el output DEBE llamarse\n * exactamente como el input + el sufijo `Change` (`cantidadChange`).\n */\n@Component({\n  selector: 'selector-cantidad',\n  templateUrl: './selector-cantidad.html',\n  styleUrl: './selector-cantidad.css',\n})\nexport class SelectorCantidad {\n  // TODO: [Paso 1] - Reemplazá el par input() + output() por UNA SOLA línea:\n  //   `cantidad = model(1);`\n  // (importá `model` desde '@angular/core'). Con `model()` el componente puede\n  // escribir el valor con `.set()` / `.update()` y el padre se entera solo,\n  // sin emitir manualmente un output. Después simplificá incrementar() y\n  // decrementar() usando `this.cantidad.update(...)`.\n  cantidad = input(1);\n  cantidadChange = output<number>();\n\n  incrementar(): void {\n    this.cantidadChange.emit(this.cantidad() + 1);\n  }\n\n  decrementar(): void {\n    this.cantidadChange.emit(Math.max(1, this.cantidad() - 1));\n  }\n}\n",
  "src/app/extras/01-comunicacion-y-bus-eventos/README.md": "# Práctica 01 — Comunicación entre componentes y Bus de Eventos\n\n## Cómo hacer la práctica\n\n1. Levantá el servidor: `npm start`\n2. Ejercicio: <http://localhost:4200/extras/01>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/extras/01/solucion>\n4. Archivos de trabajo: `src/app/extras/01-comunicacion-y-bus-eventos/ejercicio/` — buscá los comentarios `// TODO:` y completalos. Al guardar, el navegador se recarga solo.\n\n## Objetivo\n\nEn aplicaciones reales, la jerarquía de componentes se parece a una empresa: una **página** (abuelo) renderiza una **tabla** (hijo) que renderiza **filas** (nietos). El problema clásico: ¿cómo hace el nieto para avisarle al abuelo \"eliminá este producto\" sin tener que pasar un `output()` por cada nivel intermedio? Ese encadenamiento manual se llama **prop drilling** y convierte a los componentes intermedios en mensajeros inútiles.\n\nEn esta práctica resolvés ese problema de dos formas, ambas estándar en **Angular v20**:\n\n1. **Enlace bidireccional personalizado** con `model()`: el estándar moderno para que un componente hijo pueda escribir un valor que el padre también controla (reemplaza al par `input()` + `output('xChange')`).\n2. **Bus de eventos desacoplado** con RxJS: un servicio con un `Subject` que cualquier componente puede usar para emitir y escuchar, sin conocerse entre sí.\n\n## Conceptos clave\n\n### 1. Enlace bidireccional personalizado: `model()`\n\nAntes (y todavía válido) se hacía con el par input/output, donde el output **debe** llamarse igual que el input + `Change`:\n\n```ts\n// El par clásico\ncantidad = input(1);\ncantidadChange = output<number>();\n\nincrementar() {\n  this.cantidadChange.emit(this.cantidad() + 1);\n}\n```\n\nEn Angular v20 lo moderno es `model()`: es un input de **lectura y escritura** que ya trae el output integrado:\n\n```ts\n// Con model() — el padre usa <selector-cantidad [(cantidad)]=\"miSignal\" />\ncantidad = model(1);\n\nincrementar() {\n  this.cantidad.update((v) => v + 1); // el padre se entera solo\n}\n```\n\n### 2. Bus de eventos con `Subject` y `Observable`\n\nUn `Subject` es a la vez Observable y observador: quien llama `.next(valor)` **emite**, y todos los suscriptos con `.subscribe()` **reciben** al instante. Como el servicio se declara `providedIn: 'root'`, todos los componentes comparten la **misma instancia**: lo que emite el nieto lo escucha el abuelo, aunque estén a tres niveles de distancia.\n\n```ts\n@Injectable({ providedIn: 'root' })\nexport class NotificacionesBus {\n  private readonly eventos = new Subject<EventoBus>();       // la emisora (privada)\n  readonly eventos$ = this.eventos.asObservable();           // el dial (solo escuchar)\n\n  notificarProductoEliminado(id: number, nombre: string): void {\n    this.eventos.next({ tipo: 'eliminado', id, nombre });    // emitir\n  }\n}\n```\n\nPor convención, las propiedades observables se nombran con el sufijo `$`. Se exponen con `asObservable()` para que nadie externo pueda emitir: los métodos del servicio son la única \"radio autorizada\".\n\n### 3. Suscribirse sin memory leaks: `takeUntilDestroyed()`\n\nToda suscripción manual debe cerrarse cuando el componente muere. En Angular v20 la forma limpia es el operador de `@angular/core/rxjs-interop`:\n\n```ts\nconstructor() {\n  this.bus.eventos$\n    .pipe(takeUntilDestroyed())   // se desuscribe solo al destruirse el componente\n    .subscribe((evento) => { /* actualizar signals acá */ });\n}\n```\n\n### 4. El abuelo actualiza signals, no hace DOM\n\nEl abuelo es el dueño del estado (`signal<Producto[]>`); los nietos solo **notifican intenciones**. Eso mantiene la lógica de negocio en un solo lugar y los componentes reutilizables.\n\n## Consigna paso a paso (checklist)\n\nAbrí la página del ejercicio (<http://localhost:4200/extras/01>) y verificá primero el estado \"roto\": la tabla se ve y los botones no hacen nada, y el selector suma pero no se sincroniza con el abuelo.\n\n- [ ] **Paso 1 — `selector-cantidad.ts`:** reemplazá el par `input()` + `output()` por un único `cantidad = model(1)` y simplificá `incrementar()` / `decrementar()` usando `this.cantidad.update(...)`. *Test rápido: el selector de la sección \"Carrito\" ya debería reflejar el valor en el texto \"elegidas\".*\n- [ ] **Paso 2 — `notificaciones-bus.ts`:** implementá `notificarProductoAgregado()` emitiendo `{ tipo: 'agregado', id, nombre, cantidad }` con `this.eventos.next(...)`.\n- [ ] **Paso 3 — `notificaciones-bus.ts`:** implementá `notificarProductoEliminado()` emitiendo `{ tipo: 'eliminado', id, nombre }`.\n- [ ] **Paso 4 — `producto-fila.ts` (el nieto):** completá `agregar()` (Paso 4a) y `eliminar()` (Paso 4b) llamando a los métodos del bus inyectado. Fijate que el componente **no tiene outputs**: esa es la gracia.\n- [ ] **Paso 5 — `productos-page.ts` (el abuelo):** completá el cuerpo del `.subscribe()` dentro del constructor: con un `switch (evento.tipo)`, en `'agregado'` sumá la cantidad al signal `carrito` y en `'eliminado'` filtrá el producto del signal `productos`. En ambos casos agregá el mensaje correspondiente a las `notificaciones` (máximo 5, con el más nuevo primero).\n- [ ] **Paso 6:** probá los criterios de aceptación de abajo.\n\n## Criterios de aceptación\n\nProbá en <http://localhost:4200/extras/01>:\n\n1. **Two-way binding:** el selector de la sección \"Carrito\" suma y resta, y el número del texto (`1 elegidas`, `2 elegidas`...) cambia junto con él.\n2. **Agregar:** tocá \"➕ Agregar\" en una fila (probá con cantidad 2 en el selector de la fila): el contador \"Carrito: X unidades\" aumenta exactamente esa cantidad y aparece la notificación `✅ Agregaste 2 × Teclado mecánico`.\n3. **Eliminar:** tocá 🗑️ en una fila: el producto desaparece de la tabla, el **valor del catálogo se recalcula solo** (es un `computed()`) y aparece la notificación `🗑 Eliminaste \"...\"`.\n4. **Nieto → abuelo sin intermediarios:** abrí `producto-tabla.ts` y verificá que no tuviste que tocarlo para que el flujo funcione (no tiene outputs ni inyecta el bus).\n5. **Sin leaks:** navegá a otra ruta y volvé; todo sigue funcionando (la suscripción se limpia con `takeUntilDestroyed()`).\n6. **Comparación:** abrí `/extras/01/solucion` en otra pestaña y comprobá que tu versión se comporta igual.\n\n> 💡 **Para pensar (nivel oficina):** ¿qué pasa si dos componentes suscriptos escuchan el mismo evento? ¿Quién debería mutar la lista y quién solo mostrar un toast? Regla de oro: **un solo dueño del estado por dato**.\n\n## Solución\n\nLa versión resuelta y comentada está en `src/app/extras/01-comunicacion-y-bus-eventos/solucion/` y se navega en `/extras/01/solucion`.\n",
  "src/app/extras/02-formularios-reactivos-avanzados/ejercicio/registro-page.css": "/* ─── Página de registro: formulario reactivo avanzado ──────────── */\n.layout {\n  display: grid;\n  gap: 1rem;\n  max-width: 560px;\n  margin: 0 auto;\n  padding: 1rem;\n}\n\n.panel {\n  border: 1px solid var(--borde);\n  border-radius: 12px;\n  padding: 1rem 1.25rem;\n  background: var(--superficie);\n  box-shadow: var(--sombra-tarjeta);\n}\n\n.panel h2,\n.panel h3 {\n  margin-top: 0;\n}\n\n.ayuda {\n  color: var(--texto-suave);\n  font-size: 0.88rem;\n  line-height: 1.5;\n}\n\nlabel {\n  display: grid;\n  gap: 0.3rem;\n  margin-top: 0.9rem;\n  font-weight: 500;\n}\n\ninput {\n  padding: 0.5rem 0.7rem;\n  border: 1px solid var(--entrada-borde);\n  border-radius: 8px;\n  background: var(--entrada-fondo);\n  color: var(--texto);\n  font: inherit;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n\ninput:focus {\n  outline: none;\n  border-color: var(--acento);\n  box-shadow: 0 0 0 3px var(--resplandor);\n}\n\ninput.invalido {\n  border-color: var(--error);\n  background: var(--error-fondo);\n}\n\ninput.invalido:focus {\n  box-shadow: 0 0 0 3px color-mix(in srgb, var(--error) 22%, transparent);\n}\n\n.errores {\n  color: var(--error);\n  font-size: 0.85rem;\n  margin: 0.3rem 0 0;\n  padding-left: 1.1rem;\n}\n\n.acciones {\n  display: flex;\n  gap: 0.6rem;\n  margin-top: 1.2rem;\n}\n\nbutton.primario {\n  border: 1px solid var(--acento);\n  background: var(--acento);\n  color: var(--acento-contraste);\n  border-radius: 8px;\n  padding: 0.5rem 1rem;\n  font: inherit;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\nbutton.primario:hover:not(:disabled) {\n  background: var(--acento-fuerte);\n  border-color: var(--acento-fuerte);\n}\n\nbutton.primario:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\nbutton.primario:focus-visible,\nbutton.secundario:focus-visible {\n  outline: 2px solid var(--acento);\n  outline-offset: 2px;\n}\n\nbutton.secundario {\n  border: 1px solid var(--entrada-borde);\n  background: var(--superficie);\n  color: var(--texto);\n  border-radius: 8px;\n  padding: 0.5rem 1rem;\n  font: inherit;\n  cursor: pointer;\n  transition: border-color 0.15s ease, color 0.15s ease;\n}\n\nbutton.secundario:hover {\n  border-color: var(--acento);\n  color: var(--acento);\n}\n\n.estados {\n  color: var(--texto-suave);\n  font-size: 0.78rem;\n  margin-top: 0.9rem;\n  font-family: monospace;\n}\n\n.exito {\n  border-color: var(--exito-borde);\n  background: var(--exito-fondo);\n}\n",
  "src/app/extras/02-formularios-reactivos-avanzados/ejercicio/registro-page.html": "<div class=\"layout\">\n  <form class=\"panel\" [formGroup]=\"registroForm\" (ngSubmit)=\"handleSubmit()\" novalidate>\n    <h2>Alta de empleado</h2>\n    <p class=\"ayuda\">\n      Formulario reactivo con validadores personalizados. Los errores usan los estados\n      <code>touched</code>/<code>dirty</code>: no aparecen hasta que tocás el campo (o\n      enviás el formulario).\n    </p>\n\n    <label>\n      Nombre completo\n      <input\n        type=\"text\"\n        formControlName=\"nombre\"\n        [class.invalido]=\"mostrarErrores('nombre')\"\n      />\n    </label>\n    @if (mostrarErrores('nombre')) {\n      <ul class=\"errores\">\n        @if (registroForm.controls.nombre.hasError('required')) {\n          <li>El nombre es obligatorio.</li>\n        }\n        @if (registroForm.controls.nombre.hasError('minlength')) {\n          <li>Necesita al menos 3 caracteres.</li>\n        }\n      </ul>\n    }\n\n    <label>\n      Email corporativo\n      <input\n        type=\"email\"\n        formControlName=\"email\"\n        [class.invalido]=\"mostrarErrores('email')\"\n      />\n    </label>\n    @if (mostrarErrores('email')) {\n      <ul class=\"errores\">\n        @if (registroForm.controls.email.hasError('required')) {\n          <li>El email es obligatorio.</li>\n        }\n        @if (registroForm.controls.email.hasError('email')) {\n          <li>El formato del email no es válido.</li>\n        }\n        @if (registroForm.controls.email.hasError('dominioProhibido')) {\n          <li>\n            No se aceptan cuentas del dominio\n            “{{ registroForm.controls.email.getError('dominioProhibido').dominio }}”.\n          </li>\n        }\n      </ul>\n    }\n    <p class=\"ayuda\">Dominios bloqueados: {{ dominiosProhibidos.join(', ') }}</p>\n\n    <label>\n      Contraseña\n      <input\n        type=\"password\"\n        formControlName=\"password\"\n        [class.invalido]=\"mostrarErrores('password')\"\n      />\n    </label>\n    @if (mostrarErrores('password')) {\n      <ul class=\"errores\">\n        @if (registroForm.controls.password.hasError('required')) {\n          <li>La contraseña es obligatoria.</li>\n        }\n        @if (registroForm.controls.password.hasError('minlength')) {\n          <li>Necesita al menos 8 caracteres.</li>\n        }\n        @if (registroForm.controls.password.hasError('sinEspacios')) {\n          <li>No puede contener espacios.</li>\n        }\n      </ul>\n    }\n\n    <div class=\"acciones\">\n      <button type=\"submit\" class=\"primario\">Crear cuenta</button>\n      <button type=\"button\" class=\"secundario\" (click)=\"registroForm.reset()\">Limpiar</button>\n    </div>\n\n    <p class=\"estados\">\n      dirty: {{ registroForm.dirty }} · touched: {{ registroForm.touched }} · invalid:\n      {{ registroForm.invalid }}\n    </p>\n  </form>\n\n  @if (registroOk()) {\n    <div class=\"panel exito\">\n      <h3>✅ ¡Cuenta creada!</h3>\n      <p>Bienvenido/a, <strong>{{ nombreRegistrado() }}</strong>.</p>\n    </div>\n  }\n</div>\n",
  "src/app/extras/02-formularios-reactivos-avanzados/ejercicio/registro-page.ts": "import { Component, signal } from '@angular/core';\nimport { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';\nimport {\n  DOMINIOS_PROHIBIDOS,\n  prohibirDominiosEmail,\n  sinEspacios,\n} from './validadores/dominios-prohibidos';\n\n/** Los nombres de los controles del formulario (para tipar los helpers). */\ntype NombreControl = 'nombre' | 'email' | 'password';\n\n/**\n * PÁGINA DE REGISTRO — Formularios reactivos avanzados\n *\n * El formulario está DEFINIDO POR CÓDIGO (no por la plantilla): la clase\n * es la dueña de los controles, sus validadores y su estado. La plantilla\n * solo \"pinta\" ese estado.\n *\n * La plantilla (registro-page.html) YA ESTÁ maquetada y muestra los estados\n * (touched, dirty, invalid) en la UI. Tu trabajo está acá, en este archivo,\n * y en `validadores/dominios-prohibidos.ts`.\n */\n@Component({\n  selector: 'registro-page',\n  imports: [ReactiveFormsModule],\n  templateUrl: './registro-page.html',\n  styleUrl: './registro-page.css',\n})\nexport class RegistroPage {\n  protected readonly dominiosProhibidos = DOMINIOS_PROHIBIDOS;\n\n  /**\n   * FormGroup = el formulario entero. Cada FormControl = un campo.\n   * `nonNullable: true` hace que .value sea siempre string (nunca null),\n   * incluso después de un reset() (vuelve a '' y no a null).\n   */\n  protected readonly registroForm = new FormGroup({\n    nombre: new FormControl('', {\n      nonNullable: true,\n      // TODO: [Paso 1] - Agregá `Validators.minLength(3)` a la lista de validators.\n      validators: [Validators.required],\n    }),\n    email: new FormControl('', {\n      nonNullable: true,\n      // TODO: [Paso 2] - Agregá `Validators.email` (el validador nativo de formato).\n      // TODO: [Paso 3b] - Y también el validador propio que implementarás en\n      //        validadores/dominios-prohibidos.ts: `prohibirDominiosEmail(DOMINIOS_PROHIBIDOS)`\n      validators: [Validators.required],\n    }),\n    password: new FormControl('', {\n      nonNullable: true,\n      // TODO: [Paso 4] - Agregá `Validators.minLength(8)` y `sinEspacios`\n      //        (el validador simple que ya viene implementado, importalo arriba).\n      validators: [Validators.required],\n    }),\n  });\n\n  /** true solo cuando el formulario se envió con éxito. */\n  protected readonly registroOk = signal(false);\n\n  /** Nombre guardado al registrarse, para el mensaje de bienvenida. */\n  protected readonly nombreRegistrado = signal('');\n\n  /**\n   * Helper que usa la plantilla: decide si mostrar los errores de un control.\n   * Regla de UX: no mostrar errores de un campo que el usuario ni tocó,\n   * salvo que haya intentado enviar el formulario (touched).\n   */\n  protected mostrarErrores(nombre: NombreControl): boolean {\n    const control = this.registroForm.controls[nombre];\n    return control.invalid && (control.touched || control.dirty);\n  }\n\n  protected handleSubmit(): void {\n    // TODO: [Paso 5] - Si el formulario es inválido:\n    //   this.registroForm.markAllAsTouched();\n    //   return;\n    // markAllAsTouched() marca TODOS los controles como tocados de una, así\n    // la plantilla muestra todos los mensajes de error de golpe.\n    //\n    // TODO: [Paso 6] - Si es válido:\n    //   1. guardá el nombre: this.nombreRegistrado.set(this.registroForm.controls.nombre.value);\n    //   2. mostrá el éxito: this.registroOk.set(true);\n    //   3. limpiá el formulario: this.registroForm.reset();\n    //      (con nonNullable vuelve a '', y dirty/touched vuelven a false)\n  }\n}\n",
  "src/app/extras/02-formularios-reactivos-avanzados/ejercicio/validadores/dominios-prohibidos.ts": "import { AbstractControl, ValidationErrors, ValidatorFn } from '@angular/forms';\n\n/**\n * Dominios de email personales que la app corporativa no acepta.\n * La lista vive acá para que el validador sea 100% parametrizable: mañana\n * podés crear otra regla con otra lista sin tocar el validador.\n */\nexport const DOMINIOS_PROHIBIDOS = ['gmail.com', 'hotmail.com', 'yahoo.com', 'outlook.com'];\n\n/**\n * Validador SIMPLE (sin parámetros) de referencia: prohibe espacios en blanco.\n *\n * Este ya está implementado para que veas la \"forma\" de un ValidatorFn:\n * una función que recibe el control y devuelve...\n *   - `null`  → el valor es VÁLIDO (para este validador).\n *   - un objeto → el valor es INVÁLIDO; la key del objeto identifica el error\n *     (ej.: `{ sinEspacios: true }`) y así la plantilla puede mostrar un\n *     mensaje específico con `hasError('sinEspacios')`.\n */\nexport function sinEspacios(control: AbstractControl): ValidationErrors | null {\n  const valor = (control.value as string | null) ?? '';\n  return /\\s/.test(valor) ? { sinEspacios: true } : null;\n}\n\n/**\n * Validador personalizado PARAMETRIZABLE (fábrica de ValidatorFn).\n *\n * Es una función que devuelve OTRA función: la primera recibe la\n * configuración (la lista de dominios) y la segunda, que es la que Angular\n * ejecuta en cada cambio, recibe el control.\n *\n * Uso en un FormControl:\n *   validators: [Validators.required, prohibirDominiosEmail(DOMINIOS_PROHIBIDOS)]\n */\nexport function prohibirDominiosEmail(dominiosProhibidos: string[]): ValidatorFn {\n  return (control: AbstractControl): ValidationErrors | null => {\n    // TODO: [Paso 3a] - Implementá la lógica del validador:\n    //\n    //  1. Tomá el valor y normalizalo:\n    //       const email = ((control.value as string | null) ?? '').trim().toLowerCase();\n    //\n    //  2. Si `email` está vacío devolvé `null`: el campo vacío lo maneja\n    //     `Validators.required` (cada validador se ocupa de UNA sola cosa).\n    //\n    //  3. Extraé el dominio: la parte después del '@'\n    //       const dominio = email.split('@')[1] ?? '';\n    //\n    //  4. Buscá si el dominio está en la lista `dominiosProhibidos`\n    //     (compará en minúsculas con .some() o .includes()).\n    //\n    //  5. Si está → devolvé el error:\n    //       return { dominioProhibido: { dominio } };\n    //     (el objeto `{ dominio }` permite a la plantilla mostrar CUÁL\n    //      dominio fue bloqueado con getError('dominioProhibido').dominio)\n    //\n    //  6. Si no está → devolvé `null` (válido para este validador).\n    return null;\n  };\n}\n",
  "src/app/extras/02-formularios-reactivos-avanzados/README.md": "# Práctica 02 — Formularios Reactivos Avanzados y Validadores Personalizados\n\n## Cómo hacer la práctica\n\n1. Levantá el servidor: `npm start`\n2. Ejercicio: <http://localhost:4200/extras/02>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/extras/02/solucion>\n4. Archivos de trabajo: `src/app/extras/02-formularios-reactivos-avanzados/ejercicio/` — buscá los comentarios `// TODO:`. La plantilla y los estilos **ya están maquetados**; tu trabajo es en `registro-page.ts` y en `validadores/dominios-prohibidos.ts`.\n\n## Objetivo\n\nTodo sistema corporativo tiene formularios de alta con reglas de negocio: \"no aceptamos emails personales (@gmail, @hotmail)\", \"la contraseña no puede tener espacios\", \"si el usuario intenta enviar a medias, mostrale todos los errores de una\". La lección básica del tutorial ya usó formularios reactivos; acá vas a manejarlos como en un entorno laboral real:\n\n1. **Estado del formulario en la UI**: `dirty`, `touched`, `invalid` para mostrar errores recién cuando corresponde.\n2. **Validadores personalizados parametrizables** (`ValidatorFn` de fábrica): la forma estándar de codificar reglas de negocio reutilizables.\n\n## Conceptos clave\n\n### 1. `FormGroup` + `FormControl` definidos por código\n\nEn formularios reactivos la clase es la dueña; la plantilla solo pinta:\n\n```ts\nregistroForm = new FormGroup({\n  nombre: new FormControl('', {\n    nonNullable: true, // .value es siempre string, incluso tras reset()\n    validators: [Validators.required, Validators.minLength(3)],\n  }),\n});\n```\n\n```html\n<form [formGroup]=\"registroForm\" (ngSubmit)=\"handleSubmit()\">\n  <input formControlName=\"nombre\" />\n</form>\n```\n\n### 2. Estados: `touched`, `dirty`, `invalid`\n\n| Estado | Significado | Cuándo usarlo |\n|---|---|---|\n| `touched` | El usuario entró y salió del campo | No mostrar errores de campos que ni miró |\n| `dirty` | El usuario **escribió** algo en el campo | Diferenciar \"lo editó\" de \"solo pasó por arriba\" |\n| `invalid` | Falla al menos un validador | Pinta el borde rojo / mensajes |\n\nLa combinación clásica de UX: mostrar el error solo si `invalid && (touched || dirty)`. Y cuando el usuario intenta enviar un formulario incompleto, `markAllAsTouched()` revela todos los errores de golpe:\n\n```ts\nif (this.form.invalid) {\n  this.form.markAllAsTouched(); // dispara los mensajes en la UI\n  return;\n}\n```\n\n### 3. Validador simple vs. validador parametrizable\n\nUn `ValidatorFn` es una función que recibe el control y devuelve `null` (válido) o un objeto con la key del error (inválido):\n\n```ts\n// Simple: sin configuración\nexport function sinEspacios(control: AbstractControl): ValidationErrors | null {\n  const valor = (control.value as string | null) ?? '';\n  return /\\s/.test(valor) ? { sinEspacios: true } : null;\n}\n```\n\nEl **parametrizable** es una **fábrica**: una función que devuelve el `ValidatorFn` ya configurado. Así la misma regla sirve para cualquier lista de dominios:\n\n```ts\nexport function prohibirDominiosEmail(dominiosProhibidos: string[]): ValidatorFn {\n  return (control: AbstractControl): ValidationErrors | null => {\n    const email = ((control.value as string | null) ?? '').trim().toLowerCase();\n    if (!email) return null; // el vacío lo maneja Validators.required\n    const dominio = email.split('@')[1] ?? '';\n    return dominiosProhibidos.includes(dominio) ? { dominioProhibido: { dominio } } : null;\n  };\n}\n```\n\nEl error devuelve **data** (`{ dominio }`), no solo una bandera: la plantilla puede mostrar un mensaje concreto con `getError('dominioProhibido').dominio`.\n\n### 4. Cada validador valida UNA cosa\n\n`required` se ocupa del vacío, `email` del formato y tu validador solo de los dominios prohibidos. Se acumulan en el array de `validators` y Angular los evalúa todos: el control es inválido si falla cualquiera.\n\n## Consigna paso a paso (checklist)\n\nAbrí el ejercicio (<http://localhost:4200/extras/02>) y jugá un rato: tocá campos, escribí, borrá, enviá. Vas a ver que faltan validaciones y el envío no hace nada.\n\n- [ ] **Paso 1 — `registro-page.ts`:** al control `nombre` agregale `Validators.minLength(3)`.\n- [ ] **Paso 2 — `registro-page.ts`:** al control `email` agregale `Validators.email` (el nativo de formato).\n- [ ] **Paso 3 — `validadores/dominios-prohibidos.ts` y `registro-page.ts`:**\n  - **3a:** implementá el cuerpo del factory `prohibirDominiosEmail()` (los pasos 1 a 6 están detallados en el `// TODO`).\n  - **3b:** registrá el validador en el control `email` con `prohibirDominiosEmail(DOMINIOS_PROHIBIDOS)`.\n- [ ] **Paso 4 — `registro-page.ts`:** al control `password` agregale `Validators.minLength(8)` y el validador simple `sinEspacios` (ya está implementado, solo importalo y usalo).\n- [ ] **Paso 5 — `registro-page.ts`:** en `handleSubmit()`, si el formulario es inválido llamá `markAllAsTouched()` y hacé `return`.\n- [ ] **Paso 6 — `registro-page.ts`:** si es válido: guardá el nombre en `nombreRegistrado`, activá `registroOk` con `.set(true)` y limpiá con `this.registroForm.reset()`.\n- [ ] **Paso 7:** probá los criterios de aceptación de abajo.\n\n## Criterios de aceptación\n\nProbá en <http://localhost:4200/extras/02>:\n\n1. **Estados en vivo:** apenas carga, la fila `dirty / touched / invalid` muestra `false / false / true` y **no hay mensajes de error** (aunque los campos estén vacíos).\n2. **Errores al tocar:** escribí una letra en \"Nombre\" y salí del campo → aparece \"Necesita al menos 3 caracteres\". Mientras el campo está enfocado y vacío, no hay mensajes.\n3. **Dominios bloqueados:** escribí `juan@gmail.com` → aparece el borde rojo y el mensaje *\"No se aceptan cuentas del dominio 'gmail.com'\"*. Con `juan@empresa.com.ar` el error desaparece (y `Validators.email` no se queja).\n4. **Formato de email:** `juan.sin-arroba` → aparece \"El formato del email no es válido\".\n5. **Contraseña:** probá `pass word` (con espacio) → \"No puede contener espacios\"; con `abc123` → \"Necesita al menos 8 caracteres\".\n6. **Envío incompleto:** con errores presentes, tocá \"Crear cuenta\" → todos los mensajes aparecen de golpe (`markAllAsTouched`).\n7. **Envío válido:** completá todo bien → aparece el panel \"✅ ¡Cuenta creada!\" con el nombre, y el formulario se limpia (estados `false / false / true` de nuevo).\n8. **Comparación:** en `/extras/02/solucion` el comportamiento es idéntico.\n\n> 💡 **Para pensar (nivel oficina):** ¿por qué `prohibirDominiosEmail` es una fábrica y no una función con la lista hardcodeada adentro? Pista: imaginá que mañana el mismo validador sirve para una lista blanca de dominios socios.\n\n## Solución\n\nLa versión resuelta y comentada está en `src/app/extras/02-formularios-reactivos-avanzados/solucion/` y se navega en `/extras/02/solucion`.\n",
  "src/app/extras/03-http-client-y-manejo-errores/ejercicio/empleado.ts": "export type Area = 'IT' | 'RRHH' | 'Ventas';\n\n/** Un empleado del equipo, tal como lo devuelve `GET /api/empleados`. */\nexport interface Empleado {\n  id: number;\n  nombre: string;\n  area: Area;\n  seniority: string;\n}\n",
  "src/app/extras/03-http-client-y-manejo-errores/ejercicio/empleados-page.css": "/* ─── Página de empleados: HttpClient + manejo de errores ──────── */\n.contenedor {\n  max-width: 720px;\n  margin: 0 auto;\n  padding: 2rem 1rem;\n}\n\nh1 {\n  margin: 0 0 0.5rem;\n}\n\n.bajada {\n  color: var(--texto-suave);\n  line-height: 1.5;\n}\n\n.acciones {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 0.5rem;\n  margin: 1.25rem 0;\n}\n\nbutton {\n  padding: 0.45rem 0.9rem;\n  border: 1px solid var(--acento);\n  border-radius: 8px;\n  background: var(--superficie);\n  color: var(--acento);\n  font: inherit;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease, color 0.15s ease;\n}\n\nbutton:hover:not(.peligro) {\n  background: var(--acento-suave);\n}\n\nbutton.peligro {\n  border-color: color-mix(in srgb, var(--error) 55%, transparent);\n  color: var(--error);\n}\n\nbutton.peligro:hover {\n  background: var(--error-fondo);\n  border-color: var(--error);\n}\n\nbutton:focus-visible {\n  outline: 2px solid var(--acento);\n  outline-offset: 2px;\n}\n\n.cargando {\n  font-weight: 600;\n  color: var(--texto-suave);\n}\n\n.alerta {\n  border: 1px solid var(--error-borde);\n  background: var(--error-fondo);\n  color: var(--error);\n  border-radius: 10px;\n  padding: 0.75rem 1rem;\n  margin-bottom: 1rem;\n}\n\ntable {\n  width: 100%;\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  text-align: left;\n  padding: 0.55rem 0.75rem;\n  border-bottom: 1px solid var(--borde);\n}\n\nth {\n  color: var(--texto-suave);\n  font-size: 0.85rem;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n}\n\ntbody tr {\n  transition: background-color 0.15s ease;\n}\n\ntbody tr:hover {\n  background: var(--acento-suave);\n}\n\n.badge {\n  background: var(--acento-suave);\n  color: var(--acento);\n  border-radius: 999px;\n  padding: 0.1rem 0.6rem;\n  font-size: 0.8rem;\n  font-weight: 600;\n}\n\n.vacio {\n  text-align: center;\n  color: var(--texto-suave);\n  font-style: italic;\n}\n",
  "src/app/extras/03-http-client-y-manejo-errores/ejercicio/empleados-page.html": "<main class=\"contenedor\">\n  <h1>Equipo de trabajo</h1>\n  <p class=\"bajada\">\n    Práctica 03 — HttpClient con <code>HttpHeaders</code>, <code>HttpParams</code> y manejo de\n    errores con <code>catchError</code>. Los botones de abajo disparan peticiones al backend\n    falso (fijate en la pestaña Network que NADIE sale a internet).\n  </p>\n\n  <div class=\"acciones\">\n    <button (click)=\"cargar()\">Cargar equipo</button>\n    <button (click)=\"cargar('IT')\">Solo IT</button>\n    <button (click)=\"cargar('RRHH')\">Solo RRHH</button>\n    <button class=\"peligro\" (click)=\"verEmpleadoInexistente()\">Legajo 999 (404)</button>\n    <button class=\"peligro\" (click)=\"generarReporte()\">Reporte (500)</button>\n  </div>\n\n  @if (cargando()) {\n    <p class=\"cargando\">⏳ Cargando...</p>\n  }\n\n  @if (mensajeError()) {\n    <div class=\"alerta\" role=\"alert\">\n      <strong>Ups:</strong> {{ mensajeError() }}\n    </div>\n  }\n\n  <table>\n    <thead>\n      <tr>\n        <th>Legajo</th>\n        <th>Nombre</th>\n        <th>Área</th>\n        <th>Seniority</th>\n      </tr>\n    </thead>\n    <tbody>\n      @for (empleado of empleados(); track empleado.id) {\n        <tr>\n          <td>{{ empleado.id }}</td>\n          <td>{{ empleado.nombre }}</td>\n          <td><span class=\"badge\">{{ empleado.area }}</span></td>\n          <td>{{ empleado.seniority }}</td>\n        </tr>\n      } @empty {\n        <tr>\n          <td colspan=\"4\" class=\"vacio\">Todavía no hay empleados para mostrar.</td>\n        </tr>\n      }\n    </tbody>\n  </table>\n</main>\n",
  "src/app/extras/03-http-client-y-manejo-errores/ejercicio/empleados-page.ts": "import { Component, inject, signal } from '@angular/core';\nimport { Area, Empleado } from './empleado';\nimport { EmpleadosService } from './empleados.service';\n\n/**\n * PÁGINA DEL EQUIPO — consumir un servicio HTTP y mostrar estados\n *\n * La página tiene tres señales de estado:\n * - `empleados`: la lista que llega del backend (empieza vacía).\n * - `cargando`: true mientras vuela la petición (muestra \"⏳ Cargando...\").\n * - `mensajeError`: el mensaje amigable si algo falla (muestra la alerta).\n *\n * Tu trabajo (Pasos 7 a 9) es implementar los tres métodos que disparan\n * peticiones y setean estas señales según el resultado.\n */\n@Component({\n  selector: 'empleados-page',\n  imports: [],\n  templateUrl: './empleados-page.html',\n  styleUrl: './empleados-page.css',\n})\nexport class EmpleadosPage {\n  private readonly servicio = inject(EmpleadosService);\n\n  protected readonly empleados = signal<Empleado[]>([]);\n  protected readonly cargando = signal(false);\n  protected readonly mensajeError = signal('');\n\n  /**\n   * Carga la lista, opcionalmente filtrada por área.\n   * Es el método que usan los botones \"Cargar equipo\", \"Solo IT\" y \"Solo RRHH\".\n   */\n  protected cargar(area?: Area): void {\n    // TODO: [Paso 7] - Receta para TODA petición HTTP en un componente:\n    //   1. this.cargando.set(true);\n    //   2. limpiá el error previo: this.mensajeError.set('');\n    //   3. this.servicio.getEmpleados(area).subscribe({ next, error }):\n    //      - next: seteá `empleados` con lo recibido y cargando.set(false).\n    //      - error: seteá `mensajeError` con err.message y cargando.set(false).\n    //   El error llega como un Error normal (gracias a manejarError del\n    //   servicio): err.message ya es el texto amigable.\n  }\n\n  /** Pide el legajo 999: el backend responde 404. */\n  protected verEmpleadoInexistente(): void {\n    // TODO: [Paso 8] - Igual que cargar(), pero con this.servicio.getEmpleado(999).\n    //   Si por alguna razón llega un empleado, mostralo solo en la tabla\n    //   (this.empleados.set([empleado])).\n  }\n\n  /** Pide el reporte al endpoint caído: el backend responde 500 siempre. */\n  protected generarReporte(): void {\n    // TODO: [Paso 9] - Igual que cargar(), pero con this.servicio.getReporte().\n  }\n}\n",
  "src/app/extras/03-http-client-y-manejo-errores/ejercicio/empleados.service.ts": "import { HttpClient, HttpErrorResponse, HttpHeaders, HttpParams } from '@angular/common/http';\nimport { Injectable, inject } from '@angular/core';\nimport { EMPTY, Observable, catchError, throwError } from 'rxjs';\nimport { Area, Empleado } from './empleado';\n\n/**\n * SERVICIO DE EMPLEADOS — HttpClient, HttpParams, HttpHeaders y catchError\n *\n * Este servicio habla con el \"backend falso\" (un HttpInterceptorFn registrado\n * en app.config.ts, 100% offline). Ojo: ese backend es exigente:\n * - Responde **400** si falta la cabecera `X-Canal: practica-03`.\n * - Responde **404** si pedís un empleado que no existe (probá el legajo 999).\n * - El endpoint `/api/reporte` responde **500** SIEMPRE (está \"caído\").\n *\n * Tu trabajo es que cada llamada arme sus opciones y que TODOS los errores\n * pasen por `manejarError()` para convertirlos en mensajes amigables.\n */\n@Injectable({ providedIn: 'root' })\nexport class EmpleadosService {\n  private readonly http = inject(HttpClient);\n  private readonly urlBase = '/api/empleados';\n\n  /**\n   * Lista de empleados, opcionalmente filtrada por área (?area=IT|RRHH|Ventas).\n   */\n  getEmpleados(area?: Area): Observable<Empleado[]> {\n    // TODO: [Paso 2] - Armá el filtro con HttpParams: si `area` viene definida,\n    //   agregala al params con `params = params.set('area', area)`.\n    //   Recordá que HttpParams es INMUTABLE: cada set() devuelve una instancia\n    //   nueva, por eso se reasigna sobre la misma variable.\n    let params = new HttpParams();\n\n    // TODO: [Paso 3] - Creá los HttpHeaders con la cabecera obligatoria:\n    //   new HttpHeaders({ 'X-Canal': 'practica-03' })\n    //   Sin esa cabecera el backend falso responde 400.\n    const headers = new HttpHeaders();\n\n    // TODO: [Paso 5] - Pasá las opciones al get(): el tercer argumento es un\n    //   objeto `{ params, headers }`. Con catchError envolvé el error para que\n    //   pase por manejarError() (ya está cableado abajo, no lo toques).\n    return this.http\n      .get<Empleado[]>(this.urlBase)\n      .pipe(catchError((error) => this.manejarError(error)));\n  }\n\n  /** Busca UN empleado por legajo. Con id 999 el backend responde 404. */\n  getEmpleado(id: number): Observable<Empleado> {\n    // TODO: [Paso 6] - Mismo patrón que getEmpleados():\n    //   - GET a `${this.urlBase}/${id}` (template literal).\n    //   - Con la cabecera 'X-Canal: practica-03'.\n    //   - Con catchError → manejarError().\n    console.warn('getEmpleado() sin implementar (Paso 6)');\n    return EMPTY;\n  }\n\n  /** Pide un reporte al endpoint \"caído\" (siempre responde 500). */\n  getReporte(): Observable<{ total: number }> {\n    // TODO: [Paso 6] - Igual que arriba, pero GET a '/api/reporte'\n    //   (tipalo como Observable<{ total: number }>).\n    console.warn('getReporte() sin implementar (Paso 6)');\n    return EMPTY;\n  }\n\n  /**\n   * Traduce un HttpErrorResponse a un mensaje amigable y lo relanza como\n   * Error normal, así el componente solo recibe `err.message`.\n   */\n  private manejarError(error: HttpErrorResponse): Observable<never> {\n    // TODO: [Paso 4] - Implementá el switch sobre `error.status`:\n    //   - 0     → 'No hay conexión con el servidor. Verificá tu red.'\n    //   - 400   → 'La petición es inválida: falta la cabecera X-Canal.'\n    //   - 404   → 'El recurso que buscás no existe.'\n    //   - 500   → 'El servidor está caído. Probá de nuevo más tarde.'\n    //   - default → `Error inesperado (${error.status})`\n    //   Y devolvé `throwError(() => new Error(mensaje))`.\n    //   (El stub actual devuelve EMPTY: el observable \"termina en silencio\"\n    //   y el componente nunca se entera del error. Por eso hay que cambiarlo.)\n    console.error('Error HTTP:', error.status, error.message);\n    return EMPTY;\n  }\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/admin-page.ts": "import { HttpClient, HttpErrorResponse } from '@angular/common/http';\nimport { Component, inject, signal } from '@angular/core';\n\n/** Lo que responde `GET /api/panel` cuando todo sale bien. */\ninterface PanelResponse {\n  rolRecibido: string;\n  secretos: string[];\n}\n\n/**\n * PÁGINA DE ADMIN — consumir un endpoint protegido (Bearer + rol admin).\n *\n * Este endpoint falla de dos formas distintas (y eso es lo didáctico):\n * - **401**: nadie sabe quién sos → falta el token (Paso 7 del interceptor).\n * - **403**: sabés quién sos pero no sos admin → probá con ana/ana123.\n *\n * 401 = no autenticado. 403 = autenticado pero sin permisos. No son lo mismo.\n */\n@Component({\n  selector: 'admin-page',\n  template: `\n    <section>\n      <h2>Panel admin</h2>\n      <p class=\"bajada\">\n        <code>GET /api/panel</code> exige cabecera <code>Authorization: Bearer &lt;jwt&gt;</code>\n        y rol admin.\n      </p>\n\n      <button (click)=\"consultar()\">Volver a consultar</button>\n\n      @if (cargando()) {\n        <p>⏳ Cargando...</p>\n      }\n\n      @if (mensajeError()) {\n        <div class=\"alerta\" role=\"alert\"><strong>Ups:</strong> {{ mensajeError() }}</div>\n      }\n\n      @if (datos(); as datos) {\n        <p>\n          rolRecibido: <strong>{{ datos.rolRecibido }}</strong>\n        </p>\n        <h3>Secretos corporativos</h3>\n        <ul>\n          @for (secreto of datos.secretos; track secreto) {\n            <li>{{ secreto }}</li>\n          }\n        </ul>\n      }\n    </section>\n  `,\n  styles: `\n    .bajada {\n      color: var(--texto-suave);\n    }\n    button {\n      padding: 0.45rem 0.9rem;\n      border: 1px solid var(--acento);\n      background: var(--superficie);\n      color: var(--acento);\n      border-radius: 8px;\n      font: inherit;\n      font-weight: 600;\n      cursor: pointer;\n      margin-bottom: 1rem;\n      transition: background-color 0.15s ease, border-color 0.15s ease;\n    }\n    button:hover {\n      background: var(--acento-suave);\n    }\n    .alerta {\n      border: 1px solid var(--error-borde);\n      background: var(--error-fondo);\n      color: var(--error);\n      border-radius: 10px;\n      padding: 0.75rem 1rem;\n    }\n  `,\n})\nexport class AdminPage {\n  private readonly http = inject(HttpClient);\n\n  protected readonly datos = signal<PanelResponse | null>(null);\n  protected readonly mensajeError = signal('');\n  protected readonly cargando = signal(false);\n\n  constructor() {\n    this.consultar();\n  }\n\n  protected consultar(): void {\n    // TODO: [Paso 9] - Consultar el endpoint protegido:\n    //   1. this.cargando.set(true); this.mensajeError.set(''); this.datos.set(null);\n    //   2. this.http.get<PanelResponse>('/api/panel').subscribe({ next, error }):\n    //      - next: this.datos.set(datos) y cargando.set(false).\n    //      - error (HttpErrorResponse): mensaje amigable según err.status:\n    //        401 → 'No estás autenticado: falta el Bearer token (¿Paso 7?).'\n    //        403 → 'No tenés permisos: tu rol no es admin.'\n    //        otro → `Error inesperado (${err.status})`\n    //   Mientras el interceptor (Paso 7) no mande el token, acá se ve el 401.\n    console.warn('consultar() sin implementar (Paso 9)');\n  }\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/auth.guard.ts": "import { inject } from '@angular/core';\nimport { CanActivateFn, Router } from '@angular/router';\nimport { AuthService, Rol } from './auth.service';\n\n/**\n * GUARD de autenticación: ¿hay sesión abierta?\n *\n * Un CanActivateFn devuelve:\n * - `true` → la ruta se muestra;\n * - `false` → se bloquea;\n * - un `UrlTree` → Angular redirige a esa URL (la forma pro de redirigir).\n *\n * Se usa en las rutas hijas de la práctica (ver ../rutas.ts): canActivate: [authGuard].\n */\nexport const authGuard: CanActivateFn = (route, state) => {\n  // TODO: [Paso 5] - Si hay sesión, dejá pasar: return true;\n  //   Si no, redirigí al login conservando adónde iba el usuario:\n  //   const auth = inject(AuthService);\n  //   const router = inject(Router);\n  //   if (auth.usuarioActual()) {\n  //     return true;\n  //   }\n  //   return router.createUrlTree(['/extras/04/login'], {\n  //     queryParams: { returnUrl: state.url },\n  //   });\n  //   `state.url` es la ruta que se quiso visitar: el login la usa (Paso 8)\n  //   para volver ahí después de loguear. Este patrón se llama \"returnUrl\".\n  return true; // stub: rutas abiertas hasta implementar el guard\n};\n\n/**\n * Fábrica de GUARD de autorización: ¿la sesión tiene el rol correcto?\n *\n * Es una FUNCIÓN que devuelve un CanActivateFn: así el mismo guard sirve\n * para 'admin', 'user' o el rol que haga falta (patrón igual al validador\n * parametrizable de la práctica 02).\n *\n * Se usa en cascada: canActivate: [authGuard, roleGuard('admin')] — primero\n * se pregunta si hay sesión, después si el rol alcanza.\n */\nexport function roleGuard(rolRequerido: Rol): CanActivateFn {\n  return (route, state) => {\n    // TODO: [Paso 6] - Tres caminos:\n    //   1. sin sesión → redirigir al login (igual que authGuard, con returnUrl).\n    //   2. con sesión pero rol distinto de `rolRequerido` → redirigir al perfil:\n    //      return router.createUrlTree(['/extras/04/perfil']);\n    //   3. rol correcto → return true.\n    return true; // stub: rutas abiertas hasta implementar el guard\n  };\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/auth.interceptor.ts": "import { HttpInterceptorFn } from '@angular/common/http';\nimport { TOKEN_KEY } from './auth.service';\n\n/**\n * INTERCEPTOR DE TOKEN — agrega `Authorization: Bearer <jwt>` a cada petición.\n *\n * Se registra PRIMERO en app.config.ts, así \"envuelve\" al resto de los\n * interceptores (incluido el backend falso): cuando el backend falso lee la\n * cabecera Authorization, este interceptor ya la agregó.\n *\n * Estado inicial: el stub hace `return next(req)` sin tocar nada, por eso\n * `/api/panel` responde 401 al principio. Con el Paso 7 implementado, toda\n * petición sale con su Bearer token (si hay sesión guardada).\n */\nexport const authTokenInterceptor: HttpInterceptorFn = (req, next) => {\n  // TODO: [Paso 7] - Inyectar el token en la petición:\n  //   1. const token = localStorage.getItem(TOKEN_KEY);\n  //   2. si hay token: cloná la petición con la cabecera y seguí con el clon:\n  //      const reqConToken = req.clone({\n  //        setHeaders: { Authorization: `Bearer ${token}` },\n  //      });\n  //      return next(reqConToken);\n  //   3. si no hay token: return next(req); (las públicas como /api/login pasan igual)\n  //\n  //   ¿Por qué req.clone()? HttpRequest es inmutable (igual que HttpParams):\n  //   clone() devuelve una copia nueva con los cambios, sin mutar la original.\n  return next(req);\n};\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/auth.service.ts": "import { HttpClient } from '@angular/common/http';\nimport { Injectable, inject, signal } from '@angular/core';\nimport { EMPTY, Observable, map } from 'rxjs';\n\nexport type Rol = 'admin' | 'user';\n\nexport interface Credenciales {\n  usuario: string;\n  clave: string;\n}\n\nexport interface Usuario {\n  usuario: string;\n  nombre: string;\n  rol: Rol;\n}\n\n/** El payload del JWT simulado: un usuario + fecha de expiración. */\nexport interface PayloadJwt extends Usuario {\n  exp: number;\n}\n\n/** Clave bajo la que vive el token en localStorage. */\nexport const TOKEN_KEY = 'pp_token';\n\n/**\n * SERVICIO DE AUTH — login con JWT simulado y sesión en localStorage.\n *\n * El backend falso responde a `POST /api/login` con `{ token }`, un JWT\n * simulado (header.payload.firma, codificado en base64). Este servicio:\n * 1. guarda el token en localStorage (para que el interceptor lo use),\n * 2. decodifica el payload (atob + JSON.parse) para saber QUIÉN entró,\n * 3. expone al usuario en la señal `usuarioActual` (para guards y plantillas).\n */\n@Injectable({ providedIn: 'root' })\nexport class AuthService {\n  private readonly http = inject(HttpClient);\n\n  /** Usuario con sesión abierta (null = nadie logueado). */\n  readonly usuarioActual = signal<Usuario | null>(null);\n\n  constructor() {\n    // TODO: [Paso 1] - Restaurar sesión guardada (para sobrevivir a F5):\n    //   1. const token = localStorage.getItem(TOKEN_KEY);\n    //   2. const payload = token ? this.decodificarToken(token) : null;\n    //   3. si hay payload, seteá la señal: this.usuarioActual.set(payload);\n    //      (un PayloadJwt \"es\" un Usuario porque PayloadJwt extends Usuario).\n  }\n\n  /** POST /api/login → guarda la sesión y devuelve el Usuario logueado. */\n  login(credenciales: Credenciales): Observable<Usuario> {\n    // TODO: [Paso 3] - Llamada al backend y transformación con map():\n    //   return this.http.post<{ token: string }>('/api/login', credenciales).pipe(\n    //     map((respuesta) => this.guardarSesion(respuesta.token)),\n    //   );\n    // Credenciales inválidas → el backend responde 401 → el observable emite\n    // error y el componente lo muestra (ver Paso 8 en login-page.ts).\n    console.warn('login() sin implementar (Paso 3)');\n    return EMPTY;\n  }\n\n  /**\n   * Decodifica el segmento medio de un JWT simulado (base64 + JSON).\n   * Devuelve null si el token es basura: mejor no confiar que explotar.\n   */\n  decodificarToken(token: string): PayloadJwt | null {\n    // TODO: [Paso 2] - Envolver en try/catch y devolver null en el catch:\n    //   const payload = JSON.parse(atob(token.split('.')[1])) as PayloadJwt;\n    //   - token.split('.')[1] → el segmento \"payload\" del JWT (header.payload.firma).\n    //   - atob(...) → decodifica base64 a texto.\n    //   - JSON.parse(...) → texto a objeto.\n    console.warn('decodificarToken() sin implementar (Paso 2)');\n    return null;\n  }\n\n  /** Cierra la sesión: sin token en storage y sin usuario en memoria. */\n  cerrarSesion(): void {\n    // TODO: [Paso 4] - localStorage.removeItem(TOKEN_KEY);\n    //                   this.usuarioActual.set(null);\n  }\n\n  /** Guarda el token, decodifica el payload y setea la señal. Devuelve el usuario. */\n  private guardarSesion(token: string): Usuario {\n    // TODO: [Paso 3, parte 2] - En orden:\n    //   1. localStorage.setItem(TOKEN_KEY, token);\n    //   2. const payload = this.decodificarToken(token);\n    //   3. si hay payload: this.usuarioActual.set(payload) y return payload;\n    //   4. si el token es basura: throw new Error('Token inválido');\n    console.warn('guardarSesion() sin implementar (Paso 3)');\n    return { usuario: '', nombre: '', rol: 'user' }; // placeholder hasta el Paso 3\n  }\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/login-page.ts": "import { Component, inject, signal } from '@angular/core';\nimport { ActivatedRoute, Router } from '@angular/router';\nimport { Credenciales, AuthService } from './auth.service';\n\n/**\n * PÁGINA DE LOGIN — disparar el login y navegar según el resultado.\n *\n * Credenciales válidas del backend falso:\n * - admin / admin123 → rol 'admin' (puede ver el Panel admin)\n * - ana / ana123     → rol 'user' (el Panel admin le da 403)\n *\n * El guard (Paso 5) deja en la URL `?returnUrl=/extras/04/admin` cuando\n * te corta el paso: el login usa ese dato para volver EXACTAMENTE adonde\n * ibas después de loguearte (patrón returnUrl, como en apps reales).\n */\n@Component({\n  selector: 'login-page',\n  template: `\n    <section>\n      <h2>Login</h2>\n      <p class=\"bajada\">\n        Probá <code>admin / admin123</code> o <code>ana / ana123</code>. Con otra cosa: 401.\n      </p>\n\n      <div class=\"campos\">\n        <input #usuarioInput placeholder=\"usuario\" autocomplete=\"username\" />\n        <input #claveInput type=\"password\" placeholder=\"clave\" autocomplete=\"current-password\" />\n        <button (click)=\"ingresar(usuarioInput.value, claveInput.value)\">Ingresar</button>\n      </div>\n\n      @if (mensajeError()) {\n        <div class=\"alerta\" role=\"alert\"><strong>Ups:</strong> {{ mensajeError() }}</div>\n      }\n    </section>\n  `,\n  styles: `\n    .campos {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 0.5rem;\n      margin: 1rem 0;\n    }\n    input {\n      padding: 0.45rem 0.7rem;\n      border: 1px solid var(--entrada-borde);\n      border-radius: 8px;\n      background: var(--entrada-fondo);\n      color: var(--texto);\n      font: inherit;\n    }\n    button {\n      padding: 0.45rem 0.9rem;\n      border: 1px solid var(--acento);\n      background: var(--acento);\n      color: var(--acento-contraste);\n      border-radius: 8px;\n      font: inherit;\n      font-weight: 600;\n      cursor: pointer;\n      transition: background-color 0.15s ease, border-color 0.15s ease;\n    }\n    button:hover {\n      background: var(--acento-fuerte);\n      border-color: var(--acento-fuerte);\n    }\n    button:focus-visible {\n      outline: 2px solid var(--acento);\n      outline-offset: 2px;\n    }\n    .alerta {\n      border: 1px solid var(--error-borde);\n      background: var(--error-fondo);\n      color: var(--error);\n      border-radius: 10px;\n      padding: 0.75rem 1rem;\n    }\n  `,\n})\nexport class LoginPage {\n  private readonly auth = inject(AuthService);\n  private readonly route = inject(ActivatedRoute);\n  private readonly router = inject(Router);\n\n  protected readonly mensajeError = signal('');\n\n  /** A dónde volver tras loguear (el authGuard lo dejó en la query string). */\n  protected readonly returnUrl =\n    this.route.snapshot.queryParamMap.get('returnUrl') ?? '/extras/04/perfil';\n\n  protected ingresar(usuario: string, clave: string): void {\n    const credenciales: Credenciales = { usuario: usuario.trim(), clave };\n\n    // TODO: [Paso 8] - this.auth.login(credenciales).subscribe({ next, error }):\n    //   - next: navegar al returnUrl → this.router.navigateByUrl(this.returnUrl);\n    //   - error: mostrar el mensaje → this.mensajeError.set(e.message);\n    //     (el 401 del backend llega como HttpErrorResponse: su .message ya es\n    //     legible; si querés afinarlo, traducí por e.status acá mismo).\n    console.warn('ingresar() sin implementar (Paso 8)');\n  }\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/panel-layout.ts": "import { Component, inject } from '@angular/core';\nimport { Router, RouterLink, RouterOutlet } from '@angular/router';\nimport { AuthService } from './auth.service';\n\n/**\n * LAYOUT DEL PANEL — nav + estado de sesión + <router-outlet />\n *\n * Este componente NO tiene TODOs: ya está completo. Es la \"caja\" que envuelve\n * a las páginas hijas (login, perfil, admin) definidas en ../rutas.ts:\n * lo que esté acá se ve SIEMPRE, y cada página hija se pinta en el outlet.\n *\n * Fijate cómo la señal `usuarioActual` del servicio alimenta la UI: cuando\n * el login setea la señal, este layout re-renderiza solo.\n */\n@Component({\n  selector: 'panel-layout',\n  imports: [RouterLink, RouterOutlet],\n  template: `\n    <main class=\"contenedor\">\n      <h1>Panel de gestión</h1>\n\n      <nav>\n        <a routerLink=\"perfil\">Perfil</a>\n        <a routerLink=\"admin\">Panel admin</a>\n      </nav>\n\n      @if (auth.usuarioActual(); as usuario) {\n        <p class=\"sesion\">\n          👤 {{ usuario.nombre }} — rol: <strong>{{ usuario.rol }}</strong>\n          <button (click)=\"cerrarSesion()\">Cerrar sesión</button>\n        </p>\n      } @else {\n        <p class=\"sesion\">Sin sesión abierta. Las rutas protegidas te van a llevar al login.</p>\n      }\n\n      <router-outlet />\n    </main>\n  `,\n  styles: `\n    .contenedor {\n      max-width: 640px;\n      margin: 0 auto;\n      padding: 2rem 1rem;\n    }\n    nav {\n      display: flex;\n      gap: 1rem;\n      margin: 1rem 0;\n    }\n    a {\n      color: var(--acento);\n      text-decoration: none;\n      font-weight: 600;\n    }\n    a:hover {\n      text-decoration: underline;\n    }\n    .sesion {\n      display: flex;\n      align-items: center;\n      gap: 0.75rem;\n      background: var(--acento-suave);\n      border: 1px solid color-mix(in srgb, var(--acento) 18%, transparent);\n      border-radius: 10px;\n      padding: 0.6rem 1rem;\n    }\n    button {\n      border: 1px solid color-mix(in srgb, var(--error) 55%, transparent);\n      color: var(--error);\n      background: var(--superficie);\n      border-radius: 8px;\n      padding: 0.3rem 0.7rem;\n      font: inherit;\n      cursor: pointer;\n      transition: background-color 0.15s ease, border-color 0.15s ease;\n    }\n    button:hover {\n      background: var(--error-fondo);\n      border-color: var(--error);\n    }\n  `,\n})\nexport class PanelLayout {\n  protected readonly auth = inject(AuthService);\n  private readonly router = inject(Router);\n\n  protected cerrarSesion(): void {\n    this.auth.cerrarSesion();\n    this.router.navigate(['/extras/04/login']);\n  }\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/perfil-page.ts": "import { Component, inject } from '@angular/core';\nimport { AuthService } from './auth.service';\n\n/**\n * PÁGINA DE PERFIL — muestra la sesión activa (protegida por authGuard).\n * Sin TODOs: es la página \"feliz\" adonde el login te manda.\n */\n@Component({\n  selector: 'perfil-page',\n  template: `\n    <section>\n      <h2>Mi perfil</h2>\n      @if (auth.usuarioActual(); as usuario) {\n        <dl>\n          <dt>Usuario</dt>\n          <dd>{{ usuario.usuario }}</dd>\n          <dt>Nombre</dt>\n          <dd>{{ usuario.nombre }}</dd>\n          <dt>Rol</dt>\n          <dd><strong>{{ usuario.rol }}</strong></dd>\n        </dl>\n        <p class=\"nota\">\n          Estos datos NO vinieron de una petición: salieron del payload del JWT,\n          decodificados con <code>atob</code> por el AuthService.\n        </p>\n      } @else {\n        <p class=\"alerta\">No hay sesión abierta (¿cómo llegaste acá sin que el guard te corte?).</p>\n      }\n    </section>\n  `,\n  styles: `\n    dl {\n      display: grid;\n      grid-template-columns: auto 1fr;\n      gap: 0.35rem 1.25rem;\n    }\n    dt {\n      color: var(--texto-suave);\n      font-weight: 600;\n    }\n    dd {\n      margin: 0;\n    }\n    .nota {\n      color: var(--texto-suave);\n      font-size: 0.85rem;\n    }\n    .alerta {\n      border: 1px solid var(--error-borde);\n      background: var(--error-fondo);\n      color: var(--error);\n      border-radius: 10px;\n      padding: 0.75rem 1rem;\n    }\n  `,\n})\nexport class PerfilPage {\n  protected readonly auth = inject(AuthService);\n}\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/README.md": "# Práctica 04 — Auth JWT: Guards e Interceptores\n\n## Cómo hacer la práctica\n\n1. Levantá el servidor: `npm start`\n2. Ejercicio: <http://localhost:4200/extras/04>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/extras/04/solucion>\n4. Archivos de trabajo: `src/app/extras/04-auth-jwt-guards-interceptors/ejercicio/` — buscá los comentarios `// TODO:`. Las páginas usan template inline (son chicas); tu trabajo es en `auth.service.ts`, `auth.guard.ts`, `auth.interceptor.ts`, `login-page.ts` y `admin-page.ts`.\n5. El backend sigue siendo 100% offline (`src/app/extras/backend-falso.ts`): `POST /api/login` devuelve un JWT simulado y `GET /api/panel` exige Bearer + rol admin.\n\n## Objetivo\n\nEn cualquier empresa real, hay pantallas que solo ven usuarios logueados y otras que solo ve un admin. Acá vas a implementar ese circuito completo con las herramientas de Angular:\n\n1. **Autenticación con JWT**: login que guarda el token, lo decodifica y restaura la sesión al recargar.\n2. **Guards** (`CanActivateFn`): decidir ANTES de pintar una ruta si el usuario puede verla.\n3. **Interceptores** (`HttpInterceptorFn`): agregar `Authorization: Bearer <token>` a TODAS las peticiones sin tocar cada servicio.\n\n## Conceptos clave\n\n### 1. El JWT simulado y su decodificación\n\nUn JWT son tres segmentos base64 separados por puntos: `header.payload.firma`. El payload es el interesante (quién sos y qué rol tenés):\n\n```ts\ndecodificarToken(token: string): PayloadJwt | null {\n  try {\n    return JSON.parse(atob(token.split('.')[1])) as PayloadJwt;\n  } catch {\n    return null;\n  }\n}\n```\n\nFijate: NO se \"confía\" en el token — el `try/catch` devuelve `null` ante cualquier basura. (En producción, la firma se valida en el servidor; acá la simulamos.)\n\n### 2. Guards: `CanActivateFn` y `createUrlTree`\n\nUn guard devuelve `true` (pasar), `false` (bloquear) o un `UrlTree` (redirigir — la forma pro):\n\n```ts\nexport const authGuard: CanActivateFn = (route, state) => {\n  if (auth.usuarioActual()) return true;\n  return router.createUrlTree(['/extras/04/login'], {\n    queryParams: { returnUrl: state.url },\n  });\n};\n```\n\n`state.url` es la ruta que el usuario quería visitar: el login la usa para volver ahí después de loguear (patrón **returnUrl**). Y el guard de rol es una **fábrica**, como el validador parametrizable de la práctica 02:\n\n```ts\nexport function roleGuard(rolRequerido: Rol): CanActivateFn {\n  return (route, state) => { /* pregunta por rolRequerido */ };\n}\n```\n\nEn cascada: `canActivate: [authGuard, roleGuard('admin')]` — primero sesión, después rol.\n\n### 3. Interceptores: un solo lugar para la cabecera\n\nEn vez de agregar la cabecera a mano en cada servicio, un interceptor lo hace por TODOS:\n\n```ts\nexport const authTokenInterceptor: HttpInterceptorFn = (req, next) => {\n  const token = localStorage.getItem(TOKEN_KEY);\n  if (token) {\n    return next(req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }));\n  }\n  return next(req);\n};\n```\n\n`req.clone()` porque `HttpRequest` es inmutable (igual que `HttpParams` en la 03). Y en `app.config.ts` el orden importa: el interceptor de token va **primero**, así envuelve al resto (incluido el backend falso) y el token ya está cuando el backend lo mira.\n\n> ⚠️ **Importante para la solución:** el interceptor registrado globalmente en `app.config.ts` es el del **ejercicio**. Una vez que implementes ese (Paso 7), tanto `/extras/04` como `/extras/04/solucion` funcionan; el interceptor de `solucion/` sirve solo de referencia y no está registrado.\n\n### 4. 401 vs 403 (no son lo mismo)\n\n- **401 Unauthorized**: no sé quién sos → falta (o es inválido) el token.\n- **403 Forbidden**: sé quién sos y no alcanza → tu rol no es admin.\n\nEl panel admin de la práctica te muestra los dos: 401 antes del Paso 7, 403 con `ana/ana123`.\n\n## Consigna paso a paso (checklist)\n\nAbrí el ejercicio (<http://localhost:4200/extras/04>) y recorré las rutas: con los guards stub (`return true`) TODO está \"abierto\", incluso sin sesión. Esa es la brecha de seguridad que vas a cerrar.\n\n- [ ] **Paso 1 — `auth.service.ts`:** restaurá la sesión en el constructor: leer `localStorage.getItem(TOKEN_KEY)`, decodificar y setear `usuarioActual` si es válido.\n- [ ] **Paso 2 — `auth.service.ts`:** implementá `decodificarToken()` (try/catch, `atob` del segmento medio).\n- [ ] **Paso 3 — `auth.service.ts`:** implementá `login()` (POST + `map`) y `guardarSesion()` (guardar token, decodificar, setear la señal, devolver el usuario).\n- [ ] **Paso 4 — `auth.service.ts`:** implementá `cerrarSesion()`.\n- [ ] **Paso 5 — `auth.guard.ts`:** implementá `authGuard`: sesión → `true`; si no, `createUrlTree` al login con `returnUrl`.\n- [ ] **Paso 6 — `auth.guard.ts`:** implementá `roleGuard(rolRequerido)`: sin sesión → login; con sesión y rol distinto → perfil; rol correcto → `true`.\n- [ ] **Paso 7 — `auth.interceptor.ts`:** implementá el Bearer: leer token, `req.clone({ setHeaders: { Authorization: \\`Bearer ${token}\\` } })` y `next(reqConToken)`.\n- [ ] **Paso 8 — `login-page.ts`:** en `ingresar()`, llamá `auth.login(...)` y en `next` navegá al `returnUrl` (o a `/extras/04/perfil`); en `error` mostrá `e.message`.\n- [ ] **Paso 9 — `admin-page.ts`:** consultá `GET /api/panel` con `inject(HttpClient)` y seteá `datos` o un `mensajeError` amigable (401/403).\n- [ ] **Paso 10:** probá los criterios de aceptación de abajo.\n\n## Criterios de aceptación\n\nProbá en <http://localhost:4200/extras/04>:\n\n1. **Estado inicial:** las 3 rutas abren (guards stub), pero \"Panel admin\" muestra el 401 amigable (el interceptor todavía no manda el token).\n2. Login con `admin/admin123` → redirige al perfil conservando `returnUrl` si venía de una ruta protegida.\n3. Al loguearse, el layout muestra la sesión (nombre + rol) — el payload del JWT fue decodificado con `atob`.\n4. Tras implementar el interceptor: \"Panel admin\" muestra los datos y `rolRecibido: 'admin'`.\n5. `roleGuard`: con `ana/ana123` (rol user), la ruta `/extras/04/admin` redirige (no muestra el panel).\n6. Recargar la página con sesión abierta sigue logueado (restauración desde localStorage).\n7. \"Cerrar sesión\" vuelve al estado sin sesión y las rutas protegidas redirigen al login.\n8. En `/extras/04/solucion` el flujo completo funciona solo (aclarar en el README que el interceptor registrado globalmente en `app.config.ts` es el del ejercicio: una vez implementado ese, ambas vistas funcionan; el de `solucion/` sirve de referencia).\n\n## Solución\n\nLa versión resuelta y comentada está en `src/app/extras/04-auth-jwt-guards-interceptors/solucion/` y se navega en `/extras/04/solucion`.\n",
  "src/app/extras/04-auth-jwt-guards-interceptors/rutas.ts": "import { Routes } from '@angular/router';\nimport { authGuard, roleGuard } from './ejercicio/auth.guard';\nimport { authGuardSolucion, roleGuardSolucion } from './solucion/auth.guard';\n\n/**\n * RUTAS DE LA PRÁCTICA 04 — rutas hijas con guards.\n *\n * Esta práctica define SUS rutas en su propio archivo (en vez de tocar\n * directamente app.routes.ts) porque son rutas HIJAS con guards: el layout\n * (PanelLayout) se carga con loadComponent y las páginas hijas se pintan\n * en su <router-outlet />.\n *\n * app.routes.ts registra todo con un spread: ...rutasPractica04\n *\n * Los guards se importan de forma ESTÁTICA (no loadComponent/loadChildren):\n * son funciones livianas que van en el bundle principal, y así el lazy\n * loading queda solo para los componentes pesados.\n */\nexport const rutasPractica04: Routes = [\n  {\n    path: 'extras/04',\n    loadComponent: () => import('./ejercicio/panel-layout').then((m) => m.PanelLayout),\n    children: [\n      // Al entrar sin página específica: al perfil (el guard decide si ves o te manda al login).\n      { path: '', pathMatch: 'full', redirectTo: 'perfil' },\n      {\n        path: 'login',\n        loadComponent: () => import('./ejercicio/login-page').then((m) => m.LoginPage),\n        title: 'Práctica 04 — Login',\n      },\n      {\n        path: 'perfil',\n        loadComponent: () => import('./ejercicio/perfil-page').then((m) => m.PerfilPage),\n        canActivate: [authGuard],\n        title: 'Práctica 04 — Perfil',\n      },\n      {\n        path: 'admin',\n        loadComponent: () => import('./ejercicio/admin-page').then((m) => m.AdminPage),\n        // En cascada: primero ¿hay sesión?, después ¿el rol alcanza?\n        canActivate: [authGuard, roleGuard('admin')],\n        title: 'Práctica 04 — Panel admin',\n      },\n    ],\n  },\n\n  // Mismo árbol con las variantes Solucion y sus guards resueltos.\n  {\n    path: 'extras/04/solucion',\n    loadComponent: () => import('./solucion/panel-layout').then((m) => m.PanelLayoutSolucion),\n    children: [\n      { path: '', pathMatch: 'full', redirectTo: 'perfil' },\n      {\n        path: 'login',\n        loadComponent: () => import('./solucion/login-page').then((m) => m.LoginPageSolucion),\n        title: 'Solución 04 — Login',\n      },\n      {\n        path: 'perfil',\n        loadComponent: () => import('./solucion/perfil-page').then((m) => m.PerfilPageSolucion),\n        canActivate: [authGuardSolucion],\n        title: 'Solución 04 — Perfil',\n      },\n      {\n        path: 'admin',\n        loadComponent: () => import('./solucion/admin-page').then((m) => m.AdminPageSolucion),\n        canActivate: [authGuardSolucion, roleGuardSolucion('admin')],\n        title: 'Solución 04 — Panel admin',\n      },\n    ],\n  },\n];\n",
  "src/app/extras/05-crud-interactivo-con-modales/ejercicio/empleados-page.css": "/* ─── Página CRUD de empleados ──────────────────────────────────── */\n.contenedor {\n  max-width: 860px;\n  margin: 0 auto;\n  padding: 2rem 1rem;\n}\n\nh1 {\n  margin: 0 0 0.5rem;\n}\n\n.bajada {\n  color: var(--texto-suave);\n  line-height: 1.5;\n}\n\n.toolbar {\n  display: flex;\n  gap: 0.75rem;\n  align-items: center;\n  justify-content: space-between;\n  margin: 1.25rem 0;\n}\n\n.filtro {\n  flex: 1;\n  max-width: 340px;\n  padding: 0.45rem 0.7rem;\n  border: 1px solid var(--entrada-borde);\n  border-radius: 8px;\n  background: var(--entrada-fondo);\n  color: var(--texto);\n  font: inherit;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.filtro:focus {\n  outline: none;\n  border-color: var(--acento);\n  box-shadow: 0 0 0 3px var(--resplandor);\n}\n\nbutton {\n  padding: 0.4rem 0.8rem;\n  border: 1px solid var(--acento);\n  background: var(--superficie);\n  color: var(--acento);\n  border-radius: 8px;\n  font: inherit;\n  font-weight: 600;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\nbutton:hover:not(:disabled) {\n  background: var(--acento-suave);\n}\n\nbutton:disabled {\n  opacity: 0.45;\n  cursor: not-allowed;\n}\n\nbutton.primario {\n  background: var(--acento);\n  color: var(--acento-contraste);\n}\n\nbutton.primario:hover:not(:disabled) {\n  background: var(--acento-fuerte);\n  border-color: var(--acento-fuerte);\n}\n\nbutton.peligro {\n  border-color: color-mix(in srgb, var(--error) 55%, transparent);\n  color: var(--error);\n}\n\nbutton.peligro:hover:not(:disabled) {\n  background: var(--error-fondo);\n  border-color: var(--error);\n}\n\nbutton:focus-visible {\n  outline: 2px solid var(--acento);\n  outline-offset: 2px;\n}\n\ntable {\n  width: 100%;\n  border-collapse: collapse;\n}\n\nth,\ntd {\n  text-align: left;\n  padding: 0.55rem 0.75rem;\n  border-bottom: 1px solid var(--borde);\n}\n\nth {\n  color: var(--texto-suave);\n  font-size: 0.85rem;\n  text-transform: uppercase;\n  letter-spacing: 0.03em;\n}\n\ntbody tr {\n  transition: background-color 0.15s ease;\n}\n\ntbody tr:hover {\n  background: var(--acento-suave);\n}\n\n.badge {\n  background: var(--acento-suave);\n  color: var(--acento);\n  border-radius: 999px;\n  padding: 0.1rem 0.6rem;\n  font-size: 0.8rem;\n  font-weight: 600;\n}\n\n.acciones {\n  white-space: nowrap;\n}\n\n.acciones button {\n  margin-left: 0.4rem;\n}\n\n.confirmacion {\n  color: var(--error);\n  font-size: 0.9rem;\n}\n\n.vacio {\n  text-align: center;\n  color: var(--texto-suave);\n  font-style: italic;\n}\n\n.paginador {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 1rem;\n  margin-top: 1rem;\n  color: var(--texto-suave);\n}\n",
  "src/app/extras/05-crud-interactivo-con-modales/ejercicio/empleados-page.html": "<main class=\"contenedor\">\n  <h1>Empleados</h1>\n  <p class=\"bajada\">\n    Práctica 05 — CRUD interactivo: filtro en vivo, paginación, modal de alta/edición\n    y confirmación de borrado inline (sin <code>confirm()</code>).\n  </p>\n\n  <div class=\"toolbar\">\n    <input\n      class=\"filtro\"\n      type=\"search\"\n      placeholder=\"Filtrar por nombre, email o área...\"\n      [value]=\"filtro()\"\n      (input)=\"alTipearFiltro($event)\"\n    />\n    <button class=\"primario\" (click)=\"abrirNuevo()\">+ Nuevo empleado</button>\n  </div>\n\n  <table>\n    <thead>\n      <tr>\n        <th>#</th>\n        <th>Nombre</th>\n        <th>Email</th>\n        <th>Área</th>\n        <th>Seniority</th>\n        <th>Acciones</th>\n      </tr>\n    </thead>\n    <tbody>\n      @for (empleado of paginados(); track empleado.id) {\n        <tr>\n          <td>{{ empleado.id }}</td>\n          <td>{{ empleado.nombre }}</td>\n          <td>{{ empleado.email }}</td>\n          <td><span class=\"badge\">{{ empleado.area }}</span></td>\n          <td>{{ empleado.seniority }}</td>\n          <td class=\"acciones\">\n            @if (eliminandoId() === empleado.id) {\n              <span class=\"confirmacion\">\n                ¿Borrar a {{ empleado.nombre }}?\n                <button class=\"peligro\" (click)=\"confirmarEliminacion()\">Sí</button>\n                <button (click)=\"cancelarEliminacion()\">No</button>\n              </span>\n            } @else {\n              <button (click)=\"abrirEdicion(empleado)\">Editar</button>\n              <button class=\"peligro\" (click)=\"pedirConfirmacion(empleado.id)\">Borrar</button>\n            }\n          </td>\n        </tr>\n      } @empty {\n        <tr>\n          <td colspan=\"6\" class=\"vacio\">Ningún empleado coincide con el filtro.</td>\n        </tr>\n      }\n    </tbody>\n  </table>\n\n  <div class=\"paginador\">\n    <button [disabled]=\"pagina() <= 1\" (click)=\"cambiarPagina(-1)\">‹</button>\n    <span>Página {{ pagina() }} de {{ totalPaginas() }}</span>\n    <button [disabled]=\"pagina() >= totalPaginas()\" (click)=\"cambiarPagina(1)\">›</button>\n  </div>\n\n  @if (modalAbierto()) {\n    <modal-editor\n      [empleado]=\"seleccionado()\"\n      (cerrar)=\"cerrarModal()\"\n      (guardar)=\"guardarCambios($event)\"\n    />\n  }\n</main>\n",
  "src/app/extras/05-crud-interactivo-con-modales/ejercicio/empleados-page.ts": "import { Component, computed, inject, signal } from '@angular/core';\nimport { Empleado } from '../empleado';\nimport { EmpleadosCrudService } from '../empleados-crud.service';\nimport { ModalEditor } from './modal-editor';\n\n/**\n * PÁGINA CRUD — tabla con filtro, paginación, modal y confirmación inline.\n *\n * El \"backend\" es el servicio compartido (`../empleados-crud.service.ts`,\n * un singleton con signals). Tu trabajo es la lógica de UI en la página\n * (Pasos 1 a 4 y 7) y el formulario del modal (`./modal-editor.ts`,\n * Pasos 5 y 6).\n */\n@Component({\n  selector: 'empleados-page',\n  imports: [ModalEditor],\n  templateUrl: './empleados-page.html',\n  styleUrl: './empleados-page.css',\n})\nexport class EmpleadosPage {\n  private readonly servicio = inject(EmpleadosCrudService);\n\n  /** Texto del filtro (nombre, email o área). */\n  protected readonly filtro = signal('');\n  protected readonly pagina = signal(1);\n  protected readonly porPagina = 4;\n\n  /** Empleado en edición (null = alta de uno nuevo). */\n  protected readonly seleccionado = signal<Empleado | null>(null);\n  protected readonly modalAbierto = signal(false);\n\n  /** Id de la fila con la confirmación de borrado abierta (null = ninguna). */\n  protected readonly eliminandoId = signal<number | null>(null);\n\n  // TODO: [Paso 1] - Convertí este computed en un filtro REAL: sobre la lista\n  //   del servicio, quedate con los empleados cuyo nombre, email O área\n  //   incluyan el texto de `filtro()` (usá `includes` y, si querés ser pro,\n  //   compará en minúsculas para que \"ANA\" encuentre a \"Ana Pérez\").\n  //   Ojo: `filtro()` vacío → devolver todo.\n  protected readonly filtrados = computed(() => this.servicio.empleados());\n\n  // TODO: [Paso 2] - Paginación real: usá `.slice(...)` sobre `filtrados()`\n  //   con `this.porPagina` y la página actual.\n  protected readonly paginados = computed(() => this.filtrados());\n\n  // TODO: [Paso 2] - Total de páginas: Math.ceil(cantidad filtrada / porPagina).\n  //   Mínimo 1, para que \"Página 1 de 1\" no rompa con la lista vacía.\n  protected readonly totalPaginas = computed(() => 1);\n\n  /**\n   * Mueve la página en `delta` (+1 o -1), CLAMPEADA entre 1 y totalPaginas:\n   * no importa cuántas veces toquen \"‹\" o \"›\", la página nunca se va de rango.\n   */\n  protected cambiarPagina(delta: number): void {\n    // TODO: [Paso 2] - this.pagina.update((p) => Math.min(Math.max(p + delta, 1), this.totalPaginas()));\n  }\n\n  /** Handler del input de filtro (viene un Event genérico del (input)). */\n  protected alTipearFiltro(event: Event): void {\n    // TODO: [Paso 2] - Dos cosas:\n    //   1. this.filtro.set((event.target as HTMLInputElement).value);\n    //   2. volver a la página 1: si estás filtrando desde la página 3 y el\n    //      resultado tiene 1 página, quedarías \"colgado\" en una página vacía.\n    //      this.pagina.set(1);\n  }\n\n  // TODO: [Paso 3] - Abrir el modal para un empleado NUEVO:\n  //   seleccionado.set(null), modalAbierto.set(true).\n  protected abrirNuevo(): void {}\n\n  // TODO: [Paso 3] - Abrir el modal para EDITAR: seleccionado.set(empleado),\n  //   modalAbierto.set(true). El modal (Paso 5) precarga el form con esos datos.\n  protected abrirEdicion(empleado: Empleado): void {}\n\n  protected cerrarModal(): void {\n    this.modalAbierto.set(false);\n    this.seleccionado.set(null);\n  }\n\n  /** Guardar el modal: alta o edición según haya empleado seleccionado. */\n  protected guardarCambios(datos: Omit<Empleado, 'id'>): void {\n    // TODO: [Paso 7] - Si this.seleccionado() existe → EDICIÓN:\n    //   this.servicio.actualizar({ ...datos, id: this.seleccionado()!.id });\n    //   Si no → ALTA: this.servicio.crear(datos);\n    //   Y en ambos casos cerrá el modal (hay un método justo arriba para eso).\n  }\n\n  /** Ya está hecho: abre la confirmación inline en la fila. */\n  protected pedirConfirmacion(id: number): void {\n    this.eliminandoId.set(id);\n  }\n\n  /** Ya está hecho: cierra la confirmación sin borrar. */\n  protected cancelarEliminacion(): void {\n    this.eliminandoId.set(null);\n  }\n\n  protected confirmarEliminacion(): void {\n    // TODO: [Paso 4] - Borrar de verdad y resetear el estado:\n    //   1. this.servicio.eliminar(this.eliminandoId()!);\n    //   2. this.eliminandoId.set(null);\n  }\n}\n",
  "src/app/extras/05-crud-interactivo-con-modales/ejercicio/modal-editor.css": "/* ─── Modal editor de empleado ──────────────────────────────────── */\n.overlay {\n  position: fixed;\n  inset: 0;\n  background: rgb(0 0 0 / 0.55);\n  display: grid;\n  place-items: center;\n  z-index: 10;\n}\n\n.tarjeta {\n  background: var(--superficie);\n  color: var(--texto);\n  border: 1px solid var(--borde);\n  border-radius: 14px;\n  padding: 1.5rem;\n  width: min(480px, calc(100vw - 2rem));\n  box-shadow: var(--sombra-tarjeta);\n}\n\nh2 {\n  margin: 0 0 1rem;\n}\n\nform {\n  display: grid;\n  gap: 0.9rem;\n}\n\nlabel {\n  display: grid;\n  gap: 0.25rem;\n  font-size: 0.9rem;\n  color: var(--texto-suave);\n}\n\ninput,\nselect {\n  padding: 0.45rem 0.7rem;\n  border: 1px solid var(--entrada-borde);\n  border-radius: 8px;\n  background: var(--entrada-fondo);\n  color: var(--texto);\n  font: inherit;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n\ninput:focus,\nselect:focus {\n  outline: none;\n  border-color: var(--acento);\n  box-shadow: 0 0 0 3px var(--resplandor);\n}\n\ninput.ng-invalid.ng-touched,\ninput.ng-invalid.ng-dirty {\n  border-color: var(--error);\n}\n\n.fila {\n  display: grid;\n  grid-template-columns: 140px 1fr;\n  gap: 0.75rem;\n}\n\n.error {\n  color: var(--error);\n  font-size: 0.8rem;\n}\n\n.acciones {\n  display: flex;\n  justify-content: flex-end;\n  gap: 0.5rem;\n  margin-top: 0.5rem;\n}\n\nbutton {\n  padding: 0.45rem 0.9rem;\n  border: 1px solid var(--entrada-borde);\n  background: var(--superficie);\n  color: var(--texto);\n  border-radius: 8px;\n  font: inherit;\n  cursor: pointer;\n  transition: background-color 0.15s ease, border-color 0.15s ease;\n}\n\nbutton:hover {\n  border-color: var(--acento);\n  color: var(--acento);\n}\n\nbutton.primario {\n  background: var(--acento);\n  border-color: var(--acento);\n  color: var(--acento-contraste);\n}\n\nbutton.primario:hover {\n  background: var(--acento-fuerte);\n  border-color: var(--acento-fuerte);\n  color: var(--acento-contraste);\n}\n\nbutton:focus-visible {\n  outline: 2px solid var(--acento);\n  outline-offset: 2px;\n}\n",
  "src/app/extras/05-crud-interactivo-con-modales/ejercicio/modal-editor.html": "<div class=\"overlay\" (click)=\"cerrar.emit()\">\n  <div class=\"tarjeta\" (click)=\"$event.stopPropagation()\">\n    <h2>{{ empleado() ? 'Editar empleado' : 'Nuevo empleado' }}</h2>\n\n    <form [formGroup]=\"form\" (ngSubmit)=\"confirmar()\">\n      <label>\n        Nombre\n        <input formControlName=\"nombre\" placeholder=\"Ana Pérez\" />\n        @if (mostrarErrores('nombre')) {\n          <span class=\"error\">\n            @if (form.controls.nombre.hasError('required')) {\n              El nombre es obligatorio.\n            } @else if (form.controls.nombre.hasError('minlength')) {\n              Necesita al menos 3 caracteres.\n            }\n          </span>\n        }\n      </label>\n\n      <label>\n        Email\n        <input formControlName=\"email\" placeholder=\"ana@empresa.com.ar\" />\n        @if (mostrarErrores('email')) {\n          <span class=\"error\">\n            @if (form.controls.email.hasError('required')) {\n              El email es obligatorio.\n            } @else if (form.controls.email.hasError('email')) {\n              El formato del email no es válido.\n            }\n          </span>\n        }\n      </label>\n\n      <div class=\"fila\">\n        <label>\n          Área\n          <select formControlName=\"area\">\n            <option value=\"IT\">IT</option>\n            <option value=\"RRHH\">RRHH</option>\n            <option value=\"Ventas\">Ventas</option>\n          </select>\n        </label>\n\n        <label>\n          Seniority\n          <input formControlName=\"seniority\" placeholder=\"Senior / Semi Senior / Junior\" />\n          @if (mostrarErrores('seniority')) {\n            <span class=\"error\">El seniority es obligatorio.</span>\n          }\n        </label>\n      </div>\n\n      <div class=\"acciones\">\n        <button type=\"button\" (click)=\"cerrar.emit()\">Cancelar</button>\n        <button type=\"submit\" class=\"primario\">Guardar</button>\n      </div>\n    </form>\n  </div>\n</div>\n",
  "src/app/extras/05-crud-interactivo-con-modales/ejercicio/modal-editor.ts": "import { Component, effect, input, output } from '@angular/core';\nimport { FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';\nimport { Area, Empleado } from '../empleado';\n\ntype NombreControl = 'nombre' | 'email' | 'area' | 'seniority';\n\n/**\n * MODAL EDITOR — formulario de alta/edición con precarga (patchValue).\n *\n * Es un componente \"de diálogo\": recibe al empleado por `input()` (null =\n * alta), emite eventos por `output()` y la página decide qué hacer con ellos.\n * La página lo monta con:\n *   <modal-editor [empleado]=\"seleccionado()\" (cerrar)=\"...\" (guardar)=\"...\" />\n *\n * Tu trabajo: el Pasos 5 (precarga con effect) y 6 (confirmar()) de acá abajo.\n */\n@Component({\n  selector: 'modal-editor',\n  imports: [ReactiveFormsModule],\n  templateUrl: './modal-editor.html',\n  styleUrl: './modal-editor.css',\n})\nexport class ModalEditor {\n  /** Empleado a editar; `null` = alta de uno nuevo (form vacío). */\n  empleado = input<Empleado | null>(null);\n\n  /** Pedirle a la página que cierre el modal (Cancelar, overlay, Esc...). */\n  cerrar = output<void>();\n\n  /** Entregarle a la página los datos ya validados del formulario. */\n  guardar = output<Omit<Empleado, 'id'>>();\n\n  /**\n   * FormGroup del modal. Los validadores son los mismos patrones de la\n   * práctica 02: `required` + reglas por campo.\n   * Ojo con `area`: es un <select>, y su FormControl es NO nullable con\n   * valor inicial 'IT' (el select siempre tiene un valor válido).\n   */\n  protected readonly form = new FormGroup({\n    nombre: new FormControl('', {\n      nonNullable: true,\n      validators: [Validators.required, Validators.minLength(3)],\n    }),\n    email: new FormControl('', {\n      nonNullable: true,\n      validators: [Validators.required, Validators.email],\n    }),\n    area: new FormControl<Area>('IT', { nonNullable: true }),\n    seniority: new FormControl('', {\n      nonNullable: true,\n      validators: [Validators.required],\n    }),\n  });\n\n  constructor() {\n    // TODO: [Paso 5] - Precargar el formulario cuando cambia `empleado`.\n    //   Un effect() dentro del constructor (contexto de inyección) corre\n    //   cada vez que la señal leída adentro cambia:\n    //\n    //     effect(() => {\n    //       const empleado = this.empleado();\n    //       if (empleado) {\n    //         this.form.patchValue(empleado); // EDITAR: precarga los 4 campos\n    //       } else {\n    //         this.form.reset(); // ALTA: form vacío (con nonNullable vuelve a '')\n    //       }\n    //     });\n    //\n    //   ¿Por qué patchValue y no setValue? patchValue acepta un objeto PARCIAL\n    //   (Empleado trae `id`, que no es parte del form, y patchValue lo ignora).\n  }\n\n  /** Helper de la plantilla: cuándo mostrar el error de un control. */\n  protected mostrarErrores(nombre: NombreControl): boolean {\n    const control = this.form.controls[nombre];\n    return control.invalid && (control.touched || control.dirty);\n  }\n\n  /** Botón \"Guardar\" del modal (ngSubmit del form). */\n  protected confirmar(): void {\n    // TODO: [Paso 6] - Validar antes de emitir:\n    //   1. si el form es inválido: this.form.markAllAsTouched() y return\n    //      (así la plantilla muestra todos los mensajes de golpe).\n    //   2. si es válido: this.guardar.emit(this.form.getRawValue());\n    //      getRawValue() devuelve { nombre, email, area, seniority } tipado,\n    //      exactamente el Omit<Empleado, 'id'> que espera la página.\n  }\n}\n",
  "src/app/extras/05-crud-interactivo-con-modales/empleado.ts": "export type Area = 'IT' | 'RRHH' | 'Ventas';\n\n/** Un empleado de la \"empresa\": el modelo de la práctica 05. */\nexport interface Empleado {\n  id: number;\n  nombre: string;\n  email: string;\n  area: Area;\n  seniority: string;\n}\n\n/** Un empleado sin id: lo que llega del formulario al dar de alta. */\nexport type EmpleadoNuevo = Omit<Empleado, 'id'>;\n",
  "src/app/extras/05-crud-interactivo-con-modales/empleados-crud.service.ts": "import { Injectable, signal } from '@angular/core';\nimport { Area, Empleado, EmpleadoNuevo } from './empleado';\n\n/** Semilla de empleados para que la tabla no arranque vacía. */\nconst SEMILLA: Empleado[] = [\n  { id: 1, nombre: 'Ana Pérez', email: 'ana@empresa.com.ar', area: 'IT', seniority: 'Senior' },\n  { id: 2, nombre: 'Bruno Díaz', email: 'bruno@empresa.com.ar', area: 'IT', seniority: 'Junior' },\n  { id: 3, nombre: 'Carla Gómez', email: 'carla@empresa.com.ar', area: 'RRHH', seniority: 'Semi Senior' },\n  { id: 4, nombre: 'Diego Ruiz', email: 'diego@empresa.com.ar', area: 'Ventas', seniority: 'Senior' },\n  { id: 5, nombre: 'Elena Sosa', email: 'elena@empresa.com.ar', area: 'RRHH', seniority: 'Junior' },\n  { id: 6, nombre: 'Fabio Luna', email: 'fabio@empresa.com.ar', area: 'IT', seniority: 'Semi Senior' },\n];\n\n/**\n * SERVICIO CRUD — el \"backend en memoria\" de la práctica 05.\n *\n * Este archivo ya está COMPLETO (no tiene TODOs): es el material sobre el\n * que trabaja la página. Dos cosas para notar:\n *\n * 1. `providedIn: 'root'` → es un SINGLETON: ejercicio y solución comparten\n *    los mismos datos (si creás un empleado en una, aparece en la otra).\n * 2. Es un mini-modelo de stores con signals: una señal privada `fuente`\n *    con los datos, y `asReadonly()` expone una versión de solo lectura.\n *    Los métodos mutan SIEMPRE con update() (copia del array inmutable),\n *    nunca con push(): así las referencias cambian y toda la UI reacciona.\n */\n@Injectable({ providedIn: 'root' })\nexport class EmpleadosCrudService {\n  /** Fuente de verdad: señal privada con la lista completa. */\n  private readonly fuente = signal<Empleado[]>(SEMILLA);\n\n  /** Lista de solo lectura para el resto de la app. */\n  readonly empleados = this.fuente.asReadonly();\n\n  /** Alta: calcula el id (max + 1) y agrega al final. */\n  crear(datos: EmpleadoNuevo): void {\n    const id = Math.max(0, ...this.fuente().map((e) => e.id)) + 1;\n    this.fuente.update((lista) => [...lista, { ...datos, id }]);\n  }\n\n  /** Edición: reemplaza el empleado con el mismo id. */\n  actualizar(actualizado: Empleado): void {\n    this.fuente.update((lista) =>\n      lista.map((e) => (e.id === actualizado.id ? actualizado : e)),\n    );\n  }\n\n  /** Baja: saca al empleado con ese id. */\n  eliminar(id: number): void {\n    this.fuente.update((lista) => lista.filter((e) => e.id !== id));\n  }\n}\n",
  "src/app/extras/05-crud-interactivo-con-modales/README.md": "# Práctica 05 — CRUD Interactivo con Modales\n\n## Cómo hacer la práctica\n\n1. Levantá el servidor: `npm start`\n2. Ejercicio: <http://localhost:4200/extras/05>\n3. Solución para comparar en otra pestaña: <http://localhost:4200/extras/05/solucion>\n4. Archivos de trabajo: `src/app/extras/05-crud-interactivo-con-modales/ejercicio/` — buscá los comentarios `// TODO:`. La plantilla y los estilos **ya están maquetados**; tu trabajo es en `empleados-page.ts` (Pasos 1–4 y 7) y en `modal-editor.ts` (Pasos 5 y 6).\n5. El \"backend\" ya está hecho: `empleados-crud.service.ts` (en la raíz de la carpeta, compartido entre ejercicio y solución) es el backend en memoria con signals. NO tiene TODOs: es el material sobre el que trabajás.\n\n## Objetivo\n\nEl CRUD es el pan de cada día de cualquier sistema de gestión: listar, filtrar, dar de alta, editar y borrar — todo sin recargar la página. La parte difícil no es el `HttpClient` (eso fue la práctica 03) sino la **experiencia interactiva**: paginar resultados, confirmar un borrado sin `confirm()` del navegador, y un modal que precarga el formulario al editar. Acá vas a combinar todo lo de las prácticas anteriores:\n\n1. **Estado derivado con `computed()`**: filtrar y paginar como funciones de las señales.\n2. **Un modal reutilizable**: componente con `input()`/`output()` que precarga el form con `patchValue()`.\n3. **Borrado con confirmación inline**: el mensaje vive en la propia fila de la tabla.\n\n## Conceptos clave\n\n### 1. Estado derivado: `filtrados` y `paginados`\n\nEl orden del pipeline es: lista completa → filtro → página. Cada eslabón es un `computed()` que lee al anterior, así Angular recalcula en cadena solo lo necesario:\n\n```ts\nfiltrados = computed(() => lista.filter(...));           // depende de filtro + servicio\npaginados = computed(() => filtrados().slice(...));       // depende de filtrados + pagina\ntotalPaginas = computed(() => Math.max(1, Math.ceil(...)));\n```\n\nDos trampas clásicas (que la solución comenta): `Math.ceil` para la página parcial, y **volver a la página 1 al tipear en el filtro** — si estás en la página 3 y el resultado pasa a tener 1 página, quedarías mirando una página que ya no existe.\n\n### 2. Modal con `input()` + `output()`\n\nEl modal es un componente más, sin lógica de negocio: recibe al empleado por `input()` (`null` = alta), emite `guardar` con los datos validados y la página decide qué hacer:\n\n```ts\nempleado = input<Empleado | null>(null);\nguardar = output<Omit<Empleado, 'id'>>();\n```\n\nLa precarga se hace en un **`effect()`** (dentro del constructor, contexto de inyección): corre cada vez que cambia el input — editar precarga, alta resetea:\n\n```ts\neffect(() => {\n  const empleado = this.empleado();\n  if (empleado) this.form.patchValue(empleado);\n  else this.form.reset();\n});\n```\n\n¿`patchValue` y no `setValue`? `patchValue` acepta un objeto **parcial**: `Empleado` trae `id`, que no es control del form, y `patchValue` lo ignora (`setValue` explotaría).\n\n### 3. `getRawValue()` y el flujo de guardado\n\n```ts\n// En el modal (Paso 6): validar antes de emitir\nif (this.form.invalid) {\n  this.form.markAllAsTouched();\n  return;\n}\nthis.guardar.emit(this.form.getRawValue());\n\n// En la página (Paso 7): ¿edición o alta? Lo decide seleccionado()\nconst seleccionado = this.seleccionado();\nif (seleccionado) {\n  this.servicio.actualizar({ ...datos, id: seleccionado.id });\n} else {\n  this.servicio.crear(datos);\n}\n```\n\n### 4. El servicio como \"backend en memoria\"\n\n```ts\n@Injectable({ providedIn: 'root' })\nexport class EmpleadosCrudService {\n  private readonly fuente = signal<Empleado[]>(SEMILLA);\n  readonly empleados = this.fuente.asReadonly();\n\n  crear(datos: Omit<Empleado, 'id'>): void {\n    const id = Math.max(0, ...this.fuente().map((e) => e.id)) + 1;\n    this.fuente.update((lista) => [...lista, { ...datos, id }]);\n  }\n  // actualizar() y eliminar(): update() con map/filter (copia inmutable)\n}\n```\n\n`providedIn: 'root'` → singleton. Mutar con `update()` (nunca `push()`) cambia la referencia del array y toda la UI reacciona al instante.\n\n## Consigna paso a paso (checklist)\n\nAbrí el ejercicio (<http://localhost:4200/extras/05>) y probá: el filtro no filtra, el modal no precarga al editar, y guardar no hace nada. Cada `TODO: [Paso X]` del código corresponde a un paso de acá.\n\n- [ ] **Paso 1 — `empleados-page.ts`:** implementá `filtrados` como `computed()` real: nombre, email o área con `includes` (y `toLowerCase()` para no distinguir mayúsculas). Con filtro vacío, devolver todo.\n- [ ] **Paso 2 — `empleados-page.ts`:** implementá `paginados` (`slice` por `porPagina`), `totalPaginas` (`Math.ceil`, mínimo 1), `cambiarPagina(delta)` clampeado, y `alTipearFiltro(event)` (setear filtro + volver a página 1).\n- [ ] **Paso 3 — `empleados-page.ts`:** implementá `abrirNuevo()` (seleccionado `null`) y `abrirEdicion(empleado)`.\n- [ ] **Paso 4 — `empleados-page.ts`:** completá `confirmarEliminacion()`: `servicio.eliminar(id)` + reset de `eliminandoId` (la confirmación inline y su cancelación ya están hechas).\n- [ ] **Paso 5 — `modal-editor.ts`:** en un `effect()` dentro del constructor, precargá el form: con empleado → `patchValue(empleado)`; sin empleado (alta) → `reset()`.\n- [ ] **Paso 6 — `modal-editor.ts`:** implementá `confirmar()`: inválido → `markAllAsTouched()` y `return`; válido → `guardar.emit(getRawValue())`.\n- [ ] **Paso 7 — `empleados-page.ts`:** implementá `guardarCambios(datos)`: con `seleccionado()` → `actualizar({ ...datos, id })`; si no → `crear(datos)`; y cerrá el modal.\n- [ ] **Paso 8:** probá los criterios de aceptación de abajo.\n\n## Criterios de aceptación\n\nProbá en <http://localhost:4200/extras/05>:\n\n1. **Filtrado en vivo:** escribir \"ana\" reduce la tabla y vuelve a página 1.\n2. **Paginación:** \"‹ ›\" navega entre páginas, deshabilitado/clampeado en los extremos.\n3. **Modal:** \"Nuevo empleado\" abre el modal vacío; \"Editar\" lo abre **precargado** con los datos de la fila.\n4. **Validación:** guardar con campos vacíos marca los errores; guardar válido actualiza la fila al instante (signals).\n5. **Borrado:** pide confirmación inline en la fila; \"Sí\" borra, \"No\" cancela.\n6. **Singleton:** el servicio es `providedIn: 'root'`: ejercicio y solución comparten los mismos datos (probá: creá uno en el ejercicio y mirá la solución).\n7. **Cancelar:** cerrar el modal con Cancelar no altera la fila.\n\n## Solución\n\nLa versión resuelta y comentada está en `src/app/extras/05-crud-interactivo-con-modales/solucion/` y se navega en `/extras/05/solucion`.\n",
};

